(window.GIM_TS=window.GIM_TS||{})["Taanit.1"]={"from":24,"a":[["\u0003והא\u0004 \u0005[והרי]\u0006 \u0003שייר תיבה\u0004 (ארון הקודש), שלא הזכיר שבאחרונות מוציאים את ארון הקודש, לרחובה של עיר! את הטענה זו דוחים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום תיבה — לאו שיורא הוא\u0004 \u0005[אין זה שיור]\u0006 כי \u0003מילי\u0004 \u0005[דברים]\u0006 שב\u0003צינעא — קתני\u0004 \u0005[שנה]\u0006 ופירט את חלוקות התעניות, אולם \u0003מילי\u0004 \u0005[דברים]\u0006 ש\u0003בפרהסיא\u0004 שהכל רואים — \u0003לא קתני\u0004 \u0005[שנה].\u0006","\u0003אמר רב אשי: מתניתין נמי דיקא\u0004 \u0005[משנתנו גם כן מדוייקת]\u0006 כהסבר זה, \u0003דקתני\u0004 \u0005[ששנינו]:\u0006 \u0003מה אלו\u0004 התעניות האחרונות \u0003יתירות על\u0004 התעניות \u0003הראשונות? אלא שבאלו\u0004 האחרונות \u0003מתריעין\u0004 (צועקים, משמיעים קול) \u0003ונועלין את החנויות,\u0004 משמע: \u0003אבל בכל\u0004 שאר \u0003דבריהן, זה וזה שוין. וכי תימא הכא נמי תנא\u0004 \u0005[ואם תאמר\u0006 כי \u0005כאן גם כן שנה]\u0006 \u0003ושייר, והא\u0004 \u0005[והרי]\u0006 \u0003\"מה אלו\" קתני\u0004 \u0005[שנה],\u0006 לומר: שאלו ולא יותר.","ותוהים: \u0003ותסברא\u0004 \u0005[והאם סבור אתה]\u0006 ש\u0003\"מה אלו\"\u0004 בא לדייק ולומר כי \u0003דווקא הוא? והא\u0004 \u0005[והרי]\u0006 \u0003שייר לה\u0004 את הוצאת ה\u0003תיבה\u0004 החוצה שאינה אלא בתעניות האחרונות ועם כל זה לא הזכירה בחלוקות שבין הראשונות לאחרונות! ודוחים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום\u0004 ה\u0003תיבה לאו שיורא\u0004 \u0005[לא שיור]\u0006 \u0003הוא, משום דקא חשיב לה באידך פרקא\u0004 \u0005[שמנה,\u0006 דן בה, \u0005בפרק האחר]\u0006 ולכן לא צריך היה לפרט כאן את הדבר. ואומרים: \u0003השתא דאתית להכי\u0004 \u0005[עכשיו שהגעת לכאן]\u0006 לתירוץ זה, אם כן גם הקושיות הקודמות אינן קשות: \u0003עשרים וארבעה נמי לאו שיורא\u0004 \u0005[גם כן לא שיור]\u0006 \u0003הוא, דקתני לה באידך פרקא\u0004 \u0005[ש\u0006הרי \u0005שונה\u0006 אף \u0005אותה בפרק אחר],\u0006 ופירש שם בהרחבה את הברכות, וכאן מנה רק דברים שאינם נזכרים להלן.","וכיון שלא הבאנו הוכחה מכרעת לא לכאן ולא לכאן, \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה]\u0006 על בעיה זו, היכן מוסיף היחיד ביום התענית את תפילת \"עננו\"? \u0003אמר רב שמואל בר ססרטאי וכן אמר רב חייא בר אשי אמר רב:\u0004 אומר ברכה מיוחדת בתפילת שמונה עשרה \u0003בין\u0004 ברכת \"\u0003גואל\" ל\u0004ברכת \u0003\"רופא\", ורב אשי אמר משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' ינאי בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' ישמעאל:\u0004 מוסיף אותה בתוך ברכת \u0003\"שומע תפילה\".\u0004 ומסכמים: \u0003והלכתא\u0004 \u0005[וההלכה\u0006 היא\u0005]\u0006 כי מוסיף אותה \u0003ב\u0004ברכת \u0003\"שומע תפילה\".\u0004","\u0003תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]:\u0006 נשים \u0003עוברות\u0004 (הרות) \u0003ומיניקות — מתענות ב\u0004תעניות \u0003ראשונות\u0004 עם הציבור \u0003ואין מתענות באחרונות. ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]\u0006 שנשים אלה \u0003מתענות באחרונות ואין מתענות בראשונות. ותניא אידך\u0004 \u0005[ושנויה\u0006 עוד ברייתא \u0005אחרת]:\u0006 \u0003אין מתענות לא בראשונות ולא באחרונות.\u0004","\u0003אמר רב אשי: נקוט אמצעייתא בידך דמיתרצון כולהו\u0004 \u0005[קח את האמצעיות בידך ש\u0006על ידי כך \u0005מתורצות\u0006 הברייתות \u0005כולן].\u0006 כלומר, נשים אלה מתענות רק בתעניות האמצעיות, שחמורות הן מן הראשונות, ואין מתענות באחרונות מפני שהן מרובות מדי. ובאמת כל שלוש הברייתות לדבר אחד נתכוונו, שבברייתא הראשונה \"הראשונות\" הן באמת האמצעיות, שהן ראשונות לאחרונות, ו\"האחרונות\" הן האחרונות ממש, ובברייתא השניה הפירוש הוא ש\"הראשונות\" הן ראשונות ממש ו\"האחרונות\" הן האמצעיות, שהן אחרונות לגבי הראשונות, ובשלישית \"ראשונות\" ו\"אחרונות\" הן ראשונות ואחרונות ממש, ואכן אינן מתענות אף לפי שיטת ברייתא זו אלא באמצעיות. ולפי פירוש זה, תוכנן של כל הברייתות זהה.","שנינו במשנה: \u0003מה אלו\u0004 התעניות האחרונות \u0003יתירות על\u0004 התעניות \u0003הראשונות, אלא שבאלו\u0004 האחרונות \u0003מתריעין ונועלין את החנויות.\u0004 ושואלים: \u0003במאי\u0004 \u0005[במה]\u0006 \u0003מתריעין? רב יהודה אמר:\u0004 תוקעים \u0003בשופרות, ורב יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003רב שמואל בר שילת משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב אמר: ב\"עננו\",\u0004 שאומרים דברי תפילה המתחילים במלה \"עננו\".","ולפני שבאים לדון בדבר מסבירים: \u0003קא סלקא דעתן\u0004 \u0005[עלה בדעתנו],\u0006 כלומר, זו ההנחה ראשונה היתה ש\u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 מתריעים \u0003ב\"עננו\" — לא אמר,\u0004 כלומר, אינו סבור שמתריעים \u0003בשופרות, ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 כי מתריעים \u0003בשופרות לא אמר\u0004 שמתריעים \u0003ב\"עננו\",\u0004 ועל סמך הנחה זאת הקשו: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין פוחתין משבע תעניות על הצבור שבהן שמונה עשרה התרעות, וסימן לדבר יריחו. ו\u0004הרי \u0003יריחו\u0004 תקיעה ב\u0003שופרות הוה\u0004 \u0005[היה]\u0006 \u0003ותיובתא\u0004 \u0005[וקושיה חמורה]\u0006 \u0003למאן דאמר\u0004 \u0005[למי שאומר]\u0006 שמתריעים \u0003ב\"עננו\"!\u0004","\u0003אלא\u0004 יש להבין את המחלוקת בצורה אחרת: \u0003בשופרות דכולי עלמא לא פליגי דקרי לה\u0004 \u0005[לדעת הכל אין חלוקים שלכך קוראים]\u0006 \u0003התרעה,\u0004 ובודאי מתריעים בשופרות, \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 היה זה \u0003ב\u0004ענין \u0003\"עננו\". מר\u0004 \u0005[חכם זה]\u0006 \u0003סבר קרי לה\u0004 \u0005[\u0006ש\u0005קוראים לכך]\u0006 \u0003התרעה,\u0004 ולכן אומרים גם \"עננו\", \u0003ומר\u0004 \u0005[וחכם זה]\u0006 \u0003סבר לא קרי\u0004 \u0005[אינו קורא]\u0006 \u0003לה\u0004 ל\"עננו\" \u0003התרעה.\u0004","ותוהים: אם כך יוצא כי \u0003למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 שמתריעים (מתפללים) \u0003ב\"עננו\", כל שכן\u0004 שתוקעים \u0003בשופרות, ולמאן דאמר\u0004 \u0005[ול\u0006שיטת \u0005מי שאמר]\u0006 כי תוקעים \u0003בשופרות — אבל ב\"עננו\" לא!\u0004","משמע שתפילת \"עננו\" נאמרת רק במקרים חמורים ביותר, והיא התרעה גדולה יותר מאשר שופרות, \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ושאר כל מיני פורעניות המתרגשות\u0004 (הבאות) \u0003לעולם\u0004 שאינן חוסר גשם, כגון: \u0003חיכוך\u0004 (מחלה הגורמת לגירוי ולגירוד בעור), או \u0003חגב\u0004 שבא להשחית, \u0003זבוב וצירעה ויתושין\u0004 שנתרבו ביותר, או \u0003שילוח נחשים ועקרבים\u0004 החודרים למקומות ישוב — \u0003לא היו מתריעין\u0004 עליהם \u0003אלא צועקין.\u0004 ונדייק: \u0003מ\u0004כיון ש\u0003צעקה\u0004 היא לכל הדעות תפילה \u0003בפה,\u0004 הרי \u0003התרעה בשופרות\u0004 משמע. ואם כן מובן מכאן שהתרעה בשופרות חמורה יותר מאשר תפילה בפה, תפילת \"עננו\"!","ומשיבים: מחלוקת זו \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003על אלו מתריעין\u0004 אפילו \u0003בשבת: על עיר שהקיפוה גייס\u0004 (צבא של אויבים) \u0003או נהר\u0004 שעומד לשטוף אותה, \u0003ועל ספינה המטורפת\u0004 (העומדת לטבוע) \u0003בים. ר' יוסי אמר:\u0004 מתריעים \u0003לעזרה\u0004 במקום שסבורים שההתרעה הזו תביא עזרה מבני אדם, אבל \u0003לא לצעקה\u0004 אל ה'.","ונברר \u0003במאי\u0004 \u0005[במה]\u0006 מתריעים? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003בשופרות\u0004 — תקיעה \u0003בשופרות בשבת מי שרי\u0004 \u0005[האם מותרת]?\u0006 שהרי אף ראש השנה שחל בשבת אין תוקעין בו, \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 שמדובר \u0003ב\"עננו\", וקרי\u0004 \u0005[וקורא]\u0006 \u0003לה\u0004 התנא של ברייתא זו \u0003התרעה, שמע מינה\u0004 \u0005[למד ממנה]\u0006 שיש הסבור שהתרעה היא בפה, וכדברי רב יהודה בן רב שמואל בר שילת.","מסופר: \u0003בשני\u0004 \u0005[בשנותיו]\u0006 של \u0003ר' יהודה נשיאה הוה צערא\u0004 \u0005[היה צער],\u0006 מצוקה של הציבור,"],["\u0003גזר תלת\u0004 \u0005[שלוש]\u0006 \u0003עשרה תעניות ולא איעני\u0004 \u0005[נענה].\u0006 \u0003סבר למיגזר טפי\u0004 \u0005[לגזור עוד]\u0006 עד שייענו מן השמים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אמי: הרי אמרו אין מטריחין את הצבור יותר מדאי,\u0004 ואין קובעים יותר משלוש עשרה תעניות.","\u0003אמר ר' אבא בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא בר אבא: ר' אמי דעבד\u0004 \u0005[שעשה],\u0006 שפסק הלכה זו — \u0003לגרמיה\u0004 \u0005[לעצמו]\u0006 \u0003הוא דעבד\u0004 \u0005[שעשה],\u0006 כלומר, הוא עצמו לא רצה להתענות ודעתו בלבד היא זו ואינה דעת הרבים. \u0003אלא הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' חייא בר אבא אמר ר' יוחנן: לא שנו\u0004 גבול זה של שלוש עשרה תעניות \u0003אלא לגשמים, אבל לשאר מיני פורענויות — מתענין והולכין עד שיענו מן השמים.\u0004 ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003כשאמרו שלש וכשאמרו שבע — לא אמרו אלא ל\u0004ענין \u0003גשמים, אבל לשאר מיני פורענויות\u0004 — \u0003מתענין והולכין עד שיענו.\u0004","ושואלים: \u0003לימא תיהוי תיובתיה\u0004 \u0005[האם לומר\u0006 שברייתא זאת \u0005תהא קושיה חמורה]\u0006 על \u0003ר' אמי\u0004 שלא אמר כן! ומשיבים: \u0003אמר לך ר' אמי\u0004 \u0005[יכול היה ר' אמי לומר לך]:\u0006 \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 בענין זה, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין גוזרין יותר משלש עשרה תעניות על הצבור, לפי שאין מטריחין את הצבור יותר מדאי,\u0004 אלו \u0003דברי רבי. רבן שמעון בן גמליאל אומר: לא מן השם הוא זה,\u0004 כלומר, לא מטעם זה הוא הדבר \u0003אלא מפני\u0004 שאחרי שלוש עשרה תעניות כבר \u0003יצא זמנה של רביעה,\u0004 ואין טעם להתענות על הגשמים לאחר תקופת הגשם. ומדברי רבי שאמר \"אין מטריחין על הציבור\" נראה שהוא סבור שהטעם הוא משום הטרחת הציבור, ולאו דווקא משום עונת הגשמים וזוהי איפוא אף דעת ר' אמי. ואילו רבן שמעון בן גמליאל האומר כי הטעם הוא \"מפני שכבר יצא זמנה של רביעה\", נראה שהוא סבור שזהו דווקא בענין הגשם, אולם בשאר מיני פורעניות, לדעתו יש להתענות כפי הצורך ואפילו יותר משלוש עשרה, וכדבריו סובר אף ר' יוחנן.","בנושא קרוב לזה מסופר: \u0003שלחו ליה\u0004 \u0005[לו]\u0006 \u0003בני נינוה\u0004 שאלה זו \u0003לרבי: כגון אנן\u0004 \u0005[אנחנו]\u0006 ש\u0003אפילו בתקופת תמוז\u0004 (בעונת הקיץ) \u0003בעינן מטרא\u0004 \u0005[אנו צריכים גשם],\u0006 ובמקומותינו גשמים יורדים בכל השנה, \u0003היכי נעביד\u0004 \u0005[כיצד נעשה]\u0006 כאשר אין הגשמים יורדים בקיץ? האם \u0003כיחידים דמינן\u0004 \u0005[נחשבים אנו]\u0006 \u0003או כרבים דמינן\u0004 \u0005[נחשבים אנו]?\u0006 ומה ההבדל; \u0003כיחידים דמינן\u0004 \u0005[נחשבים אנו]\u0006 \u0003ו\u0004מזכירים את שאלת הגשם \u0003ב\"שומע תפלה\", או כרבים דמינן\u0004 \u0005[נחשבים אנו]\u0006 \u0003ו\u0004עלינו להזכיר את הגשמים \u0003בברכת השנים? שלח להו\u0004 \u0005[להם]\u0006 תשובה: \u0003כיחידים דמיתו\u0004 \u0005[נחשבים אתם]\u0006 \u0003וב\"שומע תפלה\"\u0004 יש לכם להזכיר.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו: \u0003אמר ר' יהודה: אימתי\u0004 אמרו זמני תעניות אלה וקביעות הברכות — \u0003בזמן שהשנים כתיקנן וישראל שרוין על אדמתן, אבל בזמן הזה —\u0004 שישראל מפוזרים בכל מקום, ואין הזמנים כתיקונם — \u0003הכל לפי השנים, הכל לפי המקומות, הכל לפי הזמן —\u0004 ומתפללים על הגשמים בברכת השנים לפי הצורך! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 וכי \u0003מתניתא רמית עליה\u0004 \u0005[\u0006מ\u0005ברייתא אתה מקשה עליו]\u0006 על \u0003רבי?!\u0004 הלא \u0003רבי\u0004 עצמו \u0003תנא הוא ופליג\u0004 \u0005[ו\u0006הוא \u0005חולק]\u0006 על דברי ר' יהודה.","ושואלים: הלכה למעשה \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה,\u0006 על שאלה זו\u0005]?\u0006 \u0003רב נחמן אמר:\u0004 שואלים \u0003בברכת השנים,\u0004 כשיטת ר' יהודה. \u0003רב ששת אמר: ב\"שומע תפלה\"\u0004 כשיטת רבי. ומסכמים: \u0003והלכתא\u0004 \u0005[ההלכה\u0006 למעשה\u0005]:\u0006 שואלים \u0003ב\"שומע תפלה\",\u0004 אם צריכים לגשמים בזמן שאינו עונת הגשמים בארץ ישראל.","שנינו במשנה: \u0003\"בשני\u0004 בשבת \u0003מטין עם חשיכה ובחמישי כל היום מפני כבוד השבת\". איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003היכי קתני\u0004 \u0005[כיצד שנה],\u0006 כלומר, כיצד יש להבין את דברי המשנה, האם פירושה כי \u0003בשני מטין\u0004 (פותחים מעט את דלתות החנויות) \u0003עם חשיכה, ובחמישי\u0004 מטים \u0003כל היום מפני כבוד השבת, או דילמא\u0004 \u0005[שמא]\u0006 \u0003בשני מטין\u0004 כל היום \u0003ובחמישי פותחים\u0004 לגמרי \u0003כל היום כולו?\u0004","ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 תשובה לדבר, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בשני מטין עד הערב, ובחמישי פותחין כל היום כולו מפני כבוד השבת. היו לו שני פתחים\u0004 בחנותו — \u0003פותח אחד ונועל אחד,\u0004 שהרי הוא מראה בכך שנועל קצת את חנותו, \u0003היתה לו אצטבא\u0004 (מבנה מוגבה שמסתיר את פתח החנות) \u0003כנגד פתחו — פותח כדרכו ואינו חושש,\u0004 שהרי לא נאסר הדבר משום מלאכה אלא כדי שלא ייראה שביום זה אוכלים ושותים.","שנינו במשנה: \u0003\"עברו אלו ולא נענו\u0004 — \u0003ממעטין במשא ומתן ובבנין ובנטיעה\". תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 בתוספתא: \u0003בבנין\u0004 — כוונתו \u0003בנין של שמחה,\u0004 ולא כל בנין. \u0003נטיעה — נטיעה של שמחה\u0004 ולא כל נטיעה. ומסבירים: \u0003אי זהו בנין של שמחה — זה הבונה בית חתנות לבנו,\u0004 שהיו נוהגים לבנות לבן המתחתן בית שבו היו עורכים את סעודת הנישואים, ובו היו גרים בני הזוג במשך זמן מסויים. \u0003אי זו היא נטיעה של שמחה — זה הנוטע אבוורנקי של מלכים\u0004 (גן מפואר שאיננו עשוי לתועלת אלא לנוי בלבד).","שנינו במשנה, שאסורים \u0003\"בשאילת שלום\". תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003חברים\u0004 (תלמידי חכמים) \u0003אין שאילת שלום ביניהן\u0004 כלל. \u0003עמי הארץ ששואלין\u0004 כיון שאינם יודעים שאין ראוי לשאול — \u0003מחזירין להם בשפה רפה,\u0004 כלומר, בשקט \u0003ובכובד ראש\u0004 (ברצינות), כפי שעונה אדם שהוא אבל או לבו כבד עליו. \u0003והן מתעטפין ויושבין כאבלים וכמנודין, כבני אדם הנזופין למקום,\u0004 שהרי רואים שמשמים כועסים עליהם, \u0003עד שירחמו עליהם מן השמים.\u0004","\u0003אמר ר' אלעזר: אין אדם חשוב רשאי ליפול על פניו\u0004 ולבזות בכך את עצמו בפני הציבור, \u0003אלא אם כן\u0004 יודע שהוא \u0003נענה כיהושע בן נון, שנאמר: \"ויאמר ה' אל יהושע קם לך למה זה אתה נפל על פניך\"\u0004 (יהושע ז, י). ומי שאיננו בטוח שכך יענו לו — אינו ראוי שיפול, שכן יהיה בכך בזיון אם הוא נופל על פניו ואיננו נענה.","וכן \u0003אמר ר' אלעזר: אין אדם חשוב רשאי לחגור שק\u0004 לאבל ולבקשת רחמים \u0003אלא אם כן נענה כיהורם בן אחאב, שנאמר: \"ויהי כשמע המלך את דברי האשה ויקרע את בגדיו והוא עבר על החמה וירא העם והנה השק על בשרו\u0004 מבית\u0003\"\u0004 (מלכים ב' ו, ל), ואחר כך מסופר כיצד היתה תשועה לישראל.","\u0003ואמר ר' אלעזר: לא הכל בקריעה ולא הכל בנפילה,\u0004 שלא כל אדם ראוי לו לקרוע בגדיו או ליפול על פניו כאשר יש פורענות וצריך לגלות צער. ומה עניינו? \u0003משה ואהרן בנפילה,\u0004 שהם ראוי היה להם ליפול על פניהם, \u0003יהושע וכלב\u0004 שהיו תלמידיהם — \u0003בקריעה.\u0004 ומפרטים את מקור הדברים: \u0003משה ואהרן בנפילה — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויפל משה ואהרן על פניהם\"\u0004 (במדבר יד, ה), \u0003יהושע וכלב בקריעה — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויהושע בן נון וכלב בן יפנה\u0004 מן התרים את הארץ \u0003קרעו בגדיהם\"\u0004 (במדבר יד, ו).","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 על דבר זה \u0003ר' זירא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003ר' שמואל בר נחמני: אי הוה כתיב\u0004 \u0005[אילו נאמר]\u0006 במקרא \u0003\"יהושע\u0004 וכלב\" בלא ו' החיבור — היה אכן הפירוש \u0003כדקאמרת\u0004 \u0005[כפי שאמרת],\u0006 שמשה ואהרן בנפילה ואילו יהושע וכלב בקריעה בלבד, \u0003השתא דכתיב\u0004 \u0005[עכשיו שנאמר]:\u0006 \u0003\"ויהושע\" —\u0004 ב־ו' החיבור, אפשר שה־ו' באה להוסיף על ענין ראשון, שמשה ואהרן בנפילה בלבד, ויהושע וכלב \u0003הא והא עביד\u0004 \u0005[זה וזה עשה]\u0006 שגם נפלו וגם קרעו.","\u0003ו\u0004כיוצא בו \u0003אמר ר' אלעזר: לא הכל בקימה ולא הכל בהשתחויה\u0004 לעתיד לבוא, אלא \u0003מלכים — בקימה, ושרים — בהשתחויה. מלכים בקימה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כה אמר ה' גאל ישראל קדושו\u0004"],["\u0003לבזה נפש למתעב גוי לעבד משלים מלכים יראו וקמו\"\u0004 (ישעיהו מט, ז), \u0003ושרים בהשתחויה — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"שרים וישתחוו\"\u0004 (ישעיהו מט, ז). \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' זירא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהקשה זאת \u0003ר' שמואל בר נחמני: אי הוה כתיב\u0004 \u0005[אילו נאמר]\u0006 \u0003\"ושרים ישתחוו\",\u0004 היה אכן הפירוש \u0003כדקאמרת\u0004 \u0005[כפי שאמרת],\u0006 אולם \u0003השתא דכתיב\u0004 \u0005[עכשיו שנאמר\u0006 שם\u0005]\u0006 \u0003\"שרים וישתחוו\" —\u0004 יש לפרש: השרים \u0003הא והא עבוד\u0004 \u0005[זה וזה עשו].\u0006","\u0003אמר רב נחמן בר יצחק: אף אני אומר\u0004 על דרך זו, \u0003לא הכל לאורה ולא הכל לשמחה, צדיקים —\u0004 זוכים \u0003לאורה, וישרים — לשמחה. צדיקים לאורה — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אור זרע לצדיק\"\u0004 (תהלים צז, יא). \u0003ולישרים שמחה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ולישרי לב שמחה\"\u0004 (תהלים צז, יא).","","\u0003סדר\u0004 ההנהגה ב\u0003תעניות כיצד? מוציאין את התיבה\u0004 (ארון הקודש) שהיה בימיהם מיטלטל וכרגיל היו מעמידים אותו בחדר נעול סמוך לאולם בית הכנסת, ואילו בתענית מוציאים את התיבה \u0003לרחובה של עיר, ונותנין אפר מקלה\u0004 (אפר של שריפה) \u0003על גבי התיבה\u0004 כאות אבל, \u0003ו\u0004כן נותנים אפר \u0003בראש הנשיא, ובראש אב בית דין, וכל אחד ואחד\u0004 מן הציבור \u0003נותן בראשו.\u0004","\u0003הזקן שבהן\u0004 שבציבור זה, \u0003אומר לפניהן דברי כבושין\u0004 (דברי מוסר) וכעין דברים אלה: \u0003אחינו! לא נאמר באנשי נינוה \"וירא אלהים את שקם ואת תעניתם\", אלא\u0004 נאמר בהם: \u0003\"וירא האלהים את מעשיהם כי שבו מדרכם הרעה\"\u0004 (יונה ג, י), \u0003ובקבלה\u0004 (בדברי הנביאים) \u0003הוא אומר: \"וקרעו לבבכם ואל בגדיכם\u0004 ושובו אל ה'\u0003\"\u0004 (יואל ב, יג), ללמדנו שיש לחזור בתשובה בפועל ולתקן את המעשה, ולא די בתפילה ובתענית בלבד.","\u0003עמדו בתפלה\u0004 — \u0003מורידין לפני התיבה\u0004 כשליח ציבור אדם שהוא \u0003זקן, ורגיל\u0004 בתפילה, \u0003ויש לו בנים, וביתו ריקם,\u0004 וכל זאת \u0003כדי שיהא לבו שלם בתפלה.\u0004 שכיון שהוא דואג לעצמו ולבני משפחתו, הריהו מתפלל בלב שלם על מה שנזקק לו הציבור.","\u0003ואומר לפניהן\u0004 שליח הציבור \u0003עשרים וארבע ברכות: שמונה עשרה\u0004 ברכות שאומרים \u0003בכל יום, ומוסיף עליהן עוד שש. ואלו הן:\u0004 אומר פסוקי \u0003זכרונות ושופרות,\u0004 כדרך שאומרים בראש השנה, ומוסיף ואומר מזמורי תהלים אלה: \u0003\"אל ה' בצרתה לי קראתי ויענני\"\u0004 (תהלים קכ, א), \u0003\"אשא עיני אל ההרים\u0004 מאין יבא עזרי\u0003\"\u0004 (תהלים קכא, א), \u0003\"ממעמקים קראתיך ה'\"\u0004 (תהלים קל, א), \u0003\"תפלה לעני כי יעטף\"\u0004 (תהלים קב, א).","\u0003ר' יהודה אומר: לא היה צריך לומר זכרונות ושופרות, אלא אומר תחתיהן\u0004 פרשת \u0003\"רעב כי יהיה בארץ דבר כי יהיה\"\u0004 (מלכים א' ח, לז). וכן אומר \u0003\"אשר היה דבר ה' אל ירמיהו על דברי הבצרות\"\u0004 (ירמיהו יד, א).","\u0003ואומר\u0004 בשש ברכות אלה את \u0003חותמיהן,\u0004 שמוסיף להם לנוסח כל ברכה חתימה מיוחדת, \u0003על הראשונה\u0004 שבהן שהיא ברכת \"גואל ישראל\" שמאריך בה ומוסיף בה, \u0003הוא אומר\u0004 בחתימתו: \u0003\"מי שענה את אברהם בהר המוריה הוא יענה אתכם וישמע בקול צעקתכם היום הזה. ברוך אתה ה' גואל ישראל\". על השניה\u0004 שבה הוא מוסיף פסוקי זכרונות \u0003הוא אומר: \"מי שענה את אבותינו על ים סוף הוא יענה אתכם וישמע קול צעקתכם היום הזה, ברוך אתה ה' זוכר הנשכחות\".\u0004 \u0003על\u0004 הברכה \u0003השלישית\u0004 שבה הוא מוסיף פסוקי השופרות \u0003הוא אומר\u0004 בחתימה: \u0003\"מי שענה את יהושע בגלגל\u0004 ובתקיעת שופרות יריחו (יהושע פרקים ה-ו) \u0003הוא יענה אתכם וישמע בקול צעקתכם היום הזה, ברוך אתה ה' שומע תרועה\". על הרביעית הוא אומר: \"מי שענה את שמואל במצפה\u0004 (שמואל א' פרק ז) \u0003הוא יענה אתכם וישמע בקול צעקתכם היום הזה, ברוך אתה ה' שומע צעקה\". על החמישית הוא אומר: \"מי שענה את אליהו בהר הכרמל\u0004 (מלכים א' פרק יח) \u0003הוא יענה אתכם וישמע בקול צעקתכם היום הזה, ברוך אתה ה' שומע תפלה\".\u0004","","\u0003על הששית הוא אומר: \"מי שענה את יונה ממעי הדגה, הוא יענה אתכם וישמע בקול צעקתכם היום הזה, ברוך אתה ה' העונה בעת צרה\". על השביעית\u0004 (שכן הברכה הראשונה לא היתה ברכה נוספת אלא ברכת \"גואל ישראל\" שהיתה מוגדלת ומוארכת, והשביעית היא הברכה השישית הנוספת) \u0003הוא אומר: \"מי שענה את דוד ואת שלמה בנו בירושלים, הוא יענה אתכם וישמע בקול צעקתכם היום הזה, ברוך אתה ה' המרחם על הארץ\".\u0004","\u0003מעשה\u0004"],["\u0003בימי ר' חלפתא ור' חנניא בן תרדיון שעבר אחד לפני התיבה וגמר את הברכה כולה, ולא ענו אחריו\u0004 העם \u0003אמן.\u0004 ואמר שמש בית הכנסת: \u0003תקעו הכהנים! ותקעו.\u0004 ואז אמר: \u0003\"מי שענה את אברהם אבינו בהר המוריה הוא יענה אתכם וישמע בקול צעקתכם היום הזה\",\u0004 ואמר: \u0003הריעו בני אהרן! — הריעו.\u0004 ואז אמר: \u0003\"מי שענה את אבותינו על ים סוף הוא יענה אתכם וישמע בקול צעקתכם היום הזה\",\u0004 וכן הלאה.","\u0003וכשבא\u0004 ה\u0003דבר אצל חכמים,\u0004 מה שעשו ר' חלפתא ור' חנניא, \u0003אמרו: לא היינו נוהגין כן\u0004 לעשות באופן זה שלא לענות אמן אחר הברכה, \u0003אלא בשער מזרח\u0004 של בית המקדש \u0003ובהר הבית,\u0004 אבל אין עושים טכס זה בכל פרטיו אלא במקדש ולא מחוצה לו.","בענין תעניות הציבור נאמר: \u0003שלש תעניות הראשונות אנשי משמר\u0004 של הכהנים, אותם המשמשים במקדש באותו שבוע שהיו בו התעניות \u0003מתענין,\u0004 אבל \u0003לא משלימין\u0004 את תעניתם. \u0003ואנשי בית אב\u0004 שצריכים לעבוד עבודת הקודש באותו יום \u0003לא היו מתענין כלל.\u0004 אם היה זה יום צום ב\u0003שלש\u0004 תעניות \u0003שניות, אנשי משמר מתענין ומשלימין, ואנשי בית אב מתענין ולא משלימין.\u0004 ואילו ב\u0003שבע\u0004 תעניות \u0003אחרונות — אלו ואלו מתענין ומשלימין,\u0004 אלו \u0003דברי ר' יהושע.\u0004","\u0003וחכמים אומרים: שלש תעניות הראשונות — אלו ואלו\u0004 גם אנשי משמר וגם אנשי בית אב \u0003לא היו מתענין כלל, שלש שניות — אנשי משמר מתענין ולא משלימין, ואנשי בית אב לא היו מתענין כלל. שבע אחרונות — אנשי משמר מתענין ומשלימין, ואנשי בית אב מתענין ולא משלימין.\u0004","כיון שהזכרנו את מנהגם של אנשי משמר בזמן הבית מעירים על הבדל נוסף ביניהם: \u0003אנשי משמר מותרין לשתות יין בלילות אבל לא בימים, ואנשי בית אב\u0004 שעובדים בו ביום, אינם שותים יין \u0003לא ביום ולא בלילה\u0004 (שבו מקריבים את האימורים), שהרי אסור לכהנים לעבוד כשהם שתויי יין. ועוד הלכה כללית: \u0003אנשי משמר ואנשי מעמד\u0004 שהם הישראלים שהיו מצטרפים לכל משמר כהנים ובאותו שבוע היו עוסקים בדברי תפילה ותחינה \u0003אסורין מלספר ומלכבס\u0004 כל אותו שבוע של משמרם, \u0003וב\u0004יום ה\u0003חמישי מותרין, מפני כבוד השבת.\u0004","ולענין תעניות בכלל: \u0003כל\u0004 יום \u0003הכתוב במגלת תענית\u0004 שנאמר בו \u0003\"דלא למספד\"\u0004 \u0005[שלא לספוד]\u0006 ביום זה — גם יום \u0003לפניו אסור\u0004 בהספד, אולם ביום ש\u0003לאחריו\u0004 — \u0003מותר. ר' יוסי אומר:\u0004 גם ש\u0003לפניו\u0004 וגם ש\u0003לאחריו אסור.\u0004","ואילו יום שנאמר בו רק \u0003\"דלא להתענאה\" —\u0004 \u0005[שאסור להתענות\u0006 בו\u0005],\u0006 \u0003לפניו ולאחריו מותר.\u0004 ואילו \u0003ר' יוסי אומר: לפניו — אסור, לאחריו — מותר.\u0004","ועוד אמרו: \u0003אין גוזרין תענית על הצבור בתחילה ב\u0004יום \u0003חמישי,\u0004 כדי \u0003שלא להפקיע\u0004 את \u0003השערים,\u0004 שכן בסוף התענית ירבו הבאים לקנות, וכיון שרבים באים לקנות אוכל, גם לצורך היום וגם לכבוד השבת, עלולים המוכרים להפקיע את השערים ולהעלות מחירים. \u0003אלא שלש תעניות הראשונות\u0004 לפי הסדר: \u0003שני וחמישי ושני, ושלש שניות חמישי שני וחמישי. ר' יוסי אומר: כשם שאין הראשונות\u0004 מתחילות \u0003בחמישי כך לא שניות ולא אחרונות,\u0004 אלא מתחילים תמיד בשני.","ועוד אמרו: \u0003אין גוזרין תענית על הצבור בראשי חדשים, בחנוכה, ובפורים. ואם התחילו\u0004 להתענות באיזה שהוא מחזור תעניות קודם לכן ואירע שאחד מימי הצום חל בראש חודש חנוכה או פורים — \u0003אין מפסיקין,\u0004 ומתענים גם באותם ימים, אלו \u0003דברי רבן גמליאל. אמר ר' מאיר: אף על פי שאמר רבן גמליאל אין מפסיקין — מודה היה ש\u0004בימים אלה, הקרוים מועד, \u0003אין משלימין\u0004 את התענית. \u0003וכן תשעה באב שחל להיות בערב שבת\u0004 אין משלימים בו את הצום אלא אוכלים משהו לפני כניסת השבת, כדי שלא להיכנס לשבת מתוך תענית.","שנינו במשנה: \u0003סדר\u0004 ה\u0003תעניות כיצד? מוציאין את התיבה כו'\".\u0004 ושואלים: \u0003ואפילו בקמייתא\u0004 \u0005[ב\u0006תעניות \u0005ראשונות]\u0006 עושים כן? \u0003ורמינהו\u0004 \u0005[משליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003שלש תעניות ראשונות ו\u0004כן \u0003שניות נכנסים לבית הכנסת, ומתפללין כדרך שמתפללין כל השנה כולה\u0004","\u0003ו\u0004רק \u0003בשבע אחרונות מוציאין את התיבה לרחובה של עיר, ונותנין אפר על גבי התיבה ובראש הנשיא ובראש אב בית דין, וכל אחד ואחד נוטל ונותן בראשו. ר' נתן אומר: אפר מקלה הן מביאין,\u0004 ולא אפר אחר. הרי שאפר זה הוא רק באחרונות! \u0003אמר רב פפא:\u0004 יש לומר, \u0003כי תנן נמי מתניתין\u0004 \u0005[כאשר שנינו גם כן במשנתנו]\u0006 על ה\u0003שבע\u0004 ה\u0003אחרונות תנן\u0004 \u0005[שנינו],\u0006 שבהן עושים סדר מיוחד זה, ולא בראשונות.","שנינו במשנה שנותנים אפר \u0003בראש הנשיא\u0004 ובראש אב בית דין, \u0003והדר תני\u0004 \u0005[וחזר ושנה]\u0006 \u0003כל אחד ואחד נוטל ונותן בראשו.\u0004 ותוהים: \u0003איני\u0004 \u0005[\u0006האם \u0005כן הוא]\u0006 הסדר הראוי?! \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003רבי אומר: בגדולה\u0004 בכל מקום שיש בו ענין של גדולה או נתינת כבוד \u0003מתחילין\u0004 את הדבר \u0003מן הגדול ש\u0004באותה חבורה, \u0003וב\u0004כל מקום שיש בו \u0003קללה\u0004 וביזוי \u0003מתחילין מן\u0004","\u0003הקטן.\u0004 וראיה לדבר ש\u0003בגדולה מתחילין מן הגדול — שנאמר: \"ויאמר משה אל אהרן ולאלעזר ולאיתמר\".\u0004 (ויקרא י, ו), הרי שמתחילים מן החשוב שבכולם לכבדו (כאמור: \"כי שמן משחת ה' עליכם\", ויקרא י, ז). \u0003ובקללה מתחילין מן הקטן — ש\u0004\u0003(אמר מר)\u0004 \u0005[החכם]:\u0006 \u0003בתחלה נתקלל\u0004 ה\u0003נחש, ואחר כך נתקללה חוה, ואחר כך נתקלל אדם!\u0004 ומדוע בתעניות מתחילים בביטוי אבל וצער מגדולי העדה?","ומשיבים: \u0003הא חשיבותא לדידהו\u0004 \u0005[זו\u0006 משום \u0005חשיבות\u0006 היא \u0005להם]\u0006 ויש בכך גם כבוד, \u0003דאמרי להו\u0004 \u0005[שאומרים להם],\u0006 כלומר, רומזים על ידי מעשה זה: \u0003אתון חשיביתו למיבעי עלן רחמי אכולי עלמא\u0004 \u0005[אתם חשובים לבקש עלינו רחמים על כל העולם]\u0006 ולכן ראוי להתחיל בהם.","שנינו במשנה: \u0003וכל אחד ואחד נותן בראשו,\u0004 וכן \u0003אמר רב אדא: וכל אחד ואחד נוטל ונותן בראשו,\u0004 ושואלים: \u0003נשיא ואב בית דין נמי נשקלו אינהו ונינחו בראשייהו\u0004 \u0005[גם כן, יקחו הם ויניחו בראשיהם]\u0006 בעצמם, \u0003מאי שנא דשקיל איניש אחרינא ומנח להו\u0004 \u0005[במה שונה,\u0006 מדוע, \u0005לוקח אדם אחר ומניח להם]\u0006 ולא הם עצמם? \u0003אמר ר' אבא דמן קסרי:\u0004 עושים זאת בכוונה, כי \u0003אינו דומה מתבייש מעצמו\u0004 שנותן אפר בראש עצמו"],["\u0003למתבייש מאחרים,\u0004 שאז בזיונו מרובה. וכיון שרוצים שראשי העדה יראו צער בעצמם, לכך אחרים מניחים להם את האפר. ושואלים: \u0003והיכא מנח להו\u0004 \u0005[והיכן מניחים להם]\u0006 את האפר? \u0003אמר רב יצחק: במקום\u0004 הנחת \u0003תפילין\u0004 של ראש. וראייה לדבר ממה \u0003שנאמר: \"לשום לאבלי ציון לתת להם פאר תחת אפר\"\u0004 (ישעיהו סא, ג), משמע שנתינת האפר צריכה להיות במקום נתינת הפאר, שכמקובל בידינו הוא כינוי לתפילין.","\u0003\"רחוב, תיבה, ושקים, אפר, אפר, קבורה, ומוריה\" סימן\u0004 לטעמי ההלכה הבאים. ושואלים לטעמי הדברים שעושים בתענית: \u0003למה יוצאין לרחוב? ר' חייא בר אבא אמר: לומר\u0004 על ידי כך באופן סמלי: \u0003זעקנו בצנעא\u0004 בבית הכנסת \u0003ולא נענינו, נבזה עצמנו בפרהסיא\u0004 ובכך תישמע ותתקבל זעקתנו.","\u0003ריש לקיש אמר:\u0004 הסמל שבדבר הוא, שהם כאומרים: \u0003גלינו,\u0004 תהא איפוא \u0003גלותינו מכפרת עלינו,\u0004 ושואלים \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל ביניהם\u0005]\u0006 למעשה אם זה או זה הטעם? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל \u0003דגלי מבי כנישתא לבי כנישתא\u0004 \u0005[שגולה מבית כנסת\u0006 אחד \u0005לבית כנסת\u0006 אחר\u0005]\u0006 שלטעמו של ריש לקיש, כיון שגלות היא זו — די בכך, ולטעמו של ר' חייא בר אבא אף שגלות היא זו, מכל מקום כיון שהיא בצינעה אין די בכך.","\u0003ולמה מוציאין את התיבה\u0004 (ארון הקודש) \u0003לרחובה של עיר? אמר ר' יהושע בן לוי, לומר\u0004 על ידי כך: \u0003כלי צנוע היה לנו,\u0004 שתמיד נמצא בסתר, \u0003ונתבזה בעוונינו.\u0004","\u0003ולמה מתכסין בשקים? אמר ר' חייא בר אבא : לומר\u0004 לך \u0003הרי אנו חשובין כבהמה,\u0004 ששקים אלה עשויים משערה. \u0003ולמה נותנין אפר מקלה על גבי תיבה? אמר ר' יהודה בן פזי: כלומר,\u0004 כאילו אנו אומרים בשם הקדוש ברוך הוא: \u0003\"עמו אנכי בצרה\"\u0004 (תהלים צא, טו). \u0003ריש לקיש אמר\u0004 אותו רעיון מכתוב אחר: \u0003\"בכל צרתם לו צר\"\u0004 (ישעיהו סג, ט) וכך כביכול משתפים את הקדוש ברוך הוא (שארון הקודש הוא סמל לנוכחותו) בצערם של ישראל. ומספרים: \u0003אמר ר' זירא: מריש כי הוה חזינא להו לרבנן דיהבי\u0004 \u0005[מתחילה כאשר הייתי רואה אותם,\u0006 את \u0005החכמים\u0006 שהם \u0005מניחים]\u0006 \u0003אפר מקלה על גבי תיבה — מזדעזע לי כוליה גופאי\u0004 \u0005[היה מזדעזע כל גופי]\u0006 מחמת התרגשות.","\u0003ולמה נותנין אפר בראש כל אחד ואחד? פליגי בה\u0004 \u0005[חלקו בכך]\u0006 \u0003ר' לוי בר חמא ור' חנינא. חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר\u0004 בטעם הדבר, שהוא כאילו היו אומרים: \u0003הרי אנו חשובין לפניך כאפר, וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר: כדי שיזכור לנו\u0004 הקדוש ברוך הוא \u0003אפרו של יצחק\u0004 אבינו, ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 אם זה או זה הטעם? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל לגבי נתינת \u0003עפר סתם.\u0004 שעפר סתם איננו מזכיר את קרבנו של יצחק, ורק מסמל התבטלות.","\u0003למה יוצאין\u0004 ביום התענית \u0003לבית הקברות? פליגי בה\u0004 \u0005[נחלקו בכך]\u0006 \u0003ר' לוי בר חמא ור' חנינא. חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר,\u0004 כי דבר זה בא לסמל: \u0003הרי אנו חשובין לפניך כמתים, וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר,\u0004 שהולכים לבתי הקברות \u0003כדי שיבקשו עלינו\u0004 ה\u0003מתים רחמים.\u0004 ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 למעשה? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל לענין הליכה אצל \u0003קברי גוים.\u0004 שאם הכוונה להראות עצמם כמתים — די בכך, אבל אם רוצים שיבקשו עלינו רחמים — הולכים דווקא לקברי ישראל.","כיון שהבאנו דברים אלה שנחלקו בהם ר' לוי בר חמא ור' חנינא מביאים גם נושא אחר שנחלקו בו, \u0003מאי\u0004 \u0005[מה]\u0006 משמעות \u0003הר המוריה,\u0004 מדוע נקרא כך? \u0003פליגי בה\u0004 \u0005[חלקו בכך]\u0006 \u0003ר' לוי בר חמא ור' חנינא. חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר: הר שיצא ממנו הוראה לישראל,\u0004 שהרי היא מקום הסנהדרין, מורי כל ישראל ולכן נקרא \"מוריה\", מלשון מורה. \u0003וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר: הר שיצא ממנו מורא\u0004 (אימה) \u0003לגוים,\u0004 שכן באותו מקום נבחרו ישראל להקדוש ברוך הוא, ו\"מוריה\" מלשון מורא.","שנינו במשנה: \u0003הזקן שבהן אומר לפניהן דברי כיבושין. תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003אם יש\u0004 שם \u0003זקן — אומר זקן, ואם לאו\u0004 \u0005[לא] —\u0006 \u0003אומר חכם, ואם לאו — אומר אדם של צורה,\u0004 אדם העושה רושם בצורתו ובמראהו. ושואלים: כיון שהזקן קודם לחכם לענין זה, \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003זקן דקאמרי\u0004 \u0005[שאמרנו]\u0006 בתחילה \u0003אף על גב דלאו\u0004 \u0005[אף על פי שלא]\u0006 \u0003חכם הוא\u0004 ומעדיפים מלכתחילה כל אדם הזקן בשנים? \u0003אמר אביי: הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש להבין את הדבר: \u0003אם יש\u0004 שם \u0003זקן והוא\u0004 גם \u0003חכם — אומר זקן והוא חכם, ואם לאו —\u0004 שאין שם זקן חכם — \u0003אומר חכם\u0004 גם אם הוא צעיר, \u0003ואם לאו,\u0004 שאין שם חכם — \u0003אומר אדם של צורה.\u0004","ומה הוא אומר: \u0003אחינו, לא שק ותענית גורמים\u0004 לכפרת עוונות והיפוך הדין לטובה, \u0003אלא תשובה ומעשים טובים גורמים. שכן מצינו באנשי נינוה שלא נאמר בהם \"וירא האלהים את שקם ואת תעניתם\", אלא \"וירא האלהים את מעשיהם כי שבו מדרכם הרעה\"\u0004 (יונה ג, י).","אגב הזכרת תשובת אנשי נינוה מביאים מה שנאמר בהם: \u0003\"ויתכסו שקים האדם והבהמה\"\u0004 (יונה ג, ח), \u0003מאי הוו עבדי\u0004 \u0005[מה היו עושים]?\u0006 \u0003אסרא\u0004 \u0005[אוסרים]\u0006 את \u0003הבהמות\u0004 האמהות \u0003לחוד ואת הוולדות לחוד, אמרו לפניו: רבונו של עולם! אם אין אתה מרחם עלינו — אין אנו מרחמים על אלו,\u0004 ואם אין אנו ראויים לרחמים — בעלי החיים לפחות ראויים לרחמים.","נאמר עוד באנשי נינוה: \u0003\"ויקראו אל אלהים בחזקה\"\u0004 (יונה ג, ח), ושואלים: \u0003מאי אמור\u0004 \u0005[מה אמרו]?\u0006 אלו דברים אמרו שאפשר לקרוא להם \"בחזקה\"? \u0003אמרו לפניו: רבונו של עולם! עלוב ושאינו עלוב, צדיק ורשע — מי נדחה מפני מי?\u0004 ודאי הצדיק מוותר לרשע, ואף אתה ראוי לך שתרחם עלינו.","נאמר: \u0003\"וישבו איש מדרכו הרעה ומן החמס אשר בכפיהם\"\u0004 (יונה ג, ח), \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ומן החמס אשר בכפיהם\"? אמר שמואל: אפילו גזל\u0004 אדם \u0003מריש\u0004 (קורה) \u0003ובנאו בבירה\u0004 (בבנין) — \u0003מקעקע\u0004 (שובר, הורס) את \u0003כל הבירה כולה ומחזיר\u0004 את ה\u0003מריש לבעליו,\u0004 אף על פי שמתקנת חכמים אפשר להחזיר רק את תמורתו הכספית, אלא רצו לעשות תשובה שלימה ומעולה, שלא ישאר בידם שום דבר מן הגזל.","באותו ענין \u0003אמר רב אדא בר אהבה: אדם שיש בידו עבירה, ומתודה ואינו חוזר בה, למה הוא דומה — לאדם שתופס\u0004 (שמחזיק) \u0003שרץ\u0004 מת \u0003בידו,\u0004 שהוא מטמא את הנוגע בו, \u0003שאפילו\u0004 אם הוא \u0003טובל בכל מימות שבעולם — לא עלתה לו טבילה,\u0004 שהרי הטומאה עדיין בידו היא. \u0003זרקו מידו, כיון שטבל בארבעים סאה\u0004 בלבד — \u0003מיד עלתה לו טבילה,\u0004","\u0003שנאמר: \"ומודה ועזב ירחם\"\u0004 (משלי כח, יג), משמע שלא די להיות מודה, אלא צריך לעזוב את חטאו ומיד כשהוא עוזב — הרי הוא מרוחם. \u0003ואומר: \"נשא לבבנו אל כפים אל אל בשמים\"\u0004 (איכה ג, מא). כלומר, לא די לשאת את הכפיים בתפילה, אלא צריך גם לשאת את הלב ולחזור בתשובה.","שנינו במשנה: \u0003עמדו בתפלה מורידין לפני התיבה זקן\u0004 ורגיל ויש לו בנים וביתו ריקם, כדי שיהיה לבו שלם בתפילה\u0003. תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003עמדו בתפלה, אף על פי שיש שם זקן וחכם — אין מורידין לפני התיבה\u0004 את הגדול בחכמה דווקא, \u0003אלא אדם הרגיל\u0004 בתפילה. \u0003(איזהו רגיל)\u0004 בענין זה? \u0003ר' יהודה אומר: מטופל\u0004 בילדים \u0003ואין לו\u0004 במה לפרנסם, \u0003ויש לו יגיעה בשדה\u0004 ותחינתו לגשם תהיה בודאי מתוך כוונה גדולה, \u0003וביתו ריקם,\u0004","\u0003ופרקו נאה, ושפל ברך\u0004 (עניו, המשפיל את עצמו), \u0003ומרוצה לעם\u0004 שחביב על הבריות ורצוי להם, \u0003ויש לו נעימה\u0004 (שבקי בנגינה), \u0003וקולו ערב, ובקי לקרות בתורה ובנביאים ובכתובים, ולשנות במדרש בהלכות ובאגדות, ובקי בכל הברכות כולן.\u0004 מובן שאדם שיש בו כל המעלות הללו איננו מצוי, ומסופר: \u0003ויהבו ביה רבנן עינייהו\u0004 \u0005[ונתנו החכמים עיניהם]\u0006 כאשר דיברו באדם כגון זה \u0003בר' יצחק בר אמי,\u0004 שבו היו כל התכונות הטובות הללו."],["\u0003היינו\u0004 \u0005[זהו]\u0006 \u0003\"מטופל\" ואין לו, היינו\u0004 \u0005[זהו]\u0006 \u0003\"ביתו ריקם\"! —\u0004 ולשם מה החזרה? ומשיבים: \u0003אמר רב חסדא:\u0004 \"אין לו\" משמעו אכן בענין ממון, אולם \"ביתו ריקם\" אינו בענין ממון, אלא \u0003זהו שביתו ריקם מן העבירה,\u0004 שאין עבירה הקשורה בביתו. שנינו במשנה כי אחד מן התכונות של היורד לפני התיבה צריכה להיות שיהיה \u0003\"פרקו נאה\",\u0004 ומסבירים מה פירוש הביטוי, \u0003אמר אביי: זה שלא יצא לו\u0004 (עליו) \u0003שם רע בילדותו.\u0004 שכאשר הגיע לפרקו, לבגרותו, ולא היה עליו שם רע.","ואגב מה שאמרו על שליח הציבור הראוי, מביאים כניגוד על הכתוב \u0003\"היתה לי נחלתי כאריה ביער נתנה עלי בקולה על כן שנאתיה\"\u0004 (ירמיהו יב, ח), \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"נתנה עלי בקולה\"? אמר מר זוטרא בר טוביה אמר רב, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' חמא אמר ר' אלעזר: זה שליח צבור שאינו הגון\u0004 (\"כאריה ביער\") \u0003היורד לפני התיבה,\u0004 שעליו כביכול אומר הקדוש ברוך הוא שהוא בגדר של \u0003\"נתנה עלי בקולה\" —\u0004 שקול תפילתו ונעימתו שנוא לפני המקום.","שנינו במשנה: \u0003ואומר לפניהם עשרים וארבע ברכות: שמונה עשרה שבכל יום ומוסיף עליהן עוד שש.\u0004 ותוהים: \u0003הני\u0004 \u0005[\u0006וכי \u0005אלה]\u0006 \u0003שש\u0004 ברכות בלבד הם שמוסיפים, הלא \u0003שבע הויין\u0004 \u0005[הן]!\u0006 \u0003כדתנן\u0004 \u0005[כפי ששנינו\u0006 במשנתנו\u0005],\u0006 \u0003על השביעית הוא אומר: \"ברוך מרחם על הארץ\"! אמר רב נחמן בר יצחק: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"שביעית\" — שביעית לארוכה\u0004. כלומר, אכן רק שש ברכות הם, אלא שמאריך בשישית ומוסיף עליה ולכך קורא הוא שביעית.","\u0003וכדתניא\u0004 \u0005[וכפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003ב\"גואל ישראל\" מאריך, ובחותמה\u0004 (בסיומה) \u0003הוא אומר: \"מי שענה את אברהם בהר המוריה הוא יענה אתכם וישמע בקול צעקתכם היום הזה. ברוך גואל ישראל\", והן,\u0004 הציבור, \u0003עונין אחריו \"אמן\", וחזן\u0004 (שמש) בית \u0003הכנסת אומר להם: \"תקעו בני אהרן תקעו\",\u0004","\u0003וחוזר ואומר\u0004 את כל הברכה השניה ומסיים: \u0003\"מי שענה את אבותינו על ים סוף הוא יענה אתכם וישמע בקול צעקתכם היום הזה, ברוך זוכר הנשכחות\", והן עונין אחריו \"אמן\", וחזן הכנסת אומר להם: \"הריעו בני אהרן הריעו\". וכן בכל ברכה וברכה,\u0004 הסדר הוא ש\u0003באחת אומר \"תקעו\"\u0004 ותוקעים \u0003ובאחת אומר \"הריעו\".\u0004","ומעירים: \u0003במה דברים אמורים — בגבולין,\u0004 שכך עושים בכל מקום חוץ למקדש, \u0003אבל במקדש אינו כן, לפי שאין עונין \"אמן\" במקדש,\u0004 אלא ברכה ארוכה. \u0003ומנין שאין עונין \"אמן\" במקדש —\u0004","\u0003שנאמר: \"קומו ברכו את ה' אלהיכם מן העולם עד העולם ויברכו שם כבדך ומרומם על כל ברכה ותהלה\"\u0004 (נחמיה ט, ה). \u0003יכול על כל ברכות כולן לא תהא אלא תהלה אחת,\u0004 שאומרים \"אמן\" בלבד — \u0003תלמוד לומר: \"ומרומם על כל ברכה ותהלה\" — על כל ברכה תן לו תהלה\u0004 מיוחדת.","\u0003ואלא במקדש מהו אומר?\u0004 בחתימה הוא אומר: \u0003\"ברוך ה' אלהים אלהי ישראל מן העולם ועד העולם ברוך גואל ישראל\", והן עונין אחריו\u0004 במקום \"אמן\": \u0003\"ברוך שם כבוד מלכותו לעולם ועד\". וחזן\u0004 (שמש) בית \u0003הכנסת אומר להם: \"תקעו הכהנים בני אהרון תקעו\",\u0004","\u0003וחוזר ואומר: \"מי שענה את אברהם בהר המוריה הוא יענה אתכם וישמע בקול צעקתכם היום הזה. ברוך ה' אלהי ישראל זוכר הנשכחות\", והם עונים אחריו: \"ברוך שם כבוד מלכותו לעולם ועד\", וחזן הכנסת אומר להם: \"הריעו, הכהנים בני אהרן, הריעו וכו'\", וכן\u0004 עשו ב\u0003כל ברכה וברכה, באחת\u0004 השמש \u0003אומר \"תקעו\" ובאחת\u0004 הוא \u0003אומר \"הריעו\", עד שגומר את כולן.\u0004","ומספרים: \u0003וכך הנהיג ר' חלפתא ב\u0004עירו \u0003צפורי, ור' חנניה בן תרדיון ב\u0004עירו \u0003סיכני, וכשבא\u0004 ה\u0003דבר לפני\u0004 ה\u0003חכמים אמרו\u0004 להם: \u0003לא היו נוהגין כן אלא בשערי מזרח, ובהר הבית.\u0004","\u0003ואית דאמרי\u0004 \u0005[ויש שאומרים]\u0006 ראיה, שהברכה הארוכה הראשונה אינה מן המנין, \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003אומר לפניהן עשרים וארבע ברכות, שמונה עשרה שבכל יום ומוסיף עליהן עוד שש. ואותן שש היכן אומרן — בין\u0004 ברכת \u0003\"גואל\" ל\u0004ברכת \u0003\"רופא חולי\" ומאריך ב\u0004ברכת ה\u0003גאולה, והן עונין אחריו \"אמן\" על כל ברכה וברכה. וכך היו נוהגין בגבולין\u0004 שעונים \"אמן\",","\u0003אבל במקדש היו אומרים: \"ברוך ה' אלהי ישראל מן העולם ועד העולם ברוך גואל ישראל\", ולא היו עונין אחריו \"אמן\". וכל כך למה — לפי שאין עונין \"אמן\" במקדש. ומנין שאין עונין \"אמן\" במקדש — שנאמר: \"קומו ברכו את ה' אלהיכם מן העולם עד העולם ויברכו שם כבודך ומרומם על כל ברכה ותהלה\" — על כל ברכה וברכה תן לו תהלה.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003על הראשונות הוא אומר \"ברוך ה' אלהי ישראל מן העולם ועד העולם ברוך גואל ישראל\", והן,\u0004 הציבור, \u0003עונין אחריו: \"ברוך שם כבוד מלכותו לעולם ועד\". וחזן הכנסת אומר: \"תקעו הכהנים תקעו\". וחוזר ואומר: \"מי שענה את אברהם בהר המוריה הוא יענה אתכם וישמע בקול צעקתכם היום הזה\", והן תוקעין ומריעין ותוקעין, ועל השניה הוא אומר: \"ברוך ה' אלהי ישראל מן העולם ועד העולם ברוך זוכר הנשכחות\", והן עונין אחריו: \"ברוך שם כבוד מלכותו לעולם ועד\",\u0004","\u0003וחזן הכנסת אומר: \"הריעו בני אהרן הריעו\". ואומר: \"מי שענה את אבותינו על ים סוף הוא יענה אתכם וישמע בקול צעקתכם היום הזה\", והם מריעין ותוקעין ומריעין, וכן\u0004 עושים \u0003בכל ברכה וברכה. באחת\u0004 הוא \u0003אומר \"תקעו\", ובאחת\u0004 הוא \u0003אומר \"הריעו\", עד שיגמור את הברכות כולן. וכך הנהיג ר' חלפתא בציפורי ור' חנניה בן תרדיון בסיכני. וכשבא\u0004 ה\u0003דבר אצל\u0004 ה\u0003חכמים אמרו: לא היו נוהגין כן אלא בשערי מזרח ובהר הבית.\u0004","שנינו במשנה: \u0003ר' יהודה אומר לא היה צריך לומר זכרונות\u0004 ושופרות, אלא אומר פסוקים העוסקים בענין הבצורת והרעב. \u0003אמר רב אדא דמן יפו: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהודה — לפי שאין אומרים זכרונות ושופרות\u0004"],["\u0003אלא בראש השנה, וב\u0004יום הכיפורים של \u0003יובלות, ובשעת מלחמה\u0004 בלבד.","שנינו במשנה: \u0003\"על\u0004 הברכה \u0003הראשונה הוא אומר מי שענה את אברהם כו'\". תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 בתוספתא: \u0003יש מחליפין צעקה לאליהו,\u0004 כלומר, חותמים ב\"שומע צעקה\" את הברכה המזכירה את אליהו, \u0003ותפלה לשמואל.\u0004 ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003גבי שמואל — כתיב ביה\u0004 \u0005[נאמרה בו]\u0006 לשון \u0003תפלה\u0004 (\"ויאמר שמואל קבצו את כל ישראל המצפתה ואתפלל בעדכם אל ה'\". שמואל א' ז, ה) \u0003וכתיב ביה\u0004 \u0005[ונאמרה בו]\u0006 לשון \u0003צעקה\u0004 (\"ויזעק שמואל אל ה' בעד ישראל\".","שמואל א' ז, ט) ולכן אפשר היה לומר גם לשון זו, \u0003אלא גבי אליהו,\u0004 הלא ענין \u0003תפלה כתיב\u0004 \u0005[נאמר]\u0006 בו (ראה מלכים א' יח, לו) אבל ענין \u0003צעקה לא כתיב\u0004 \u0005[נאמר]\u0006 בו! וכיצד אומרים לשון צעקה באליהו? ומשיבים: מה שאמר אליהו \u0003\"ענני ה' ענני\" —\u0004 (מלכים א' יח, לז) \u0003לשון צעקה היא\u0004 ולכן אפשר לומר גם שה' ענה לצעקתו של אליהו.","שנינו במשנה: \u0003על הששית הוא אומר: \"מי שענה את יונה כו'\", על השביעית הוא אומר: \"מי שענה את דוד\" כו'.\u0004 ושואלים: \u0003מכדי\u0004 \u0005[הלא]\u0006 \u0003יונה בתר\u0004 \u0005[אחרי]\u0006 \u0003דוד ושלמה הוה\u0004 \u0005[היה],\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003מקדים ליה ברישא\u0004 \u0005[אותו תחילה]?\u0006 ומשיבים: \u0003משום דבעי למיחתם\u0004 \u0005[ש\u0006הוא \u0005רוצה לחתום]\u0006 בברכה אחרונה \u0003\"\u0004ברוך \u0003מרחם על הארץ\".\u0004 ולכן מסיים בדוד ושלמה שהם היו מלכי הארץ, והתפללו עליה. \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003משום סומכוס אמרו:\u0004 שבברכה אחרונה זו אומר: \u0003\"ברוך משפיל הרמים\".\u0004","שנינו במשנה ש\u0003שלש תעניות הראשונות אנשי משמר מתענין ולא משלימין\u0004 וכן שנינו עוד את שאר הדינים של אנשי המשמר ואנשי המעמד. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מפני מה אמרו אנשי משמר מותרין לשתות יין בלילות אבל לא בימים\u0004 — \u0003שמא\u0004 ביום מסויים \u0003תכבד העבודה על אנשי בית אב, ויבואו\u0004 שאר אנשי המשמר \u0003ויסייעו להם,\u0004 ולכן אמרו שלא ישתו יין, כדי שלא יכנסו למקדש כשהם שיכורים.","\u0003מפני מה אמרו\u0004 שלא הותרה שתיית יין ל\u0003אנשי בית אב לא ביום ולא בלילה — מפני שהן עסוקין תמיד בעבודה.\u0004","\u0003מכאן אמרו:\u0004 בזמן הזה, לאחר החורבן, \u0003כל כהן שמכיר משמרתו\u0004 שיודע לאיזה משמרת שייכת משפחתו, \u0003ו\u0004כן יודע \u0003משמרת בית אב שלו, ויודע שבתי אבותיו קבועים שם,\u0004 שברור לו שמשפחתו אכן שייכת לבית אב ששימש ביום קבוע במקדש — \u0003אסור לשתות יין כל אותו היום,\u0004 שמא יבנה המקדש ויצטרך לחזור לעבודתו באותו יום. וכל זאת דווקא \u0003במכיר משמרתו,\u0004 שיודע באיזה שבוע בשנה היו הם עובדים, אבל \u0003אין מכיר\u0004 באיזה יום בשבוע היתה עובדת \u0003משמרת בית אב שלו, ו\u0004עם כל זה \u0003יודע\u0004 הוא בבירור \u0003שבתי אבותיו קבועין שם\u0004 בעבודה ביום מסויים — \u0003אסור לשתות יין כל אותה שבת\u0004 (שבוע) שבו עובדת משמרת זו.","\u0003אינו מכיר\u0004 לא \u0003משמרתו ו\u0004לא \u0003משמרת בית אב שלו, ויודע שבתי אבותיו קבועין שם — אסור לשתות יין כל השנה,\u0004 שהרי יודע בבירור שאם יבנה המקדש תיקרא משמרתו והוא בתוכה לעבודה, אלא שאינו יודע באיזה יום בשנה.","\u0003רבי אומר, אומר אני:\u0004 לפי זה יהיה בעצם \u0003אסור\u0004 כל כהן \u0003לשתות יין לעולם,\u0004 אפילו כהן המכיר את משמרתו ומשמרת בית אבותיו, שהרי אם ייבנה המקדש יתכן וישתנה סדר עבודת המשמרות, או שמא יעבדו כל המשמרות לחנוכת הבית ויתכן איפוא שיזדקקו לו שיעבוד אף שלא בזמן הקבוע למשמרתו, \u0003אבל מה אעשה שתקנתו קלקלתו.\u0004 שקלקלה זו שעברו שנים כה רבות מאז החורבן ועדיין לא נבנה הבית היא תקנתו, שאי אפשר לגזור גזירה זו על הכהנים ולכן הותרה להם שתיית יין בכל ימות השנה. \u0003אמר אביי: כמאן שתו האידנא כהני חמרא\u0004 \u0005[כ\u0006דעת \u0005מי שותים הכהנים בזמן הזה יין]\u0006 \u0003כ\u0004דעת \u0003רבי.\u0004","שנינו במשנה ש\u0003אנשי משמר ואנשי מעמד אסורים לספר\u0004 שערם \u0003ולכבס\u0004 בגדיהם, ורק \u0003ב\u0004יום \u0003חמישי מותרין מפני כבוד השבת.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 אסור להם לספר ולכבס? \u0003אמר רבה בר בר חנה אמר ר' יוחנן:\u0004 שהצטרכו לעשות תספורת וכביסה בשבוע שקודם למשמרתם \u0003כדי שלא יכנסו למשמרתם כשהם מנוולין\u0004 (מלוכלכים ובלתי מסופרים) ויחשבו שבזמן המשמרת יוכלו לעשות זאת.","מעין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מלך מסתפר בכל יום, כהן גדול — מערב שבת לערב שבת, כהן הדיוט — אחת לשלשים יום.\u0004 ומסבירים: \u0003מלך מסתפר בכל יום — מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003אמר ר' אבא בר זבדא: אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"מלך ביפיו תחזינה עיניך\"\u0004 (ישעיהו לג, יז), ולכן מן הראוי שהמלך יהיה מהודר ככל האפשר. \u0003כהן גדול\u0004 מסתפר \u0003מערב שבת לערב שבת — מאי טעמא\u0004 \u0005[מה טעם]?\u0006 \u0003אמר רב שמואל בר יצחק: הואיל ומשמרות מתחדשות\u0004 בכל שבוע, לכך ראוי שבכל משמרת יבואו הכהנים החדשים ויראו את הכהן הגדול כשתספורתו עשויה כראוי.","\u0003כהן הדיוט\u0004 מסתפר \u0003אחת לשלשים יום — מנלן\u0004 \u0005[מנין לנו]?\u0006 למדים דבר זה מגזירה שווה, \u0003אתיא\u0004 \u0005[באה,\u0006 נלמדת\u0005]\u0006 מן המלה השווה \u0003\"פרע\" \"פרע\" מנזיר, כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 בכהנים: \u0003\"וראשם לא יגלחו ופרע לא ישלחו\"\u0004 (יחזקאל מד, כ), ומכאן שאסור לכהנים לגדל שערותיהם יותר מדי, \u0003וכתיב התם\u0004 \u0005[נאמר שם]\u0006 בנזיר: \u0003\"קדש יהיה גדל פרע שער ראשו\"\u0004 (במדבר ו, ה), \u0003ומה להלן\u0004 בנזיר, הזמן של שילוח פרע הוא לפחות \u0003שלשים\u0004 יום — \u0003אף כאן שלשים\u0004 יום.","ושואלים: \u0003ונזיר גופיה מנלן\u0004 \u0005[עצמו מניין לנו]\u0006 שהוא שלושים יום? \u0003אמר רב מתנה:\u0004 כלל הוא ש\u0003סתם נזירות שלשים יום.\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מניין לנו]\u0006 כלל זה? ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"קדוש יהיה\", ו\u0003\"יהיה\" בגמטריא\u0004 (לפי חשבון האותיות), \u0003תלתין הוי\u0004 \u0005[שלושים הוא].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: ודלמא הכי קאמר רחמנא\u0004 \u0005[ושמא כך אמרה התורה]:\u0006 ש\u0003לא לירבו\u0004 \u0005[יגדלו]\u0006 שער \u0003כלל\u0004 ויסתפרו בכל יום? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אי הוה כתב\u0004 \u0005[אלו היה כותב]\u0006 \u0003\"לא ישלחו פרע\" —\u0004 הייתי מפרש אכן \u0003כדקאמרת\u0004 \u0005[כפי שאמרת],\u0006 אולם \u0003השתא דכתיב\u0004 \u0005[עכשיו שכתוב\u0006 שם\u0005]:\u0006 \u0003\"ופרע לא ישלחו\" —\u0004 הכוונה היא זו: \u0003פרע ליהוי\u0004 \u0005[שיהיה],\u0006 שהשערות יכולות לגדול קצת, אבל \u0003שלוחי הוא דלא לישלחו\u0004 \u0005[לשלח אותן\u0006 הרבה \u0005שלא ישתלחו]\u0006 ויסתפרו לפני שהן עוברות את גדר \"פרע\".","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שתספורת הכהנים היא מחובות עבודתם במקדש ומן התורה היא, אם כן \u0003אפילו האידנא נמי\u0004 \u0005[בזמן הזה גם כן]\u0006 יצטרכו הכהנים להסתפר אחת לשלושים יום, שמא ייבנה בית המקדש וייקראו הם לעבודה! ומשיבים: \u0003דומיא\u0004 \u0005[דומה]\u0006 הדבר לדין \u0003שתויי יין. מה שתויי יין — בזמן ביאה\u0004 למקדש \u0003הוא\u0004 ש\u0003אסור\u0004 להם שיהיו שתויים, אולם \u0003שלא בזמן ביאה — שרי\u0004 \u0005[מותר]\u0006 להם לשתות יין, \u0003אף הכא נמי\u0004 \u0005[כאן גם כן]\u0006 חובת תספורת היא רק בזמן עבודתה במקדש.","ושואלים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003רבי אומר: אומר אני כהנים אסורים\u0004 בעצם \u0003לשתות יין לעולם, אבל מה אעשה שתקנתו קלקלתו. ואמר אביי\u0004 על כך: \u0003כמאן שתו האידנא כהני חמרא\u0004 \u0005[כ\u0006דעת \u0005מי שותים הכהנים בזמן הזה יין]\u0006"],["\u0003כ\u0004דעת \u0003רבי,\u0004 ואם כן, \u0003מכלל דרבנן אסרי\u0004 \u0005[מכאן שחכמים אוסרים]\u0006 אף בזמן הזה, ומדוע לא נאסור אף בתספורת! ומשיבים: \u0003מאי טעמא\u0004 \u0005[ומה טעם]\u0006 האיסור, משום התקווה: \u0003מהרה יבנה בית המקדש, ובעינן\u0004 \u0005[ואנו צריכים]\u0006 \u0003כהן הראוי לעבודה — וליכא\u0004 \u0005[ואין],\u0006 שכולם יהיו פסולים משום שתויי יין, ויעבור זמן רב עד שיפוג יינם, ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003אפשר\u0004 שמכשיר את עצמו בקלות \u0003דמספר ועייל\u0004 \u0005[שיסתפר ויכנס]\u0006 מיד לעבודה.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003שתוי יין נמי\u0004 \u0005[גם כן]\u0006 \u0003אפשר דגני פורתא ועייל\u0004 \u0005[שיישן מעט ויכנס]\u0006 ו\u0003כד\u0004 ברי \u0003רמי בר אבא,\u0004 ש\u0003אמר רמי בר אבא: דרך מיל,\u0004 שאדם הולך אחר שתייתו \u0003ושינה כל שהוא — מפיגין את\u0004 השפעת \u0003היין!\u0004 ודוחים: \u0003לאו מי איתמר עלה\u0004 \u0005[האם לא נאמר עליה]\u0006 על הלכה זו ש\u0003אמר רב נחמן אמר רבה בר אבוה: לא שנו\u0004 שדרך ושינה כל שהיא מפיגים את השפעת היין, \u0003אלא כששתה שיעור רביעית\u0004 או פחות, \u0003אבל\u0004 אם \u0003שתה יותר מרביעית — כל שכן שדרך\u0004 שהולך אחר כך \u0003מטרידתו ושינה משכרתו\u0004 יותר. ולכן אסרו לכהנים לשתות יין שמא לא יימצאו כהנים הראויים לעבודה.","\u0003רב אשי אמר\u0004 טעם אחר לחלק בין הדינים: \u0003שתויי יין\u0004 שאם נכנסו ועשו עבודה \u0003דמחלי\u0004 \u0005[שמחללים]\u0006 הם בכך \u0003עבודה,\u0004 את עבודת הקודש — \u0003גזרו בהו רבנן\u0004 \u0005[בהם חכמים]\u0006 שלא ישתו, ואולם \u0003פרועי ראש דלא מחלי\u0004 \u0005[שאינם מחללים]\u0006 בכך את ה\u0003עבודה\u0004 — \u0003לא גזרו בהו רבנן\u0004 \u0005[בהם חכמים].\u0006","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו: \u0003ואלו\u0004 מן העבירות \u0003שהן\u0004 גוררות עונש \u0003במיתה\u0004 בידי שמים: כהנים הנכנסים לעבודה כשהם \u0003שתויי יין, ופרועי ראש.\u0004 ותחילה מבררים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003שתויי יין — בהדיא כתיב בהו\u0004 \u0005[במפורש נאמר בהם]\u0006 \u0003\"יין ושכר אל תשת\u0004 אתה ובניך אתך בבואכם אל אהל מועד ולא תמותו\u0003\"\u0004 (ויקרא י, ט), \u0003אלא פרועי ראש מנלן\u0004 \u0005[מניין לנו]\u0006 שחייבים מיתה?","ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וראשם לא יגלחו ופרע לא ישלחו\"\u0004 (יחזקאל מד, כ), \u0003וכתיב בתריה\u0004 \u0005[ונאמר אחריו]:\u0006 \u0003\"ויין לא ישתו כל כהן בבואם אל החצר הפנימית\"\u0004 (יחזקאל מד, כא), \u0003ואיתקוש\u0004 \u0005[והוקשו,\u0006 והשוו\u0005]\u0006 לפיכך \u0003פרועי ראש לשתויי יין; מה שתויי יין\u0004 עונשם \u0003במיתה — אף פרועי ראש\u0004 עונשם \u0003במיתה.\u0004","ומקשים: \u0003ומינה\u0004 \u0005[וממנה]\u0006 מן ההשוואה הזו אנחנו יכולים להמשיך ולומר: \u0003אי\u0004 \u0005[אם]\u0006 כך, אמור אף: \u0003מה שתויי יין דמחלי\u0004 \u0005[שמחללים]\u0006 את ה\u0003עבודה\u0004 אם עשו אותה בהיותם שתויים — \u0003אף פרועי ראש\u0004 יהיו כמו כן אף הם \u0003דמחלי\u0004 \u0005[שמחללים]\u0006 את ה\u0003עבודה!\u0004 ודוחים: \u0003לא, כי איתקוש\u0004 \u0005[כאשר הוקשו,\u0006 הושוו\u0005]\u0006 הדברים — \u0003למיתה הוא דאתקוש\u0004 \u0005[שהוקשו,\u0006 הושוו\u0005],\u0006 \u0003אבל לאחולי\u0004 \u0005[לחלל]\u0006 את ה\u0003עבודה — לא אתקוש\u0004 \u0005[הוקשו,\u0006 הושוו\u0005],\u0006 ודבר שלא נתפרש לא למדנו.","באותו ענין \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: הא\u0004 \u0005[\u0006דבר \u0005זה],\u0006 איסור עבודה לכהנים כשהם פרועי ראש הנלמד מדברי הנביא יחזקאל, \u0003מקמי דאתא\u0004 \u0005[מלפני שבא]\u0006 \u0003יחזקאל, מאן אמרה\u0004 \u0005[מי אמרו]?\u0006 שהרי איסור זה של פרועי ראש לא נזכר בתורה, וכיצד מתחדש דבר על ידי נביא, שאינו רשאי לחדש הלכה! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005],\u0006 לפי אותה סברה, \u0003הא\u0004 \u0005[זו]\u0006 ש\u0003אמר רב חסדא: דבר זה מתורת משה לא למדנו, ומדברי קבלה\u0004 (דברי נביאים) \u0003למדנו,\u0004 שנאמר: \u0003\"כל בן נכר ערל לב וערל בשר לא יבוא אל מקדשי לשרתני\"\u0004 (יחזקאל מד, ט), \u0003הא מקמי דאתא\u0004 \u0005[\u0006דבר \u0005זה לפני שבא]\u0006 \u0003יחזקאל, מאן אמרה\u0004 \u0005[מי אמרו]?\u0006","\u0003אלא\u0004 על כרחך אתה חייב לומר ש\u0003גמרא גמיר לה\u0004 \u0005[במסורת למד אותה]\u0006 ככל תורה שבעל־פה, \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003יחזקאל ואסמכה אקרא\u0004 \u0005[והסמיכה על הכתוב]\u0006 ונכתבה על ידו, ולא הוא חידש את ההלכה. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 לענין פרועי ראש, \u0003גמרא גמיר לה\u0004 \u0005[במסורת למד אותה]\u0006 \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003יחזקאל ואסמכה אקרא\u0004 \u0005[והסמיכה על הכתוב],\u0006 \u0003כי גמירי\u0004 \u0005[וכאשר למדו]\u0006 \u0003הלכה\u0004 זו מתחילה היה זה \u0003ל\u0004ענין עונש \u0003מיתה\u0004 בידי שמים לעובר, אבל \u0003לאחולי\u0004 \u0005[ל\u0006ענין \u0005חילול]\u0006 ה\u0003עבודה — לא גמירי\u0004 \u0005[למדו].\u0006","שנינו במשנה ש\u0003כל\u0004 יום ש\u0003כתוב\u0004 עליו \u0003במגילת תענית \"דלא למיספד\"\u0004 \u0005[שאין לספוד\u0006 בו\u0005]\u0006 — ביום ש\u0003לפניו אסור\u0004 להתענות, וביום ש\u0003לאחריו — מותר. תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 במגילת תענית: \u0003אלין יומיא\u0004 \u0005[אלה\u0006 הם \u0005הימים]\u0006 שקבעו ש\u0003לא להתענאה בהון\u0004 \u0005[להתענות בהם],\u0006 \u0003ומקצתהון\u0004 \u0005[ומקצתם]\u0006 אפילו ש\u0003לא למיספד בהון\u0004 \u0005[לספוד בהם]:\u0006 \u0003מריש ירחא דניסן\u0004 \u0005[מראש חודש ניסן]\u0006 \u0003עד תמניא ביה\u0004 \u0005[\u0006היום ה\u0005שמיני בו]\u0006 \u0003איתוקם תמידא\u0004 \u0005[הוקם התמיד],\u0006 ולפיכך נקבע בענין הימים הללו ש\u0003לא למיספד בהון\u0004 \u0005[לספוד בהם].\u0006 \u0003מתמניא ביה\u0004 \u0005[מה\u0006 יום ה\u0005שמיני בו]\u0006 \u0003עד סוף מועדא\u0004 \u0005[המועד\u0006 חג הפסח\u0005]\u0006 \u0003איתותב חגא דשבועיא\u0004 \u0005[הוחזר חג השבועות]\u0006 ולכך נקבע ש\u0003לא למיספד בהון\u0004 \u0005[לספוד בהם].\u0006","ומעתה אנחנו מבררים את הדברים הללו בהשוואה למשנתנו, \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003מריש ירחא דניסן\u0004 \u0005[מראש חודש ניסן]\u0006 \u0003עד תמניא ביה\u0004 \u0005[\u0006היום ה\u0005שמיני בו]\u0006 \u0003איתוקם תמידא דלא למיספד\u0004 \u0005[הועמד התמיד שאין לספוד]\u0006 אבל \u0003למה לי\u0004 שיאמר \u0003מריש ירחא\u0004 \u0005[מראש חודש]?\u0006 \u0003לימא מתרי\u0004 \u0005[שיאמר\u0006 רק \u0005משנים]\u0006 \u0003בניסן,\u0004 שהרי \u0003ראש חודש גופיה\u0004 \u0005[עצמו]\u0006 \u0003יום טוב הוא ואסור\u0004 לספוד בו! ולשם מה הזכירו גם אותו? \u0003אמר רב: לא נצרכה\u0004 הלכה זו שבמגילת תענית לגבי ראש חודש עצמו, \u0003אלא לאסור\u0004 בהספד אף את ה\u0003יום שלפניו,\u0004 שהרי אמרנו שבימים הכתובים במגילת תענית, גם ביום שלפניהם אסור להתענות.","ושואלים: \u0003ו\u0004איסור ההספד ביום \u0003שלפניו נמי, תיפוק ליה\u0004 \u0005[גם כן, תצא לו]\u0006 הלכה זו מטעם אחר \u0003דהוה ליה\u0004 \u0005[שהרי הוא]\u0006 \u0003יום שלפני ראש חדש,\u0004 וכיון שבראש חודש אסור להתענות, גם ביום שלפניו אסור! ומשיבים: אין הדבר כן — \u0003ראש חדש דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003הוא ודאורייתא לא בעי\u0004 \u0005[ו\u0006דבר \u0005שמן התורה אינו צריך]\u0006 \u0003חיזוק,\u0004 ולכן מותר להתענות ביום שלפניו.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו בברייתא\u0006\u0005]:\u0006 \u0003הימים האלה הכתובין במגילת תענית — לפניהם ולאחריהם אסורין\u0004 בתענית, ואילו \u0003בשבתות ובימים טובים, הן\u0004 עצמם — \u0003אסורין\u0004 בתענית, אבל \u0003לפניהן ולאחריהן — מותרין. ומה הפרש בין זה לזה? הללו\u0004 שבתות וימים טובים \u0003דברי תורה\u0004 הם \u0003ודברי תורה אין צריכין חיזוק\u0004 לעשות להם משמרת לפניהם ואחריהם, ואילו \u0003הללו\u0004 שאר הימים הכתובים במסכת תענית — מ\u0003דברי סופרים\u0004 הם, \u0003ודברי סופרים צריכין חיזוק.\u0004","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003מתמניא ביה\u0004 \u0005[מ\u0006היום ה\u0005שמיני בו]\u0006 \u0003עד סוף מועדא\u0004 \u0005[המועד,\u0006 פסח\u0005]\u0006 \u0003איתותב חגא דשבועיא\u0004 \u0005[הוחזר חג השבועות]\u0006 ונקבע ש\u0003לא למיספד\u0004 \u0005[לספוד]\u0006 בהם, ושואלים: \u0003למה לי\u0004 לומר \u0003\"עד סוף\u0004 ה\u0003מועד\"? לימא\u0004 \u0005[שיאמר]\u0006 \u0003\"עד המועד\",\u0004 שהרי ה\u0003מועד גופיה\u0004 \u0005[עצמו]\u0006 \u0003יום טוב הוא, ואסור\u0004 לפיכך בהספד! \u0003אמר רב פפא\u0004 גם כאן יש לפרש \u0003כדאמר\u0004 \u0005[כפי שאמר]\u0006 \u0003רב: לא נצרכא\u0004 הלכה זו לגופה,"],["\u0003אלא לאסור\u0004 את ה\u0003יום שלפניו,\u0004 אם כן \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 \u0003לא נצרכה אלא לאסור\u0004 אף את ה\u0003יום שלאחריו,\u0004 לומר שגם היום שאחרי סוף המועד אסור בהספד משום שהוא לאחר יום הכתוב במגילת תענית. ושואלים: \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי\u0006 הדבר\u0005],\u0006 אם תאמר שהוא \u0003כ\u0004שיטת \u0003ר' יוסי\u0004 ש\u0003אמר:\u0004 לא רק היום הכתוב במגילת תענית אסור אלא \u0003בין לפניו ובין לאחריו אסור; אי הכי\u0004 \u0005[אם כך]\u0006 \u0003ב\u0004יום ה\u0003עשרים ותשעה\u0004 בחודש אדר \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא\u0005]\u0006 ייאסר להתענות בו מן הטעם שאמרנו \u0003דהוי יומא דמקמי יומא דמיתוקם תמידא\u0004 \u0005[שהוא יום לפני היום שהועמד\u0006 בו \u0005התמיד],\u0006 ראש חודש ניסן? \u0003תיפוק ליה\u0004 \u0005[תצא לו]\u0006 הלכה זו שאסור להתענות ביום זה מטעם אחר — \u0003דהוה ליה\u0004 \u0005[שהרי הוא]\u0006 \u0003יומא דבתר עשרין ותמניא ביה\u0004 \u0005[יום אחרי עשרים ושמונה בו,\u0006 באדר\u0005]\u0006 ומטעם זה עצמו ייאסר בתענית,","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 במגילת תענית: \u0003בעשרים ותמניא ביה\u0004 \u0005[בעשרים ושמונה בו]\u0006 באדר \u0003אתת בשורתא טבתא ליהודאי דלא יעידון מן אורייתא\u0004 \u0005[באה בשורה טובה ליהודים שלא יסורו מן התורה]\u0006 וקבעו יום זה כחג. ומהו הענין? מבואר שם: \u0003שפעם אחת גזרה מלכות הרשעה\u0004 (רומי) \u0003שמד על ישראל שלא יעסקו בתורה, ושלא ימולו את בניהם, ושיחללו שבתות. מה עשה יהודה בן שמוע וחבריו? הלכו ונטלו עצה ממטרוניתא\u0004 (גבירה) \u0003אחת שכל גדולי רומי מצויין אצלה\u0004 מה יעשו.","\u0003אמרה להם: עמדו והפגינו\u0004 (צעקו) \u0003בלילה. הלכו והפגינו בלילה, ואמרו\u0004 בצעקתם: \u0003אי\u0004 (אוי) \u0003שמים!\u0004 וכי \u0003לא אחים אנחנו, לא בני אב אחד אנחנו, לא בני אם אחת אנחנו? מה נשתנינו מכל אומה ולשון שאתם גוזרין עלינו גזירות רעות!\u0004 והשפיעה ההפגנה \u0003ובטלום\u0004 את הגזירות הללו, \u0003ואותו יום\u0004 שביטלום \u0003עשאוהו יום טוב.\u0004 וכיון שעשרים ושמיני באדר הוא יום טוב, הרי לדעת ר' יוסי גם ביום שלאחריו אסור להתענות, ואם כן אין צורך לשנות גם את ראש חודש ניסן כדי לאסור את העשרים ותשעה באדר מטעם יום שלפניו, שכן הוא אסור כבר משום שהוא יום אחרי העשרים ושמונה באדר!","\u0003אמר אביי: לא נצרכה אלא לחדש מעובר.\u0004 שהרי יתכן שיהיה חודש אדר בן שלושים יום ואז היום העשרים ותשעה בו אינו היום שלפני ראש חודש ניסן ואין לאוסרו אלא משום שהוא היום שלאחר העשרים ושמונה באדר.","\u0003רב אשי אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 \u0003לחודש חסר,\u0004 בכל זאת צריך שיהיו שני ימים טובים אלה, כי אמנם \u0003כל שלאחריו\u0004 — \u0003בתענית אסור\u0004 אבל \u0003בהספד מותר, ו\u0004יום \u0003זה, הואיל ומוטל בין שני ימים טובים,\u0004 העשרים ושמיני באדר וראש חודש ניסן — \u0003עשאוהו\u0004 שיהיה דינו \u0003כיום טוב עצמו, ואפילו בהספד נמי\u0004 \u0005[גם כן]\u0006 \u0003אסור.\u0004","\u0003אמר מר\u0004 \u0005[החכם]\u0006 במגילת תענית: \u0003מתמניא ביה\u0004 \u0005[משמונה בו,\u0006 בניסן\u0005]\u0006 \u0003ועד סוף מועדא\u0004 \u0005[המועד,\u0006 פסח\u0005]\u0006 \u0003איתותב חגא דשבועיא\u0004 \u0005[הוחזר חג השבועות]\u0006 ולפיכך נקבע ש\u0003לא למיספד\u0004 \u0005[לספוד]\u0006 בהם. ושואלים: \u0003למה לי למימר\u0004 \u0005[לומר]\u0006 \u0003מתמניא ביה\u0004 \u0005[משמונה בו]?\u0006 \u0003לימא\u0004 \u0005[שיאמר]\u0006 \u0003מתשעה ביה\u0004 \u0005[בו],\u0006 שכן \u0003ותמניא גופיה\u0004 \u0005[ושמיני עצמו]\u0006 \u0003אסור\u0004 משום \u0003דהוה ליה יומא דאיתוקם ביה תמידא\u0004 \u0005[שהרי הוא יום שהוקם בו התמיד]\u0006 כפי ששנינו!","ומשיבים: צריך הדבר להיאמר \u0003כיון שאילו מקלע ליה מילתא ובטליניה\u0004 \u0005[הזדמן לו דבר\u0006 של אבל \u0005ונבטל]\u0006 את יום \u0003שבעה —\u0004 הרי \u0003תמניא גופיה\u0004 \u0005[\u0006היום \u0005השמיני עצמו]\u0006 \u0003אסור\u0004 מטעם אחר, \u0003דהוה ליה יומא קמא דאיתותב ביה חגא דשבועיא\u0004 \u0005[שהרי הוא יום ראשון שהושב בו חג השבועות]\u0006 ולא נאמר שיום זה יש בו שמחה רק מפני שהוא היום שאחר יום הקמת התמיד, אלא יש בו שמחה לעצמו, שאינה בטלה עם ביטול השביעי.","ומעירים: \u0003השתא דאתית להכי\u0004 \u0005[עכשיו\u0006 כיון \u0005שהגעת לכאן]\u0006 לתירוץ בדרך זו, שמא ייבטל יום טוב אחד, אף \u0003עשרים ותשעה נמי\u0004 \u0005[גם כן]\u0006 אפשר להסביר: \u0003כיון\u0004 ש\u0003אילו מיקלע מילתא ובטליניה\u0004 \u0005[הזדמן דבר\u0006 באותו יום \u0005ונבטל]\u0006 את היום ה\u0003עשרים ותמניא\u0004 \u0005[ושמונה]\u0006 — \u0003עשרין ותשעה גופיה\u0004 \u0005[עצמו]\u0006 \u0003אסור דהוה ליה יומא דמקמי יומא דאיתוקם תמידא\u0004 \u0005[שהרי הוא יום מלפני היום שהוקם בו התמיד]\u0006 וצריך הדבר להיאמר מטעם זה.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שחלקו אמוראים בהלכה, \u0003ר' חייא בר אסי אמר\u0004 בשם \u0003רב: הלכה כר' יוסי,\u0004 שבכל אותם ימים הכתובים במגילת תענית שאסורים בהספד, אסור כמו כן גם ביום שלפניהם וגם ביום שלאחריהם, \u0003ושמואל אמר: הלכה כ\u0004סתם משנה, שעל פי הכללים המסורים בידינו היא שיטת \u0003ר' מאיר,\u0004 שאסורים בימים שלפניהם ומותרים בשלאחריהם.","ותוהים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר שמואל הכי\u0004 \u0005[כך]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003רבן שמעון בן גמליאל אומר: ומה תלמוד לומר\u0004 במגילת תענית \u0003\"בהון\" \"בהון\" שתי פעמים\u0004 (\"למספד בהון\" \"להתענאה בהון\") \u0003לומר לך\u0004 בהדגשה זו: \u0003שהן\u0004 עצמם \u0003אסורין, לפניהן ולאחריהן — מותרין. ואמר שמואל: הלכה כרבן שמעון בן גמליאל.\u0004 וכיצד אומר אתה שפסק הלכה כר' מאיר?","ומשיבים: \u0003מעיקרא\u0004 \u0005[מתחילה]\u0006 \u0003סבר כיון דליכא\u0004 \u0005[שאין]\u0006 \u0003תנא\u0004 אחר ש\u0003מיקל\u0004 ואומר \u0003כ\u0004שיטת \u0003ר' מאיר, אמר הלכה כר' מאיר, כיון דשמעיה\u0004 \u0005[ששמע אותו]\u0006 את \u0003רבן שמעון\u0004 שהוא \u0003מיקל טפי\u0004 \u0005[יותר],\u0006 \u0003אמר: הלכה כרבן שמעון בן גמליאל,\u0004 שעיקר פסק ההלכה שלו היה שיש להקל בימים טובים אלה ככל האפשר.","\u0003וכן אמר\u0004 החכם \u0003באלי אמר ר' חייא בר אבא אמר ר' יוחנן: הלכה כ\u0004שיטת \u0003ר' יוסי.\u0004 ומספרים: \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' חייא\u0004 בר אבא \u0003לבאלי: אסברא לך\u0004 \u0005[אסביר לך]\u0006 את הדברים, \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר ר' יוחנן\u0004 ש\u0003הלכה כ\u0004שיטת \u0003ר' יוסי\u0004 — לא לכל דבר אמר, אלא \u0003א\"דלא להתענאה\"\u0004 \u0005[על\u0006 היום שנאמר בו \u0005שלא להתענות]\u0006 שגם לפניו אסור, אבל בימים שנאמר בהם שלא להספיד לא פסק כר' יוסי, ויום שלאחריהם מותר.","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' יוחנן הכי\u0004 \u0005[כך]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן\u0004 כלל גדול: \u0003הלכה כסתם\u0004 שיטה ב\u0003משנה\u0004 שאינה מצויינת בשם אומרה. \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003אף על פי שאמרו\u0004 שבימי קריאת המגילה \u0003מקדימין ולא מאחרין,\u0004 ותיקנו חכמים שבמקומות מסויימים אפשר יהיה לקרוא את המגילה גם באחד עשר, בשנים עשר, ובשלושה עשר באדר,"],["\u0003מותרין\u0004 ימים אלה \u0003בהספד ותענית.\u0004 ונברר: \u0003אימת\u0004 \u0005[אימתי],\u0006 באלו ימים מדובר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר ב\u0003בני\u0004 כרכים הקוראים את המגילה ב\u0003חמיסר\u0004 \u0005[\u0006ב\u0005חמישה עשר]\u0006 באדר \u0003וקא קרי לה בארביסר\u0004 \u0005[והם קוראים אותה בארבעה עשר]\u0006 והותרו להם הספד ותענית ביום זה, אולם \u0003ומי שרי\u0004 \u0005[והאם מותר]\u0006 כלל להתענות בימים אלה?","\u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003במגילת תענית: יום ארבעה עשר בו\u0004 באדר \u0003ויום חמשה עשר בו, יומי פוריא אינון דלא למיספד בהון\u0004 \u0005[ימי הפורים הם שאסור לספוד בהם].\u0006 \u0003ואמר רבא: לא נצרכא\u0004 \u0005[נצרך]\u0006 הדבר להיאמר במגילת תענית, שהרי הוא כבר נאמר במגילת אסתר שבמקרא, \u0003אלא\u0004 בחזרה זו על הדברים בא \u0003לאסור את של זה בזה ואת של זה בזה,\u0004 שאפילו מי שהפורים שלו ביום חמישה עשר — אסור לו לספוד בארבעה עשר, ולהיפך.","\u0003ואלא,\u0004 יש לפרש את המשנה שמדובר בה באלה שהם \u0003בני ארביסר\u0004 \u0005[\u0006הקוראים \u0005בארבעה עשר]\u0006 והקדימו \u0003וקא קרי ליה בתליסר\u0004 \u0005[וקוראים אותה,\u0006 את המגילה \u0005בשלושה עשר],\u0006 אך הלא אין צורך בטעם זה לאיסור תענית, שהרי שלושה עשר באדר \u0003יום ניקנור הוא\u0004 שהוא יום שמחה מחמת עצמו! \u0003ואלא\u0004 תפרש שמדובר ב\u0003בני\u0004 עיירות הקוראים ב\u0003ארביסר\u0004 \u0005[\u0006ב\u0005ארבעה עשר]\u0006 והקדימו \u0003וקא קרי ליה בתריסר\u0004 \u0005[וקוראים אותה,\u0006 את המגילה \u0005בשנים עשר],\u0006 אולם הלא גם יום זה הוא חג לעצמו, שכן \u0003יום טוריינוס הוא!\u0004","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 \u0003דקא קרו ליה בחדיסר\u0004 \u0005[שקראו\u0006 אותה \u0005באחד עשר]\u0006 \u0003וקתני\u0004 \u0005[ושנה]\u0006 במשנה על יום זה שהוא \u0003מותר בהספד ובתענית,\u0004 אף שהוא יום שלפני יום טוריינוס, ונמצא שסתם משנה אינה כשיטת ר' יוסי, והרי זו סתירה בדברי ר' יוחנן!","ומשיבים: \u0003לא,\u0004 הכוונה היא במשנה ב\u0003בני ארבעה עשר, וקא קרו ליה בתריסר\u0004 \u0005[והם קוראים אותה,\u0006 את המגילה \u0005בשנים עשר]\u0006 \u0003ודקאמרת\u0004 \u0005[ומה שאמרת]\u0006 שהלא \u0003יום טריינוס הוא — יום טריינוס גופיה\u0004 \u0005[עצמו]\u0006 \u0003בטולי בטלוהו\u0004 \u0005[ביטלו אותו]\u0006 מלהיות יום חג, \u0003הואיל ונהרגו בו שמעיה ואחיה אחיו. כי הא\u0004 \u0005[כמו זה]\u0006 שמסופר: \u0003רב נחמן גזר תעניתא\u0004 \u0005[תענית]\u0006 \u0003בתריסר\u0004 \u0005[בשנים עשר\u0006 באדר\u0005].\u0006 \u0003אמרו ליה רבנן\u0004 \u0005[לו חכמים]:\u0006 הלא \u0003יום טוריינוס הוא! אמר להו\u0004 \u0005[להם]:\u0006 \u0003יום טוריינוס גופיה\u0004 \u0005[עצמו]\u0006 \u0003בטולי בטלוהו\u0004 \u0005[ביטלו אותו]\u0006 \u0003הואיל ונהרגו בו שמעיה ואחיה אחיו.\u0004","ומקשים: \u0003ותיפוק ליה דהוה ליה\u0004 \u0005[וייצא לו\u0006 איסור תענית ביום זה \u0005שהרי הוא]\u0006 \u0003יום שלפני\u0004 יום \u0003ניקנור! אמר רב אשי: השתא איהו גופיה בטלוהו\u0004 \u0005[עכשיו,\u0006 הרי, \u0005אותו עצמו ביטלו]\u0006 משום האבל, וכי \u0003משום יום ניקנור\u0004 שהוא יום שאחריו \u0003ניקום ונגזר\u0004 \u0005[נעמוד ונגזור]\u0006 בו איסור תענית?","אגב כך מבררים: \u0003מאי\u0004 \u0005[מהו\u0006 עניינו\u0005]\u0006 של \u0003ניקנור ומאי\u0004 \u0005[ומהו\u0006 עניינו\u0005]\u0006 של \u0003טוריינוס? דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו בברייתא\u0006\u0005]:\u0006 \u0003ניקנור אחד מאפרכי\u0004 (משרי הצבא) ה\u0003יוונים היה, ובכל יום ויום היה מניף ידו על יהודה וירושלים, ואומר: אימתי תפול בידי\u0004 עיר זו \u0003וארמסנה. וכשגברה מלכות בית חשמונאי ונצחום,\u0004 הרגו אותו במלחמה, \u0003קצצו בהונות ידיו ורגליו ותלאום בשערי ירושלים, ואמרו: פה שהיה מדבר בגאוה, וידיים שהיו מניפות\u0004 בבוז \u0003על ירושלים — תעשה בהם נקמה,\u0004 ויום זה שלושה עשר באדר היה. \u0003מאי\u0004 \u0005[מהו\u0006 עניינו\u0005]\u0006 של \u0003טוריינוס? אמרו: כשבקש טוריינוס להרוג את\u0004 המנהיגים החשובים \u0003לולינוס ופפוס אחיו בלודקיא, אמר להם: אם מעמו של חנניה מישאל ועזריה אתם — יבא אלהיכם ויציל אתכם מידי, כדרך שהציל את חנניה מישאל ועזריה מיד נבוכדנצר! אמרו לו\u0004 לוליינוס ופפוס: \u0003חנניה מישאל ועזריה צדיקים גמורין היו\u0004 בעצמם, \u0003וראויין היו ליעשות להם נס.\u0004 ועוד: \u0003ונבוכדנצר מלך הגון היה,\u0004 שהיה מלך גדול שעלה לשלטון בזכות \u0003וראוי לעשות נס על ידו,\u0004 שיזכה לגרום שייראה נס.","","\u0003ואותו רשע,\u0004 כלומר, אתה, \u0003הדיוט הוא\u0004 ולא מלך אמיתי \u0003ואינו ראוי ליעשות נס על ידו.\u0004 וגם אנו איננו צדיקים, \u0003ואנו נתחייבנו כליה למקום\u0004 (הקדוש ברוך הוא) בגלל עוונותינו כלפיו, \u0003ואם אין אתה הורגנו — הרבה הורגים\u0004 אחרים \u0003יש לו למקום,\u0004 ואם לא יהרגו אותנו בני אדם — \u0003והרבה דובין ואריות יש לו למקום בעולמו שפוגעין בנו והורגין אותנו. אלא, לא מסרנו הקדוש ברוך הוא בידך\u0004 אף שהיה יכול להורגנו בדרך אחרת, \u0003אלא\u0004 מפני \u0003שעתיד ליפרע דמינו מידך.\u0004 \u0003אף על פי כן\u0004 לא חשש לדבריהם ואף \u0003הרגן מיד. אמרו: לא זזו משם\u0004 ממקום ההריגה \u0003עד שבאו דיופלי\u0004 (זוג שליחים) \u0003מרומי\u0004 שקיבלו ייפוי כוח להסירו משלטונו ולעונשו, \u0003ופצעו את מוחו בגיזרין\u0004 של עץ והרגוהו. וכיון שאירע הדבר כך, וראו הכל כיצד הקדוש ברוך הוא נפרע משונאי ישראל, קבעוהו כיום חג.","","שנינו במשנה: \u0003אין גוזרין תענית על הצבור בתחלה בחמישי,\u0004 כדי שלא לגרום בכך להפקעת השערים, ועוד \u0003אין גוזרין תענית בראשי חדשים\u0004 בחנוכה ובפורים, ואם התחילו כבר בתעניות אין מפסיקים. ושואלים: \u0003וכמה הויא\u0004 \u0005[היא]\u0006 \u0003התחלה\u0004 לענין זה? \u0003רב אחא אמר: שלש\u0004 תעניות קודם לכן. \u0003ר' אסי אמר: אחת.\u0004","\u0003אמר רב יהודה אמר רב:\u0004 כל הלכה \u0003זו\u0004 שתענית שאירעה בימים טובים אף אם התחיל אין משלים להתענות עד הערב, היא \u0003דברי ר' מאיר שאמר\u0004 זאת \u0003משום\u0004 (משמו) של \u0003רבן (שמעון בן) גמליאל. אבל חכמים אומרים:\u0004 אם היתה תענית ביום כזה — \u0003מתענה ומשלים\u0004 להתענות עד הערב. \u0003דרש מר זוטרא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב הונא: הלכה\u0004 למעשה היא ש\u0003מתענה ומשלים.\u0004","","\u0003סדר תעניות אלו\u0004 שנתפרש בפרק ראשון, על התעניות בדרגות שונות והפסקות הזמן ביניהן הוא \u0003האמור ברביעה ראשונה\u0004 שלא ירדו בה גשמים. \u0003אבל צמחים ששנו\u0004 שהשתנה מראיהם מפני מחלה — \u0003מתריעין עליהן מיד\u0004 ואין ממתינים כלל. \u0003וכן\u0004 כ\u0003שפסקו גשמים בין גשם לגשם ארבעים יום — מתריעין עליהן\u0004 מיד, \u0003מפני שהיא מכת בצורת.\u0004","\u0003ירדו\u0004 גשמים די \u0003לצמחין אבל לא ירדו\u0004 מספיק בשביל ה\u0003אילן,\u0004 או ירדו גשמים הראויים \u0003לאילן ולא לצמחין\u0004 אחרים, ירדו גשמים הראויים \u0003לזה ולזה אבל לא\u0004 כדי \u0003ל\u0004מלאות \u0003בורות, לשיחין\u0004 (בורות מאורכים) \u0003ולמערות\u0004 (בורות מכוסים בתיקרה) לאגור בהם מים לצורך הקיץ — \u0003מתריעין עליהן מיד. וכן עיר שלא ירדו עליה גשמים\u0004 אף על פי שמסביב לה ירדו, וכמו \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והמטרתי על עיר אחת ועל עיר אחת לא אמטיר, חלקה אחת תמטר\u0004 וחלקה אשר לא תמטיר עליה תיבש\u0003\"\u0004 (עמוס ד, ז), שמשמע שדבר כזה סימן קללה הוא —"],["\u0003אותה העיר מתענה ומתרעת, וכל סביבותיה מתענות\u0004 שמצטרפות לתענית עמה, אבל \u0003לא מתריעות. ר' עקיבא אומר\u0004 לא כן: אלא \u0003מתריעות\u0004 בשופר \u0003ולא מתענות. וכן עיר שיש בה דבר או מפולת — אותה העיר מתענה ומתרעת, וכל סביבותיה מתענות ולא מתריעות, ר' עקיבא אומר: מתריעות ולא מתענות.\u0004","ומבארים: \u0003איזהו דבר,\u0004 מתי רואים מיתות תכופות בעיר כמגפה שאפשר לקרוא לה דבר? ומשיבים: \u0003עיר המוציאה חמש מאות רגלי,\u0004 כלומר, שיש בה חמש מאות איש \u0003ויצאו ממנה שלשה מתים בשלשה ימים זה אחר זה — הרי זה דבר,\u0004 ואם מתו \u0003פחות מכאן\u0004 (ממספר זה) — \u0003אין זה דבר,\u0004 שאין להחשיבו כמגיפה אלא כמחלה רגילה.","\u0003על\u0004 צרות \u0003אלו מתריעין\u0004 באמירת \"עננו\" בתפילה \u0003בכל מקום: על השדפון\u0004 (מחלת התבואה), \u0003ועל הירקון\u0004 שבתבואה, \u0003ועל הארבה, ועל החסיל\u0004 (מין אחר של חגבים הבא בלהקות גדולות) שהגיעו למקום, \u0003ועל החיה רעה\u0004 המסוכנת לבני אדם שפשטה ביישוב, \u0003ועל החרב,\u0004 כלומר, כשעוברים גדודי צבא אויב — \u0003מתריעין עליה, מפני שהיא מכה מהלכת\u0004 שעוברת ממקום למקום ולכן מתריעים עליהן בכל מקום.","\u0003מעשה שירדו זקנים מירושלים לעריהם\u0004 ברחבי ארץ ישראל, \u0003וגזרו תענית על שנראה כמלא פי תנור שדפון ב\u0004עיר \u0003אשקלון\u0004 וגזרו משום כך תענית בכל ארץ ישראל, שכן היא מכה מהלכת. \u0003ועוד גזרו תענית על שאכלו זאבים שני תינוקות בעבר הירדן. ר' יוסי אומר: לא על שאכלו, אלא על שנראו\u0004 שני זאבים אלה במקום ישוב.","\u0003על\u0004 מאורעות \u0003אלו מתריעין\u0004 אפילו \u0003בשבת: על עיר שהקיפוה נכרים\u0004 במצור, \u0003או נהר\u0004 העולה על גדותיו, \u0003ועל הספינה המיטרפת\u0004 (העומדת לטבוע) \u0003בים. ר' יוסי אומר:\u0004 מתריעים בשבת \u0003לעזרה, ולא לצעקה\u0004 בתפילה. \u0003שמעון התימני\u0004 (מהעיר תמנה) \u0003אומר: אף על הדבר\u0004 מתריעים בשבת \u0003ולא הודו לו חכמים.\u0004","ומוסיפים: בכלל, \u0003על כל צרה שלא תבוא\u0004 (לשון נקיה, כלומר: על כל צרה שתבוא) \u0003על הצבור — מתריעין עליהן, חוץ מרוב גשמים,\u0004 שאף שצרה היא, כיון שהמים בכלל לברכה הם — אין מתריעים עליה. ומספרים: \u0003מעשה שאמרו לו לחוני המעגל: התפלל שירדו גשמים. אמר להם: צאו והכניסו תנורי פסחים\u0004 אותם תנורי חרס שבהם היו אופים את קרבן הפסח \u0003בשביל שלא ימוקו\u0004 (ימסו במים), שמובטח היה שיירדו גשמים מרובים. \u0003התפלל ולא ירדו גשמים\u0004 כלל.","\u0003מה עשה? עג עוגה\u0004 (יצר מעגל) באדמה \u0003ועמד בתוכה, ואמר לפניו: רבונו של עולם! בניך שמו פניהם עלי, שאני כבן בית לפניך,\u0004 על כן \u0003נשבע אני בשמך הגדול שאיני זז מכאן עד שתרחם על בניך\u0004 ותיענה לבקשתם להורדת גשמים. \u0003התחילו גשמים מנטפין\u0004 בטיפות קטנות בלבד. \u0003אמר: לא כך שאלתי\u0004 (ביקשתי), \u0003אלא גשמי בורות שיחין ומערות,\u0004 כלומר, גשמים מרובים עד שיתמלאו מהם אף בורות המים, ויספיקו לכל השנה. \u0003התחילו\u0004 גשמים \u0003לירד בזעף. אמר: לא כך שאלתי\u0004 (ביקשתי), \u0003אלא גשמי רצון ברכה ונדבה\u0004 ולא גשמים מזיקים.","\u0003ירדו\u0004 גשמים \u0003כתקנן,\u0004 אבל המשיכו וירדו כה הרבה \u0003עד שיצאו ישראל מירושלים להר הבית מפני הגשמים\u0004 שמרוב הגשמים נתמלאה העיר במים עד שהיו צריכים להמלט למקום גבוה יותר. \u0003באו ואמרו לו: כשם שהתפללת עליהם שירדו — כך התפלל שילכו להן. אמר להם: צאו וראו אם נמחית אבן הטועין\u0004 (אבן גדולה שהיתה בעיר שעליה הכריזו על האבידות ועל המציאות) כלומר, בלשון גוזמה אמר: אם לא הגיעו הגשמים עד כדי כך — אין מן הראוי לבקש שיפסקו.","\u0003שלח לו\u0004 נשיא הסנהדרין באותו הדור \u0003שמעון בן שטח: אלמלא\u0004 (אם לא) \u0003חוני אתה — גוזרני עליך נידוי\u0004 על שאתה מדבר בלשון זו כלפי מעלה. \u0003אבל מה אעשה לך, שאתה מתחטא\u0004 (מתפנק) \u0003לפני המקום ועושה לך רצונך, כבן שהוא מתחטא על אביו ועושה לו רצונו, ועליך הכתוב אומר: \"\u0004גיל יגיל אבי צדיק ויולד חכם ישמח בו. \u0003ישמח אביך ואמך ותגל יולדתך\"\u0004 (משלי כג, כד-כה).","ועוד הלכה בתעניות: \u0003היו מתענין\u0004 על הגשם \u0003וירדו להם גשמים,\u0004 אם ירדו הגשמים \u0003קודם הנץ החמה — לא ישלימו\u0004 תעניתם עד לערב, אם ירדו \u0003לאחר הנץ החמה — ישלימו. ר' אליעזר אומר,\u0004 כך יש לחלק: אם ירדו \u0003קודם חצות\u0004 היום — \u0003לא ישלימו,\u0004 ירדו \u0003לאחר חצות — ישלימו.\u0004","מסופר: \u0003מעשה שגזרו תענית בלוד\u0004 על שלא ירדו גשמים, \u0003וירדו להם גשמים קודם חצות\u0004 יום התענית, \u0003אמר להם ר' טרפון: צאו\u0004 מיד \u0003ואכלו ושתו, ועשו יום טוב. ויצאו ואכלו ושתו ועשו יום טוב, ובאו בין הערבים\u0004 לבית הכנסת \u0003וקראו הלל הגדול\u0004 להודות על שנשמעה תפילתם.","שנינו במשנה: \u0003סדר תעניות האלו האמור ברביעה ראשונה. ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003רביעה ראשונה ושניה לשאול\u0004 ולבקש גשמים, ורק \u0003שלישית להתענות!\u0004","\u0003אמר רב יהודה: הכי קאמר\u0004 \u0005[כך אמר,\u0006 כך יש לפרש\u0005]:\u0006 \u0003סדר תעניות האמור אימתי — בזמן שיצאה רביעה ראשונה ושניה ושלישית ולא ירדו גשמים. אבל\u0004 אם \u0003ירדו גשמים ברביעה ראשונה, וזרעו\u0004 מיד \u0003ולא צמחו\u0004 משום שלא היו גשמי הרביעה מספיקים, \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003צמחו\u0004 מעט \u0003וחזרו ונשתנו\u0004 שהחלו נובלים משום שלא באו גשמים אחרי רביעה ראשונה — \u0003מתריעין עליהן מיד.\u0004","\u0003אמר רב נחמן: דוקא נשתנו, אבל\u0004 אם \u0003יבשו\u0004 לגמרי — \u0003לא\u0004 מתריעים, שאין טעם להתענות על דבר שאין לו תקנה. ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שכך הוא, שהרי \u0003נשתנו תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]!\u0006 ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 מה שאמר רב נחמן אלא \u0003דאקון\u0004 \u0005[שהתחזקו\u0006 קצת\u0005]\u0006 הצמחים לאחר שהתייבשו, ונראה שלא יגדלו יותר וכל תבואת השנה תפסד. \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003אקנתא מילתא היא\u0004 \u0005[התחזקות\u0006 זו \u0005דבר הוא]\u0006 ויש להם עוד תקנה בתפילה, לכך \u0003קמשמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין תקנה לדבר.","שנינו במשנה בין דברים שמתריעים עליהם: \u0003וכן שפסקו גשמים בין גשם לגשם\u0004 ארבעים יום, מפני שהיא מכת בצורת. ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 לשון זו \u0003\"מכת בצורת\"\u0004 הלא זו עדיין אינה נחשבת כבצורת! \u0003אמר רב יהודה אמר רב\u0004 כך יש להבין: אי ירידת גשמים במשך ארבעים יום בין גשם לגשם, היא \u0003מכה המביאה לידי בצורת.\u0004 ובענין זה \u0003אמר רב נחמן: נהרא אנהרא\u0004 \u0005[\u0006מ\u0005נהר לנהר],\u0006 כלומר, כשאין תבואה צומחת במקום אחד אבל יש אפשרות להביאה לאותו מקום דרך הנהרות, מאזור אחר שבו צומחת התבואה —"],["\u0003בצורתא\u0004 \u0005[בצורת].\u0006 אם צריך להביא את התבואה מ\u0003מדינתא אמדינתא\u0004 \u0005[\u0006מ\u0005מדינה למדינה]\u0006 — הרי זה \u0003כפנא\u0004 \u0005[רעב].\u0006 \u0003ואמר ר' חנינא:\u0004 אם \u0003סאה\u0004 חיטים נמכרת \u0003בסלע ושכיחא\u0004 \u0005[ומצויה]\u0006 — הרי זו \u0003בצורתא\u0004 \u0005[בצורת],\u0006 שמחיר התבואה מרובה, אבל התבואה מצויה למי שבידו כסף. אבל אם \u0003ארבעה\u0004 סאין בסלע \u0003ולא שכיחא\u0004 \u0005[מצויה]\u0006 התבואה כלל — הרי זה \u0003כפנא\u0004 \u0005[רעב].\u0006","\u0003אמר ר' יוחנן: לא שנו\u0004 דבר זה \u0003אלא בזמן שהמעות בזול,\u0004 כלומר, שהכסף מצוי אצל הבריות, \u0003ו\u0004מחיר ה\u0003פירות ביוקר,\u0004 יתר על המידה, \u0003אבל מעות ביוקר\u0004 שאין הכסף מצוי אצל הבריות אף שה\u0003פירות בזול — מתריעין עליה מיד,\u0004 מפני שהיא מכת רעב. שאף שמחיר הפירות זול, אין באפשרות האנשים לקנותם בשל המחסור בכסף. ש\u0003אמר ר' יוחנן: נהירנא כד הוו קיימי\u0004 \u0005[זוכר אני כאשר עמדו,\u0006 היו\u0005]\u0006 \u0003ארבעה סאין בסלע, והוו נפישי נפיחי כפן בטבריא מדלית\u0004 \u0005[והיו מרובים נפוחי רעב בטבריה משום\u0006 \u0005שאין\u0006 להם\u0005]\u0006 אפילו \u0003איסר\u0004 לקנות בו מזון.","שנינו במשנה: \u0003ירדו\u0004 גשמים הראויים \u0003לצמחין אבל לא\u0004 ראויים \u0003לאילן,\u0004 או להיפך — מתריעים עליהם מיד. ומסבירים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 שראויים הם \u0003לצמחים ולא לאילן משכחת לה\u0004 \u0005[\u0006יכול אתה \u0005למצוא\u0006 אפשרות \u0005כזו],\u0006 \u0003דאתא ניחא\u0004 \u0005[שבא,\u0006 ירד גשם \u0005נוח\u0006 וקל\u0005],\u0006 אבל \u0003ולא אתיא רזיא\u0004 \u0005[בא,\u0006 ירד גשם \u0005עז]\u0006 ואין זה מספיק לאילנות. וכן גשם הראוי \u0003לאילן ולא לצמחים\u0004 כיצד — \u0003דאתיא רזיא\u0004 \u0005[שבא\u0006 גשם \u0005עז]\u0006 \u0003ולא אתיא ניחא\u0004 \u0005[בא\u0006 גשם \u0005נוח],\u0006 ואיננו מועיל לצמחים הקטנים.","וכן גשם הראוי \u0003לזה ולזה אבל לא לבורות ולא לשיחין ומערות משכחת לה\u0004 \u0005[מוצא אתה אותה],\u0006 כגון \u0003דאתיא רזיא וניחא\u0004 \u0005[ירד\u0006 גם גשם \u0005עז ו\u0006גם גשם \u0005נוח]\u0006 ומשקה את כל הגידולים כראוי, \u0003מיהו טובא\u0004 \u0005[אבל הרבה]\u0006 \u0003לא אתיא\u0004 \u0005[בא]\u0006 ואינו מספיק למלא את הבורות גם לקיץ. \u0003אלא הא דתניא\u0004 \u0005[זו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003ירדו\u0004 גשמים הראויים \u0003לבורות לשיחין ולמערות אבל לא\u0004 ראויים \u0003לזה ולזה,\u0004 לאילן ולצמחים, \u0003היכי משכחת לה\u0004 \u0005[כיצד מוצא אתה אותה],\u0006 שאם מספיק הגשם כדי למלא את הבורות, ודאי שהוא מספיק לצמחים! ומשיבים: \u0003דאתיא בשפיכותא\u0004 \u0005[שבאו בשפיכה],\u0006 שאם ירדו הרבה גשמים בבת אחת אינם מועילים לגידולים ואפילו לאילנות.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מתריעין על האילנות,\u0004 שלא ירדו להם גשמים די צורכם \u0003בפרוס\u0004 (סמוך לחג) \u0003הפסח,\u0004 משום שעד אז יכולים הגשמים להועיל לאילנות, ו\u0003על הבורות ושיחין ומערות\u0004 שלא נתמלאו אפילו \u0003בפרוס\u0004 (סמוך) אל \u0003החג\u0004 (סוכות). \u0003ו\u0004על כולן, \u0003אם אין להן מים לשתות\u0004 באותה שעה, ולא רק שאין מים במאגרים — \u0003מתריעין עליהן מיד.\u0004","\u0003ואיזהו \"מיד\" שלהם — שני וחמישי ושני.\u0004 בשבוע שבו התברר הדבר, אבל לא תמיד באותו יום. \u0003ועל כולן\u0004 על השיבושים בירידת הגשמים \u0003אין מתריעין עליהן אלא באפרכיא\u0004 (מחוז) \u0003שלהן\u0004 ולא במקום אחר שבו יורדים הגשמים כסדרם.","אם יש מחלת \u0003אסכרא\u0004 מתפשטת, \u0003בזמן שיש בה מיתה\u0004 שהיא באה בצורה קשה הגורמת מיתה לחולים בה — \u0003מתריעין עליה,\u0004 ו\u0003בזמן שאין בה מיתה — אין מתריעין עליה. ומתריעין על הגובאי\u0004 (ארבה) \u0003בכל שהוא\u0004 אפילו באו רק מעטים, שמן הסתם יבואו גם אחרים, אבל לא על בוא החגב. \u0003ר' שמעון בן אלעזר אומר: אף על\u0004 בוא \u0003החגב\u0004 מתריעים בכל שהוא, שגם הם עלולים להביא לידי בצורת אם יתרבו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003מתריעין על האילנות בשאר שני שבוע,\u0004 כלומר, בשש שנות עבודת האדמה, אבל לא בשנת השמיטה עצמה, שהרי אין עובדים את האדמה באותה שנה. \u0003על הבורות ועל השיחין\u0004 (בורות מאורכים) \u0003ועל המערות\u0004 (בורות מכוסים בתיקרה), אם לא ירדו גשמים כדי למלאותם, מתריעים \u0003אפילו ב\u0004שנת ה\u0003שביעית. רבן שמעון בן גמליאל אומר: אף על האילנות\u0004 מתריעים \u0003בשביעית מפני שיש בהן פרנסה לעניים,\u0004 שהרי העניים סומכים בשנה זו על האילנות, ונהנים מפירותיהם ואם לא ירדו גשמים מתקפחת פרנסת העניים.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003מתריעין על האילנות בשאר שני שבוע. על הבורות, על השיחין, ועל המערות אפילו בשביעית, רבן שמעון בן גמליאל אומר: אף על האילנות.\u0004 וכן \u0003מתריעין על הספיחין\u0004 (כגון ירקות הגדלים מעצמם) \u0003בשביעית, מפני שיש בהן פרנסה לעניים\u0004 שהם מותרים באכילתם.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' אלעזר בן פרטא: מיום שחרב בית המקדש נעשו גשמים צימוקין לעולם,\u0004 כלומר, במידה מצומצמת, ולא כדי כל הצורך. ש\u0003יש שנה שגשמיה מרובין, ויש שנה שגשמיה מועטין. יש שנה שגשמיה יורדין בזמנן, ויש שנה שאין גשמיה יורדין בזמנן.\u0004","ומסבירים: \u0003שנה שגשמיה יורדין בזמנן, למה הוא דומה — לעבד שנתן לו רבו פרנסתו,\u0004 כלומר, את המזונות שצריך לאותו שבוע \u0003באחד בשבת\u0004 (ביום ראשון), ובשל כך \u0003נמצאת עיסה נאפית\u0004 במשך השבוע \u0003כתיקנה,\u0004 שהרי יש לו פנאי במשך כל ימות השבוע לאפותה כתיקנה, \u0003ו\u0004מאחר שנאפית זו כתיקנה והיא פת ראויה, הריהי אף \u0003נאכלת כתיקנה. שנה שאין גשמיה יורדין בזמנן, למה הוא דומה — לעבד שנתן לו רבו פרנסתו בערב שבת,\u0004 שאין זמן מספיק כדי לעשות מלאכתו כראוי, ולכך \u0003נמצאת עיסה נאפית שלא כתיקנה, ונאכלת\u0004 בשל כך \u0003שלא כתיקנה.\u0004","\u0003שנה שגשמיה מרובין, למה הוא דומה — לעבד שנתן לו רבו פרנסתו\u0004 למשך זמן \u0003בבת אחת,\u0004 וכיון שעושה את כל המלאכות בתבואה בבת אחת \u0003נמצאו ריחים טוחנות מן הכור מה שטוחנות מן הקב\u0004 שהרי תמיד יש פחת בטחינה, ובעיקרו פחת זה שווה כמעט בכל פעם שטוחנים ואיננו פוחת לפי ריבוי או מיעוט התבואה, וכן \u0003ונמצאת עיסה אוכלת\u0004 (פוחתת) על ידי בצק שנדבק בעריבה בה הוא נילוש ושאר פחתים \u0003מן הכור כמו\u0004 ש\u0003אוכלת מן הקב,\u0004 ונשאר בידו הרבה.","\u0003שנה שגשמיה מועטין, למה הוא דומה — לעבד שנתן לו רבו פרנסתו מעט מעט, נמצאו ריחיים מה שטוחנות\u0004 וכותתות \u0003מן הכור טוחנות מן הקב\u0004 ומפסיד בכל קב וקב. וכן \u0003נמצאת עיסה כמה שנאכלת\u0004 (ומפסידה) \u0003מן הכור, אוכלת מן הקב\u0004 ובסך הכל נשאר בידו פחות.","\u0003דבר אחר: בזמן שגשמיה מרובין למה הוא דומה — לאדם שמגבל את הטיט, אם יש לו מים רבים — מים אינן כלין, והטיט מגובל יפה. אם יש לו מים מועטין — מים כלים, והטיט אינו מתגבל יפה,\u0004 שמפני מיעוט המים אין גם חלק מן הטיט מגובל די צורכו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003פעם אחת עלו כל ישראל לרגל לירושלים ולא היה להם מים לשתות, הלך נקדימון בן גוריון\u0004 שהיה אחד מעשירי ירושלים \u0003אצל הגמון\u0004 (שר) גוי \u0003אחד, אמר לו: הלויני שתים עשרה מעיינות\u0004 (כלומר, בורות) \u0003מים לעולי רגלים, ואני אתן\u0004 (אחזיר) \u0003לך שתים עשרה עינות מים. ואם איני נותן לך — הריני נותן לך\u0004 תמורתם \u0003שתים עשרה ככר כסף, וקבע לו זמן\u0004 להחזרת המים.","\u0003כיון שהגיע הזמן\u0004 שקבעו \u0003ולא ירדו גשמים\u0004 באותו יום, \u0003בשחרית שלח לו\u0004 אותו אדון לנקדימון: \u0003שגר\u0004 (שלח) \u0003לי או מים או מעות שיש לי בידך\u0004 (שאתה חייב לי). \u0003שלח לו\u0004 נקדימון בן גוריון: \u0003עדיין יש לי זמן, כל היום כולו שלי הוא. בצהריים שלח לו\u0004 אותו אדון שוב: \u0003שגר לי או מים או מעות שיש לי בידך. שלח לו: עדיין יש לי שהות ביום. במנחה שלח לו: שגר לי או מים או מעות שיש לי בידך. שלח לו: עדיין יש לי שהות ביום. לגלג עליו אותו הגמון, אמר: כל השנה כולה לא ירדו גשמים,\u0004"],["\u0003ועכשיו ירדו גשמים?! נכנס לבית המרחץ בשמחה\u0004 על סכום הכסף הגדול שהוא עומד לקבל. \u0003עד שהאדון נכנס בשמחתו לבית המרחץ, נקדימון נכנס לבית המקדש כשהוא עצוב. נתעטף\u0004 בטליתו, \u0003ועמד בתפלה.\u0004","\u0003אמר לפניו: רבונו של עולם! גלוי וידוע לפניך שלא לכבודי עשיתי, ולא לכבוד בית אבא עשיתי, אלא לכבודך עשיתי, שיהו מים מצויין לעולי רגלים. מיד נתקשרו שמים בעבים\u0004 (עננים), \u0003וירדו גשמים\u0004 כה רבים \u0003עד שנתמלאו שתים עשרה מעינות מים והותירו.\u0004","\u0003עד שיצא אדון מבית המרחץ, נקדימון בן גוריון יצא מבית המקדש.\u0004 ו\u0003כשפגעו\u0004 (פגשו) \u0003זה בזה, אמר לו\u0004 נקדימון: \u0003תן לי דמי מים יותר\u0004 (יתרים) \u0003שיש לי בידך! אמר לו\u0004 אותו אדון: \u0003יודע אני שלא הרעיש הקדוש ברוך הוא את עולמו\u0004 שירדו גשמים אלה עכשיו \u0003אלא בשבילך, אלא עדיין יש לי פתחון פה\u0004 (נימוק, טענה) \u0003עליך, שאוציא\u0004 בשל טענה זו \u0003ממך את מעותיי,\u0004 שהרי לא פרעת לי חובך ביום שנקבע לפרעון, \u0003ש\u0004כן \u0003כבר שקעה חמה, וגשמים\u0004 שירדו — לאחר מכן ירדו ולכך \u0003ברשותי ירדו.\u0004","\u0003חזר ונכנס\u0004 נקדימון \u0003לבית המקדש, ונתעטף\u0004 בטליתו \u0003ועמד בתפלה, ואמר לפניו: רבונו של עולם! הודע\u0004 (הראה) \u0003שיש לך אהובים בעולמך! מיד נתפזרו העבים\u0004 (עננים) \u0003וזרחה החמה. באותה שעה אמר לו האדון: אילו לא נקדרה\u0004 (נקבה ויצאה) \u0003החמה\u0004 מבין העננים \u0003היה לי פתחון פה עליך ש\u0004בגללו \u0003אוציא ממך מעותיי. תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003לא נקדימון שמו\u0004 האמיתי, \u0003אלא בוני שמו, ולמה נקרא שמו נקדימון\u0004 — מפני \u0003שנקדרה חמה בעבורו.\u0004","ומוסיפים, \u0003תנו רבנן: שלשה נקדמה להם חמה בעבורן,\u0004 שזרחה להם השמש שלא בזמנה, והם: \u0003משה, ויהושע, ונקדימון בן גוריון.\u0004 ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003נקדימון בן גוריון — גמרא\u0004 \u0005[מסורת]\u0006 היא בידינו, כמסופר. \u0003יהושע נמי\u0004 \u0005[גם כן]\u0006 \u0003קרא\u0004 \u0005[כתוב]\u0006 הוא, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וידם השמש וירח עמד\u0004 עד יקום גוי אויביו\u0003\"\u0004 (יהושע י, יג). \u0003אלא משה מנלן\u0004 \u0005[מנין לנו]\u0006 שזרחה חמה עבורו שלא כדרכה?","\u0003אמר ר' אלעזר: אתיא\u0004 \u0005[בא,\u0006 נלמד\u0005]\u0006 הדבר בגזירה שווה, מן המילים \u0003\"אחל\" \"אחל\", כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 למשה: \"היום הזה \u0003אחל תת פחדך\u0004 ויראתך על פני העמים תחת כל השמים\" (דברים ב, כה), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 ביהושע: \"היום הזה \u0003אחל גדלך\u0004 בעיני כל ישראל אשר ידעון כי כאשר הייתי עם משה אהיה עמך\" (יהושע ג, ז), ללמדנו שכל הניסים שאירעו ליהושע אירעו גם למשה.","\u0003ר' שמואל בר נחמני אמר: אתיא\u0004 \u0005[בא\u0006 נלמד\u0005]\u0006 הדבר מגזירה שווה \u0003\"תת\" \"תת\", כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 במשה: \u0003\"אחל תת פחדך\"\u0004 (דברים ב, כה), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]:\u0006 \"אז ידבר יהושע לה' \u0003ביום תת ה' את האמרי\u0004 לפני בני ישראל ויאמר לעיני ישראל שמש בגבעון דום וירח בעמק אילון\" (יהושע י, יב).","\u0003ר' יוחנן אמר: אתיא מגופיה דקרא\u0004 \u0005[בא,\u0006 נלמד הדבר \u0005מגופו של הכתוב],\u0006 שנאמר במשה: \u0003\"\u0004אחל תת פחדך ויראתך על פני העמים תחת כל השמים \u0003אשר ישמעון שמעך ורגזו וחלו מפניך\", אימתי רגזו וחלו מפניך\u0004 כל העמים בכל העולם (\"תחת כל השמים\") — \u0003בשעה שנקדמה לו חמה למשה.\u0004","שנינו במשנה בענין \u0003וכן עיר\u0004 אחת \u0003שלא ירדו עליה גשמים\u0004 אף שירדו במקומות אחרים, והובא הכתוב \"והמטרתי על עיר אחת ועל עיר אחת לא אמטיר\" (עמוס ד, ז). \u0003אמר רב יהודה אמר רב: ושתיהן לקללה,\u0004 שאף ירידת הגשמים בעיר אחת — לקללה נאמרה, שמדובר בשטפונות משחיתים.","מאחר שהביאו מאמר של רב יהודה אמר רב, לפיו יש להבין הכתוב באופן הנראה היפך המשמעות הפשוטה, מביאים מה שאמר כעין זה על הכתוב \u0003\"היתה ירושלים לנדה ביניהם\"\u0004 (איכה א, יז) \u0003אמר רב יהודה אמר רב:\u0004 פסוק זה אף שמשמעותו הפשוטה היא לקללה, בעצם הוא \u0003לברכה,\u0004 לפי שמדמה את ירושלים \u0003כנדה,\u0004 ופירושו: \u0003מה נדה יש לה\u0004 בסופו של דבר \u0003היתר\u0004 לאחר שנגמרים ימי הטומאה ונטהרת, \u0003אף ירושלים יש לה תקנה\u0004 מחורבנה.","וכן על הכתוב \u0003\"היתה כאלמנה\"\u0004 (איכה א, א) \u0003אמר רב יהודה:\u0004 דימוי זה הוא \u0003לברכה,\u0004 ומדייק בלשון: אינה אלא \u0003כאלמנה\u0004 (כמו אלמנה) \u0003ולא אלמנה ממש, אלא כאשה שהלך בעלה למדינת הים\u0004 ובאין בעלה עמה הריהי כאלמנה, אבל \u0003ודעתו לחזור עליה.\u0004","וכן פירוש הכתוב: \u0003\"וגם אני נתתי אתכם נבזים ושפלים\"\u0004 (מלאכי ב, ט), \u0003אמר רב יהודה:\u0004 גם זה \u0003לברכה, דלא מוקמי מינן\u0004 \u0005[שאין מעמידים,\u0006 ממנים \u0005מאתנו]\u0006 \u0003לא רישי נהרי\u0004 \u0005[ראשי נהרות]\u0006 \u0003ולא גזיריפטי\u0004 \u0005[שוטרים],\u0006 ואף שבעיקרו הוא משום שהם מבזים אותנו, מכל מקום ברכה היא לנו, שאנו נפטרים מתפקידים קשים ובלתי נעימים אלה.","נאמר בנבואת אחיה, שקילל את ישראל ואמר: \u0003\"והכה ה' את ישראל כאשר ינוד הקנה במים\"\u0004 (מלכים א', יד, טו), \u0003אמר רב יהודה אמר רב:\u0004 דבר זה הוא באמת \u0003לברכה.\u0004 וכפי ש\u0003אמר\u0004 זאת בהרחבת ביאור \u0003ר' שמואל בר נחמני אמר ר' יונתן: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"נאמנים פצעי אוהב ונעתרות נשיקות שונא\"\u0004 (משלי כז, ו) — \u0003טובה קללה שקילל אחיה השילוני את ישראל יותר מברכה שברכן בלעם הרשע.\u0004","\u0003אחיה השילוני קללן בקנה,\u0004 בכך ש\u0003אמר להם לישראל: \"והכה ה' את ישראל כאשר ינוד הקנה\u0004 במים \u0003\"\u0004, אבל קללה זו היא באמת ברכה — \u0003מה קנה זה עומד במקום מים, וגזעו מחליף\u0004 שאם נחתך הוא צומח מחדש \u0003ושרשיו מרובין\u0004 ביחס לגודלו, \u0003ואפילו כל הרוחות שבעולם באות ונושבות בו — אין מזיזות אותו ממקומו,\u0004 שאיננו נעקר על ידן, \u0003אלא הולך\u0004 (מתנענע, נד) \u0003ובא עמהן, דממו הרוחות — עמד הקנה\u0004 שוב \u0003במקומו,\u0004 כך יהיו ישראל, שלאחר הצרות הבאות עליהם הרי הם חוזרים למקומם בהשקט ובטח.","\u0003אבל בלעם הרשע\u0004 שבירך את ישראל \u0003בירכן בארז, שנאמר: \"כארזים עלי מים\"\u0004 (במדבר כד, ו), \u0003מה ארז זה אינו עומד במקום מים, ואין גזעו מחליף, ואין שרשיו מרובין.\u0004 אמנם \u0003אפילו כל הרוחות שבעולם נושבות בו — אין מזיזות אותו ממקומו,\u0004 אבל \u0003כיון שנשבה בו רוח דרומית — עוקרתו והופכתו על פניו. ולא עוד אלא שזכה קנה ליטול הימנו קולמוס\u0004 (עט) \u0003לכתוב בו ספר תורה נביאים וכתובים,\u0004 ואם כן בסופו של דבר הקללה בקנה עדיפה מן הברכה בארז.","ועוד בשבחו של הקנה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003לעולם יהא אדם רך כקנה\u0004 כלפי הבריות \u0003ואל יהא קשה כארז. מעשה שבא ר' אלעזר בן ר' שמעון ממגדל גדור מבית רבו, והיה רכוב על חמור ומטייל על שפת נהר\u0004 בשובו אל עירו \u0003ושמח שמחה גדולה, והיתה דעתו גסה\u0004 (גדולה, גאה) \u0003עליו מפני שלמד תורה הרבה\u0004 באותו פרק זמן ששהה בבית רבו,"],["\u0003נזדמן לו אדם אחד שהיה מכוער ביותר. אמר לו\u0004 אותו אדם: \u0003שלום עליך רבי! ולא החזיר לו\u0004 ר' אלעזר שלום. ו\u0003אמר לו\u0004 ר' אלעזר: \u0003ריקה\u0004 (ברנש) \u0003כמה מכוער אותו האיש! שמא כל בני עירך מכוערין כמותך? אמר לו\u0004 האיש: \u0003איני יודע, אלא לך ואמור לאומן שעשאני: \"כמה מכוער כלי זה שעשית\". כיון שידע\u0004 ר' אלעזר \u0003בעצמו שחטא\u0004 והעליב את האיש לחינם על מום שנולד עמו, \u0003ירד מן החמור ונשתטח לפניו\u0004 לפני האיש, \u0003ואמר לו: נעניתי לך\u0004 (חטאתי כנגדך), \u0003מחול לי! אמר לו: איני מוחל לך, עד שתלך לאומן שעשאני ואמור לו: כמה מכוער כלי זה שעשית.\u0004","\u0003היה\u0004 ר' אלעזר \u0003מטייל אחריו\u0004 אחרי אותו איש ומנסה לפייסו \u0003עד שהגיע לעירו. יצאו בני עירו\u0004 של ר' אלעזר \u0003לקראתו, והיו אומרים לו: שלום עליך רבי רבי, מורי מורי! אמר להם\u0004 האיש: \u0003למי אתם קורין רבי רבי? אמרו לו: לזה שמטייל אחריך. אמר להם: אם זה רבי — אל ירבו כמותו בישראל. אמרו לו: מפני מה\u0004 אומר אתה כך? \u0003אמר להם: כך וכך עשה לי\u0004 ואמר לי. \u0003אמרו לו: אף על פי כן, מחול לו,\u0004 כיון \u0003שאדם גדול בתורה הוא.\u0004","\u0003אמר להם: בשבילכם הריני מוחל לו, ובלבד\u0004 שיקבל על עצמו \u0003שלא יהא רגיל לעשות כן. מיד נכנס ר' אלעזר בן ר' שמעון\u0004 לבית המדרש, \u0003ודרש: לעולם יהא אדם רך כקנה ואל יהא קשה כארז,\u0004 שגסות הרוח גורמת לו לאדם לחטוא. \u0003ולפיכך,\u0004 לפי שהקנה רך וכנוע \u0003זכה קנה\u0004 \u0005[עט]\u0006 \u0003ליטול הימנה קולמוס לכתוב בו ספר תורה תפילין ומזוזות.\u0004","שנינו במשנה: \u0003\"וכן עיר שיש בה דבר או מפולת\",\u0004 היא עצמה מתרעת ומתענה והערים שסביבותיה רק מתענות ולא מתריעות ולדברי ר' עקיבא הריהן מתריעות ולא מתענות. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מפולת שאמרו\u0004 שנפלו כתלים וגדרות \u0003בריאות\u0004 (חזקות) \u0003ולא רעועות,\u0004 שנפלו אלה \u0003שאינן ראויות ליפול, ולא הראויות ליפול.\u0004","על לשון זה של הברייתא שואלים: \u0003הי ניהו\u0004 \u0005[אלו הן]\u0006 \u0003בריאות, הי ניהו\u0004 \u0005[אלו הן]\u0006 \u0003שאינן ראויות ליפול, הי נינהו\u0004 \u0005[אלו הן]\u0006 \u0003רעועות הי ניהו\u0004 \u0005[אלו הן]\u0006 \u0003ראויות ליפול,\u0004 ולכאורה יש כאן כפל דברים בלבד! ומשיבים: ראויות ליפול אינן דווקא רעועות, ו\u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 ש\u0003נפלו מחמת גובהייהו\u0004 \u0005[גובהן],\u0006 שהיו אכן בריאות אבל עם כל זה היו ראויות ליפול, משום שהיו גבוהות מדי. \u0003אי נמי דקיימן אגודא דנהרא\u0004 \u0005[או גם כן שהיו עומדות על שפת הנהר]\u0006 שאף שהן כשלעצמן בריאות, מכל מקום הן ראויות ליפול, ששפת הנהר איננה יציבה וגורמת שיפלו בנינים הבנויים שם.","ומסופר: \u0003כי ההיא אשיתא רעועה דהואי\u0004 \u0005[כמו אותו כותל רעוע שהיה]\u0006 \u0003בנהרדעא\u0004 ש\u0003לא הוה חליף\u0004 \u0005[שלא היו עוברים]\u0006 \u0003רב ושמואל תותה\u0004 \u0005[תחתיו]\u0006 \u0003אף על גב דקיימא באתרה תליסר שנין\u0004 \u0005[אף על פי שעמד במקומו שלוש עשרה שנה]\u0006 שסברו שכיון שהוא רעוע — מקום סכנה הוא. מסופר: \u0003יומא חד איקלע\u0004 \u0005[יום אחד הזדמן]\u0006 \u0003רב אדא בר אהבה להתם\u0004 \u0005[לשם]\u0006 והלך איתם, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל לרב\u0004 כשעברו שם: \u0003ניתי מר נקיף\u0004 \u0005[יבוא אדוני ויקיף]\u0006 את המקום, שלא נעבור תחת תיקרה זו! \u0003אמר ליה: לא צריכנא האידנא\u0004 \u0005[אין אנו צריכים\u0006 לזה \u0005עכשיו]\u0006 משום \u0003דאיכא\u0004 \u0005[שיש,\u0006 שנמצא\u0005]\u0006 \u0003רב אדא בר אהבה בהדן\u0004 \u0005[איתנו]\u0006 \u0003דנפיש זכותיה, ולא מסתפינא\u0004 \u0005[שמרובה זכותו, ואינני מתיירא]\u0006 מפני המפולת.","וכיוצא בזה מסופר: \u0003רב הונא הוה ליה ההוא חמרא בההוא ביתא רעיעא, ובעי לפנוייה\u0004 \u0005[היה לו יין בבית רעוע אחד, ורצה לפנותו]\u0006 משם, אבל פחד מפני המפולת, \u0003עייליה\u0004 \u0005[הכניס]\u0006 את \u0003רב אדא בר אהבה להתם\u0004 \u0005[לשם]\u0006 לאותו בית, \u0003משכיה בשמעתא עד דפנייה\u0004 \u0005[\u0006ו\u0005משך אותו\u0006 בשיחה \u0005ב\u0006דבר \u0005הלכה עד\u0006 שבינתיים \u0005פינו]\u0006 את כל היין משם, ואכן \u0003בתר דנפק נפל ביתא\u0004 \u0005[אחרי שיצא\u0006 משם \u0005נפל הבית].\u0006 \u0003ארגיש\u0004 \u0005[הרגיש]\u0006 \u0003רב אדא בר אהבה\u0004 בכל מה שנעשה \u0003איקפד\u0004 \u0005[\u0006ו\u0005הקפיד]\u0006 על כך.","ומסבירים: \u0003סבר לה כי הא\u0004 \u0005[סבור היה כמו זו]\u0006 ש\u0003אמר ר' ינאי: לעולם אל יעמוד אדם במקום סכנה ויאמר: עושין לי נס,\u0004 ולא יקרה לי דבר \u0003שמא אין עושין לו נס. ואם תימצי\u0004 (תמצא) \u0003לומר שעושין לו נס —\u0004 מכל מקום \u0003מנכין לו מזכיותיו\u0004 כנגד נס זה שנעשה לו. \u0003אמר רב חנן: מאי קרא\u0004 \u0005[מהו הכתוב]\u0006 המרמז על כך — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"קטנתי מכל החסדים ומכל האמת\u0004 אשר עשית את עבדך\" (בראשית לב, י), כלומר, ככל שנעשו לאדם חסדים מרובים יותר — הרי זכויותיו קטנות ומתמעטות.","כיון שסופרו מעשים שמהם נראתה גדלותו של רב אדא בר אהבה, — שואלים: \u0003מאי הוה עובדיה\u0004 \u0005[מה היו מעשיו\u0006 הגדולים\u0005]\u0006 של \u0003רב אדא בר אהבה?\u0004 ומסופר: \u0003כי הא דאתמר\u0004 \u0005[כמו זו שנאמרה]\u0006 במקום אחר, \u0003שאלו תלמידיו (את ר' זירא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ששאלו זאת) \u0003לרב אדא בר אהבה: במה\u0004 בזכות מה \u0003הארכת ימים? אמר להם: מימי לא הקפדתי בתוך ביתי\u0004 על בני ביתי, \u0003ולא צעדתי בפני מי שגדול ממני,\u0004 אלא נתתי כבוד לגדול ללכת לפני,","\u0003ולא הרהרתי\u0004 בדברי תורה \u0003במבואות המטונפות, ולא הלכתי ארבע אמות בלא תורה ובלא תפילין, ולא ישנתי בבית המדרש לא שינת קבע ולא שינת ארעי, ולא ששתי בתקלת חברי, ולא קראתי לחבירי בהכינתו\u0004 בכינוי שיש לו, \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 \u0003בחניכתו\u0004 בכינוי משפחתו.","ועוד מעשה בשבח גדולי הדור הקשור בכותל רעוע: \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרפרם בר פפא: לימא לן מר מהני מילי מעלייתא דהוה עביד\u0004 \u0005[יאמר לנו אדוני מאותם דברים טובים שהיה עושה]\u0006 \u0003רב הונא! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בינקותיה לא דכירנא, בסיבותיה דכירנא\u0004 \u0005[בצעירותו אינני זוכר\u0006 מה עשה, אבל \u0005בזיקנותו אני זוכר],\u0006 \u0003דכל יומא דעיבא הוו מפקין ליה בגהרקא דדהבא, וסייר לה לכולה מתא\u0004 \u0005[שכל יום מעונן היו מוציאים אותו באפריון של זהב, והיה מסייר בכל העיר].\u0006 \u0003וכל אשיתא דהוות רעיעתא, הוה סתר לה\u0004 \u0005[כותל שהיה רעוע, היה\u0006 מצווה \u0005לסתור אותו],\u0006 שחשש שלכאשר יירדו גשמים עלול ליפול ולהזיק. \u0003אי אפשר למרה\u0004 \u0005[אם אפשר לבעליו] —\u0006 \u0003בני לה\u0004 \u0005[\u0006היה הוא \u0005בונה אותו],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא אפשר — בני לה איהו מדידיה\u0004 \u0005[היה בונה אותו\u0006 רב הונא \u0005משלו].\u0006","\u0003וכל פניא דמעלי שבתא הוה משדר שלוחא לשוקא\u0004 \u0005[ובכל יום שישי אחר הצהריים היה שולח שליח לשוק]\u0006 \u0003וכל ירקא דהוה פייש להו לגינאי זבין ליה ושדי ליה לנהרא\u0004 \u0005[וכל ירק שהיה משתייר אצל הגננים\u0006 שמכרו ירקותיהם, \u0005היה קונה אותו וזורק אותו לנהר].\u0006 ושואלים: \u0003וליתביה\u0004 \u0005[ושיתן אותו]\u0006 \u0003לעניים!\u0004 ומשיבים: אם היה עושה כן \u0003זמנין דסמכא דעתייהו ולא אתו למיזבן\u0004 \u0005[פעמים שתסמוך דעתם על כך\u0006 שרב הונא מחלק להם ירקות \u0005ולא יבואו לקנות]\u0006 ובדיוק באותו שבוע לא ישארו ירקות בידי מוכרי הירק ולא יהיה לו מה לתת להם ונמצא מקפח את פרנסת העניים שלא יהיה להם מה לאכול. ושואלים: \u0003ולשדייה\u0004 \u0005[ושיזרקם]\u0006 \u0003לבהמה!\u0004 ומסבירים: \u0003קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003מאכל אדם אין מאכילים לבהמה,\u0004 משום ביזוי אוכלים.","ושואלים: אם כן \u0003ו\u0004ש\u0003לא ליזבניה\u0004 \u0005[שלא יקנה אותו],\u0006 את הירק \u0003כלל?\u0004 ומשיבים: \u0003נמצאת מכשילן לעתיד לבא\u0004 שאם יראו הגננים שאינם מוכרים את סחורתם לא יביאו ירקות לשבת, ולכן דאג שתמיד יהיה מי שיקנה מהם ירקות שלא יפסידו וימשיכו להביא.","ועוד היה מנהג לרב הונא, \u0003כי הוה ליה מילתא דאסותא\u0004 \u0005[כאשר היה לו דבר של רפואה],\u0006 כלומר, כשהגיעה אליו רפואה חדשה \u0003הוי מלי כוזא דמיא, ותלי ליה בסיפא דביתא\u0004 \u0005[היה ממלא כד מים ותולה אותו על סף הבית]\u0006 \u0003ואמר: כל דבעי ליתי ולישקול\u0004 \u0005[כל\u0006 מי \u0005שצריך\u0006 לכך \u0005שיבוא ויקח]\u0006 מרפואה זו. \u0003ואיכא דאמרי\u0004 \u0005[יש אומרים]:\u0006 \u0003מילתא דשיבתא הוה גמיר\u0004 \u0005[דבר סגולה,\u0006 הצלה ממזיקים \u0005היה למוד\u0006 במסורת\u0005],\u0006 שצריך לרחוץ ידים כדי להנצל \u0003והוה מנח כוזא דמיא ודלי ליה\u0004 \u0005[והיה מניח כד מים ותולה אותו]\u0006 \u0003ואמר: כל\u0004 מי ש\u0003צריך — ליתי וליעול דלא לסתכן\u0004 \u0005[יכנס\u0006 וירחץ כדי \u0005שלא יסתכן].\u0006","\u0003כי הוה כרך ריפתא הוה פתח לבביה\u0004 \u0005[כאשר היה בא\u0006 לסעוד \u0005היה פותח את דלתותיו]\u0006 \u0003ואמר: כל מאן דצריך ליתי וליכול\u0004 \u0005[כל מי שצריך שיבוא ויאכל]\u0006 \u0003אמר רבא: כולהו מצינא מקיימנא, לבר מהא דלא מצינא למיעבד\u0004 \u0005[את כולם,\u0006 כל מנהגי רב הונא, שאר הדברים שאמרת \u0005יכול\u0006 גם אני \u0005לקיים, חוץ מזו שאין אני יכול לעשות]\u0006"],["\u0003משום דנפישי בני חילא\u0004 \u0005[שרבים אנשי הצבא]\u0006 בעיר \u0003מחוזא\u0004 ואם אתן לכולם לאכול יכלה ממוני.","ועוד סיפור הקשור בכותל רעוע, \u0003אילפא ור' יוחנן הוו גרסי באורייתא\u0004 \u0005[היו לומדים תורה]\u0006 יחד, \u0003דחיקא להו מילתא טובא\u0004 \u0005[נדחק להם הדבר מאוד]\u0006 שהיו עניים גדולים ונזקקים מאוד בפרנסתם, \u0003אמרי: ניקום וניזיל וניעבד עיסקא\u0004 \u0005[אמרו:\u0006 הבה \u0005נעמוד, נלך ונעשה\u0006 איזה שהוא \u0005עסק]\u0006 \u0003ונקיים בנפשין\u0004 \u0005[בעצמנו]\u0006 מה שנאמר: \u0003\"אפס כי לא יהיה בך אביון\"\u0004 (דברים טו, ד), ומוטב שלא ניעשה אנו אביונים גמורים. \u0003אזלו אותבי תותי גודא רעיעא\u0004 \u0005[הלכו ישבו תחת כותל רעוע],\u0006 \u0003הוו קא כרכי ריפתא\u0004 \u0005[\u0006ו\u0005היו אוכלים פת],\u0006 \u0003אתו תרי\u0004 \u0005[באו שני]\u0006 \u0003מלאכי השרת\u0004","\u0003שמעיה\u0004 \u0005[שמע]\u0006 \u0003ר' יוחנן\u0004 ש\u0003אמר חד לחבריה\u0004 \u0005[אחד לחבירו]:\u0006 \u0003נישדי עלייהו האי גודא ונקטלינהו\u0004 \u0005[\u0006הבה \u0005נשליך עליהם כותל זה ונהרגם]\u0006 לפי \u0003שמניחין חיי עולם הבא ועוסקין בחיי שעה! אמר ליה\u0004 \u0005[ליה]\u0006 \u0003אידך\u0004 \u0005[\u0006המלאך \u0005האחר]:\u0006 \u0003שבקינהו\u0004 \u0005[הנח להם],\u0006 משום \u0003דאיכא בהו חד דקיימא ליה שעתא\u0004 \u0005[שיש ביניהם אחד שהשעה עומדת לו]\u0006 ויבוא להצלחה רבה. \u0003ר' יוחנן שמע\u0004 כל זה \u0003אילפא לא שמע. אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן לאילפא:\u0004 האם \u0003שמע מר מידי\u0004 \u0005[אדוני דבר]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא. אמר\u0004 ר' יוחנן בלבו \u0003מדשמעי אנא\u0004 \u0005[מכיון שאני שמעתי]\u0006 \u0003ואילפא לא שמע, שמע מינה לדידי קיימא לי שעתא\u0004 \u0005[מכאן שלי עומדת השעה].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן\u0004 לאילפא: \u0003איהדר\u0004 \u0005[אחזור]\u0006 אני הביתה, \u0003ואוקי בנפשאי\u0004 \u0005[ואקיים בעצמי]\u0006 מה שנאמר: \u0003\"כי לא יחדל אביון מקרב הארץ\"\u0004 (דברים טו, יא). \u0003ר' יוחנן הדר\u0004 \u0005[חזר]\u0006 לבית המדרש, \u0003אילפא לא הדר\u0004 \u0005[חזר]\u0006 והלך למרחקים לעסקים, \u0003עד דאתא\u0004 \u0005[שבא]\u0006 \u0003אילפא\u0004 ממסעותיו \u0003מליך\u0004 \u0005[מלך],\u0006 כלומר, נעשה \u0003ר' יוחנן\u0004 התמנה לראש ישיבה, ומתוך כך גם השתנה מצבו הכלכלי לטובה.","\u0003אמרו לו\u0004 לאילפא: \u0003אי אתיב מר וגריס\u0004 \u0005[אם היה אדוני יושב ולומד]\u0006 ולא הולך לעסקים, \u0003לא הוה מליך מר\u0004 \u0005[היה מולך אדוני,\u0006 ר' יוחנן\u0005]\u0006 שלא היה נעשה ראש ישיבה. \u0003אזל תלא נפשיה באסקריא דספינתא\u0004 \u0005[הלך ותלה עצמו בתורן של ספינה]\u0006 \u0003אמר\u0004 בלשון זו: \u0003אי איכא דשאיל לי במתניתא\u0004 \u0005[אם יש\u0006 אדם \u0005שישאל אותי בברייתא\u0006 של\u0005]\u0006 \u0003ר' חייא ור' אושעיא ולא פשטינא לה ממתניתין\u0004 \u0005[אפתור לו\u0006 את הבעיה \u0005מ\u0006תוך \u0005משנתנו],\u0006 \u0003נפילנא מאסקריא דספינתא וטבענא\u0004 \u0005[נופל אני מתורן הספינה וטובע],\u0006 שרצה להראות שגדול כוחו בתורה גם עכשיו, ולא בשל הפסקת לימודו לא עלה לגדולה.","מסופר: \u0003אתא ההוא סבא\u0004 \u0005[בא זקן אחד]\u0006 \u0003תנא ליה\u0004 \u0005[\u0006ו\u0005שנה לו]\u0006 ברייתא זו: אדם העומד למות \u0003האומר\u0004 בצוואתו: \u0003תנו שקל לבני בשבת\u0004 (בכל שבוע), \u0003והן ראויין\u0004 לפי צורכיהם \u0003לתת להם סלע\u0004 (ארבעה דינרים) — \u0003נותנים להם סלע\u0004 ששקל שאמר לא היה אלא הערכתו, ולא התכוון דווקא לסכום זה. \u0003ואם אמר: אל תתנו להם אלא שקל — אין נותנין להם אלא שקל\u0004 ולא יותר.","\u0003אם אמר:\u0004 אם \u0003מתו\u0004 בניי \u0003ירשו אחרים תחתיהם\u0004 — הרי אז \u0003בין שאמר \"תנו\" ובין שאמר \"אל תתנו\"\u0004 שאפילו אמר שקל ולא אמר שקל בלבד — \u0003אין נותנין להם אלא שקל\u0004 ולא יותר, משום שאז ברור שהאב התכוון לתת לבניו רק קיצבה מסויימת בלבד ולא יותר מזה, שהרי רוצה להוריש יתרת הממון לאחרים, ושאל הזקן את אילפא מה המקור במשנה להלכה זו שבברייתא, \u0003אמר ליה\u0004 \u0005[לו]\u0006 אילפא: \u0003הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי],\u0006 כשיטת \u0003ר' מאיר היא,\u0004 ש\u0003אמר: מצוה לקיים דברי המת.\u0004 ודבר זה מפורש במשנה. ולפי שיטה זו מתפרשת הברייתא היטב, שאנו הולכים בכל מקרה אחרי כוונתו של הנפטר.","ומעשה אחר בבית רעוע: \u0003אמרו עליו על נחום איש גם זו שהיה סומא משתי עיניו, גדם משתי ידיו, קיטע משתי רגליו, וכל גופו מלא שחין, והיה מוטל בבית רעוע, ורגלי מטתו מונחין בספלין של מים כדי שלא יעלו עליו נמלים,\u0004 שכיון שהיה מוכה שחין וידיו ורגליו קטועות לא יכול היה לגרש את הנמלים מגופו. \u0003פעם אחת [היתה מטתו מונחת בבית רעוע],\u0004 ו\u0003בקשו תלמידיו לפנות\u0004 את \u0003מטתו, ואחר כך לפנות\u0004 משם \u0003את הכלים\u0004 שבבית. \u0003אמר להם: בניי,\u0004 מייעץ אני לכם \u0003פנו את הכלים, ואחר כך פנו את מטתי, שמובטח לכם שכל זמן שאני בבית — אין הבית נופל.\u0004 וכך עשו, \u0003פינו את הכלים ואחר כך פנו את מטתו, ונפל הבית\u0004 מיד.","\u0003אמרו לו תלמידיו: רבי, וכי מאחר שצדיק גמור אתה,\u0004 שהרי ראינו שכל זמן שאתה בבית אין הבית נופל, \u0003למה עלתה לך כך\u0004 ביסורים גדולים אלה? \u0003אמר להם: בניי, אני גרמתי\u0004 זאת \u0003לעצמי.\u0004 וכך היה המעשה: \u0003שפעם אחת הייתי מהלך בדרך לבית חמי, והיה עמי משוי\u0004 (משא) טעון על \u0003שלשה חמורים, אחד\u0004 היה טעון \u0003של מאכל, ואחד של משתה, ואחד של מיני מגדים\u0004 (ממתקים). \u0003בא עני אחד ועמד לי בדרך, ואמר לי: רבי, פרנסני. אמרתי לו: המתן עד שאפרוק מן החמור\u0004 וכשאפרוק מן החמור אתן לך. \u0003לא הספקתי לפרוק מן החמור עד שיצתה נשמתו\u0004 ברעב.","\u0003הלכתי ונפלתי על פניו, ואמרתי: עיני שלא חסו על עיניך — יסומו\u0004 (יתעוורו), \u0003ידיי שלא חסו על ידיך — יתגדמו, רגלי שלא חסו על רגליך — יתקטעו, ולא נתקררה\u0004 (שקטה) \u0003דעתי עד שאמרתי: כל גופי יהא מלא שחין\u0004 ונמצא שהוא התפלל על עצמו שיתמרק ביסורים אלה. \u0003אמרו לו\u0004 התלמידים: אף על פי כן, \u0003אוי לנו שראינוך בכך,\u0004 וביסורים אלה! \u0003אמר להם: אוי לי אם לא ראיתוני בכך,\u0004 ששמח אני ביסורים אלה שהם מכפרים על עווני.","ומסבירים: \u0003ואמאי קרו ליה\u0004 \u0005[ולמה קראו לו]\u0006 \u0003נחום איש גם זו — דכל מילתא דהוה סלקא ליה\u0004 \u0005[שכל דבר שהיה מגיע,\u0006 מזדמן \u0005לו]\u0006 \u0003אמר: גם זו לטובה,\u0004 לכן קראו לו \"איש גם זו\". ומספרים: \u0003זימנא חדא בעו לשדורי\u0004 \u0005[פעם אחת רצו לשלוח]\u0006 \u0003ישראל דורון\u0004 (מתנה) \u0003לבי\u0004 \u0005[לבית]\u0006 ה\u0003קיסר, אמרו: מאן ייזיל\u0004 \u0005[מי ילך];\u0006 \u0003ייזיל\u0004 \u0005[ילך]\u0006 \u0003נחום איש גם זו,\u0004 ש\u0003מלומד בניסין הוא. שדרו בידיה\u0004 \u0005[שלחו בידו]\u0006 \u0003מלא סיפטא\u0004 \u0005[תיבה]\u0006 \u0003אבנים טובות ומרגליות, אזל בת בההוא דירא\u0004 \u0005[הלך\u0006 ו\u0005לן בדירה אחת],\u0006 \u0003בליליא קמו הנך דיוראי ושקלינהו לספטיה ומלונהו עפרא\u0004 \u0005[בלילה קמו אותם הדיירים\u0006 שגרו שם \u0005לקחו את התיבה\u0006 הוציאו את כל המרגליות משם \u0005ומילאו אותה בעפר].\u0006","\u0003למחר כי חזנהו\u0004 \u0005[כאשר ראה זאת]\u0006 \u0003אמר: גם זו לטובה. כי מטא התם\u0004 \u0005[כאשר הגיע לשם]\u0006 לבית הקיסר \u0003שרינהו לסיפטא\u0004 \u0005[פתחו את התיבה]\u0006 \u0003חזנהו דמלו עפרא\u0004 \u0005[\u0006ו\u0005ראו אותה שמלאה עפר].\u0006 \u0003בעא מלכא למקטלינהו לכולהו\u0004 \u0005[רצה המלך להרוג את כולם]\u0006 את כל שליחי ישראל על שביזו אותו, והביאו לו עפר. \u0003אמר\u0004 המלך: \u0003קא מחייכו\u0004 \u0005[צוחקים]\u0006 \u0003בי יהודאי\u0004 \u0005[היהודים]!\u0006 \u0003אמר\u0004 נחום: \u0003גם זו לטובה. אתא\u0004 \u0005[בא]\u0006 \u0003אליהו\u0004 הנביא, \u0003אדמי ליה כחד מינייהו\u0004 \u0005[\u0006ו\u0005נדמה לו\u0006 למלך \u0005כאחד מהם]\u0006 מן השרים, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דלמא הא עפרא מעפרא\u0004 \u0005[שמא עפר זה\u0006 הוא \u0005מאותו עפר]\u0006 של \u0003אברהם אבוהון\u0004 \u0005[אביהם]\u0006 \u0003הוא, דכי הוה שרי עפרא הוו סייפיה\u0004 \u0005[שכאשר היה זורק עפר היה\u0006 נעשה \u0005חרבות]\u0006 וכשהיה זורק \u0003גילי\u0004 \u0005[קש]\u0006 \u0003הוו גירי\u0004 \u0005[היו\u0006 נעשים \u0005חיצים]\u0006 וכ\u0003דכתיב\u0004 \u0005[כפי שנאמר]\u0006 בנבואה שדרשוה חכמים באברהם אבינו: \u0003\"יתן כעפר חרבו כקש נדף קשתו\"\u0004 (ישעיהו מא, ב).","ומספרים: \u0003הויא חדא מדינתא\u0004 \u0005[היתה מדינה אחת]\u0006 ש\u0003לא מצו למיכבשה\u0004 \u0005[יכלו לכבוש אותה],\u0006 \u0003בדקו מיניה\u0004 \u0005[ממנו]\u0006 מן העפר הזה \u0003וכבשוה.\u0004 כיון שראו שעפר זה הוא אכן עפר של נס, \u0003עיילו לבי גנזיה\u0004 \u0005[נכנסו לבית האוצרות]\u0006 \u0003ומלוהו לסיפטיה\u0004 \u0005[ומלאו את תיבתו]\u0006 \u0003אבנים טובות ומרגליות ושדרוהו ביקרא רבה\u0004 \u0005[ושלחוהו בכבוד גדול].\u0006","\u0003כי אתו ביתו בההוא דיורא\u0004 \u0005[כאשר באו ללון\u0006 שוב \u0005באותו בית]\u0006 \u0003אמרו ליה\u0004 \u0005[לו]\u0006 הבריות: \u0003מאי אייתית בהדך דעבדי לך יקרא כולי האי\u0004 \u0005[מה הבאת בידך\u0006 אל המלך \u0005שעשו לך כבוד גדול כזה]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003מאי דשקלי מהכא אמטי להתם\u0004 \u0005[מה שלקחתי מכאן הבאתי לשם]\u0006 וכיון ששמעו את הסיפור סברו שהעפר שבביתם הוא עפר שגרם לנס זה. \u0003סתרו לדירייהו ואמטינהו לבי מלכא\u0004 \u0005[שברו את דירתם והביאוהו\u0006 (את העפר) \u0005לבית המלך],\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003האי עפרא דאייתי הכא\u0004 \u0005[עפר זה שבא לכאן] —\u0006 \u0003מדידן\u0004 \u0005[משלנו]\u0006 \u0003הוא. בדקוה\u0004 \u0005[בדקו אותו]\u0006 את העפר הזה במלחמה \u0003ולא אשכחוה\u0004 \u0005[מצאו בו]\u0006 כוח ניסי זה, שהרי אירע הנס בזכות נחום איש גם זו, \u0003וקטלינהו להנך דיוראי\u0004 \u0005[והרגו את הדיירים ההם].\u0006","שנינו במשנה: \u0003אי זו היא דבר\u0004 — \u0003עיר המוציאה חמש מאות רגלי\u0004 שמתו בה שלושה מתים בשלושה ימים. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003עיר המוציאה חמש מאות ואלף רגלי\u0004 (שיש בה אלף וחמש מאות איש), \u0003כגון כפר עכו, ויצאו הימנה תשעה מתים בשלשה ימים זה אחר זה — הרי זה דבר.\u0004","מתו כל התשעה \u0003ביום אחד\u0004 ולא מתו אנשים בימים האחרים \u0003או\u0004 מתו תשעה \u0003בארבעה ימים — אין זה דבר\u0004 אלא מקרה הוא שאירע שמתו כמה אנשים יחד. \u0003ועיר המוציאה חמש מאות רגלי, כגון כפר עמיקו, ויצאו ממנה שלשה מתים בשלשה ימים זה אחר זה — הרי זה דבר.\u0004"],["\u0003ביום אחד או בארבעה ימים — אין זה דבר.\u0004","ובביאור לתמיהה מדוע מותם של רבים ביום אחד אינו סימן לדבר, מסופר, שהעיירה \u0003דרוקרת עיר המוציאה חמש מאות רגלי הוה\u0004 \u0005[היתה]\u0006 \u0003ויצאו ממנה שלשה מתים ביום אחד, גזר רב נחמן בר רב חסדא תעניתא\u0004 \u0005[תענית]\u0006 משום דבר. \u0003אמר רב נחמן בר יצחק: כמאן\u0004 \u0005[כמי]\u0006 סבור אתה — \u0003כ\u0004דעת \u0003ר' מאיר\u0004 במחלוקת לגבי שור המועד (שאם נגח השור שלושה ימים בזה אחר זה — הוא נעשה מועד), ש\u0003אמר\u0004 שם ר' מאיר, שאם נגח שלוש פעמים ביום אחד — כל שכן שהוא מועד, וטעמו:","\u0003ריחק נגיחותיו\u0004 יום אחר יום — \u0003חייב\u0004 כמועד, אם \u0003קירב נגיחותיו\u0004 והיו כולן באותו יום \u0003לא כל שכן?!\u0004 אולם איך נוהג אתה — כדעת יחיד, וכשם ששיטה זו נדחתה במקומה, כך צריך שלא לקבלה לענין המגפה.","כיון ששמע זאת \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן בר רב חסדא לרב נחמן בר יצחק: ליקום מר ליתי לגבן\u0004 \u0005[יעמוד אדוני\u0006 ו\u0005יבוא אלינו],\u0006 שיהא ראש במקומנו, שהרי אנו רואים שאנו זקוקים לתורתו. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תנינא\u0004 \u0005[שנינו]\u0006 כבר בברייתא, \u0003ר' יוסי אומר: לא מקומו של אדם מכבדו, אלא\u0004 ה\u0003אדם מכבד את מקומו.\u0004 וראייה לדבר: \u0003שכן מצינו בהר סיני, שכל זמן שהשכינה\u0004 היתה \u0003שרויה עליו, אמרה תורה: \"גם הצאן והבקר אל ירעו אל מול ההר ההוא\"\u0004 (שמות לד, ג), \u0003נסתלקה שכינה ממנו — אמרה תורה: \"במשך היבל המה יעלו בהר\"\u0004 (שמות יט, יג), משמע שאין הקדושה תלויה במקום אלא בהשראת השכינה בו,","\u0003וכן מצינו באהל מועד שבמדבר, שכל זמן שהוא נטוי\u0004 ועומד \u0003אמרה תורה: \"וישלחו מן המחנה כל צרוע\u0004 וכל זב\u0003\"\u0004 (במדבר ה, ב), \u0003הוגללו הפרוכת\u0004 בזמן שנסע המחנה — \u0003הותרו הזבין והמצורעים ליכנס שם,\u0004 למקום שעמד בו קודם המשכן, משמע: לא המקום מקודש אלא השכינה שבו. ואם כן, אין לו מה ללכת למקום אחר כדי לנחול שם כבוד!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אי הכי ניקום אנא לגבי מר\u0004 \u0005[אם כך אבוא אני אל אדוני]\u0006 ללמוד תורה ממנו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן בר יצחק: אם כן \u0003מוטב יבא מנה בן פרס\u0004 (חצי מנה), כלומר, אף שאני תלמיד חכם וכמנה שלם אני, מכל מקום מאחר ואני בנו של אדם פשוט שהוא נחשב כפרס, על כן ראוי שאבוא \u0003אצל מנה בן מנה\u0004 כמוך, שאתה אדם גדול בנו של אדם גדול, רב חסדא, \u0003ואל יבא מנה בן מנה אצל מנה בן פרס.\u0004","ועוד לענין מיתת דבר, מסופר: \u0003בסורא הוות דברתא\u0004 \u0005[היה דבר],\u0006 ואולם \u0003בשיבבותיה\u0004 \u0005[בשכנותו]\u0006 של \u0003רב לא הוות דברתא\u0004 \u0005[היה דבר].\u0006 \u0003סברו\u0004 אנשים \u0003מיניה\u0004 \u0005[משום כך],\u0006 כי \u0003משום זכותיה\u0004 \u0005[זכותו]\u0006 של \u0003רב דנפיש\u0004 \u0005[ש\u0006היא \u0005מרובה]\u0006 לא היה שום דבר בסביבתו. \u0003איתחזי להו בחילמא\u0004 \u0005[נראה להם בחלום]\u0006 בענין זה: \u0003רב דנפישא זכותיה טובא\u0004 \u0005[שמרובה זכותו יותר]\u0006 \u0003הא מילתא זוטרא ליה\u0004 \u0005[דבר זה קטן]\u0006 הוא \u0003ל\u0004גבי זכותו של \u0003רב. אלא\u0004 לא היה שם דבר בגלל זכות אחרת, \u0003משום ההוא גברא\u0004 \u0005[אדם אחד]\u0006 \u0003דשייל מרא וזבילא\u0004 שהיה נוהג גמילות חסד, \u0005[שהיה משאיל מעדר ואת]\u0006 \u0003לקבורה.\u0004","וכיוצא בזה מסופר: \u0003בדרוקרת הוות דליקתא\u0004 \u0005[היתה שריפה],\u0006 \u0003ובשיבבותיה\u0004 \u0005[ובשכנותו]\u0006 של \u0003רב הונא לא הוות דליקתא\u0004 \u0005[היתה שריפה].\u0006 \u0003סבור מינה בזכותא\u0004 \u0005[סברו מכאן\u0006 כי דבר זה הוא \u0005בזכותו]\u0006 של \u0003רב הונא דנפיש\u0004 \u0005[ש\u0006היא \u0005מרובה].\u0006 \u0003איתחזי להו בחילמא\u0004 \u0005[נראה להם בחלום]:\u0006 \u0003האי זוטרא ליה\u0004 \u0005[זו קטנה\u0006 היא \u0005לו]\u0006 \u0003לרב הונא, אלא משום ההיא איתתא דמחממת תנורא ומשיילי לשיבבותיה\u0004 \u0005[אשה אחת שמחממת את התנור ומשאילה לשכנותיה]\u0006 להשתמש בו.","\u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003לרב יהודה: אתו קמצי\u0004 \u0005[באו ארבה]\u0006 למדינה. \u0003גזר\u0004 על כך \u0003תעניתא\u0004 \u0005[תענית].\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003לא קא מפסדן\u0004 \u0005[אין הם מפסידים\u0006 מזיקים\u0005],\u0006 שאינם אוכלים הרבה. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003זוודא אייתו בהדייהו\u0004 \u0005[\u0006וכי \u0005צידה הביאו אתם],\u0006 שיש להם ממה להתפרנס? הלא בהכרח, גם אם אינם מזיקים עכשיו, יתחילו לאכול לאחר זמן!","\u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003לרב יהודה: איכא מותנא בחזירי\u0004 \u0005[יש דבר בחזירים].\u0006 \u0003גזר\u0004 על כך \u0003תעניתא\u0004 \u0005[תענית].\u0006 ושאלו: \u0003נימא קסבר\u0004 \u0005[האם לומר שסבר]\u0006 \u0003רב יהודה\u0004 כי \u0003מכה משולחת ממין אחד משולחת מכל המינין\u0004 ויש לחשוש שתעבור המחלה גם לאחרים? ומשיבים: \u0003לא,\u0004 במקרים אחרים לא היה חושש, אלא \u0003שאני חזירי דדמיין מעייהו לבני אינשי\u0004 \u0005[שונים\u0006 הם ה\u0005חזירים שמעיהם דומים ל\u0006מעי \u0005בני אדם]\u0006 ויש לחשוש שמחלה מדבקת שבחזירים תדבק גם בבני אדם.","\u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003לשמואל: איכא מותנא בי חוזאי\u0004 \u0005[יש דבר\u0006 במחוז \u0005בית חוזאי],\u0006 שהוא רחוק מאוד מבבל. \u0003גזר תעניתא\u0004 \u0005[תענית].\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003והא מרחק\u0004 \u0005[והרי מרוחק]\u0006 המקום מכאן! \u0003אמר: ליכא מעברא הכא דפסיק ליה\u0004 \u0005[אין כאן מיצר שיפסיק]\u0006 את המחלה, ויש לחשוש שכעבור זמן תגיע המגיפה גם לכאן.","\u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003לרב נחמן: איכא מותנא בארעא דישראל\u0004 \u0005[יש דבר בארץ ישראל],\u0006 \u0003גזר תעניתא\u0004 \u0005[תענית]\u0006 ו\u0003אמר: אם גבירה לוקה,\u0004 כלומר, אם ארץ ישראל שהיא כגבירה לכל ישראל לוקה, \u0003שפחה\u0004 (הגולה) \u0003לא כל שכן\u0004 שלוקה! על כן צריך להתענות.","ושואלים: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 משום שארץ ישראל לגבי שאר הגולה היא כ\u0003גבירה ושפחה, הא\u0004 \u0005[הרי]\u0006 בשני מקומות בגולה שהם כ\u0003שפחה ושפחה\u0004 — \u0003לא\u0004 יתענו. \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003לשמואל: איכא מותנא בי חוזאי\u0004 \u0005[יש דבר בבית חוזאי],\u0006 ו\u0003גזר תעניתא\u0004 \u0005[תענית]\u0006 במקומו, אף על פי שאין כל מעלה לבית חוזאי על מקומו כמשל הגבירה והשפחה! ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 \u0003כיון דאיכא שיירתא דלווי ואתיא בהדיה\u0004 \u0005[שיש שיירות\u0006 תכופות הבאות מבית חוזאי לבבל, המחלה \u0005נלווית ובאה איתה\u0006 עם השיירה\u0005].\u0006","אגב הסיפור על זכותם של אנשים פשוטים, מסופר: ל\u0003אבא אומנא\u0004 \u0005[האומן],\u0006 מקיז הדם, \u0003הוה אתי ליה שלמא ממתיבתא דרקיעא כל יומא\u0004 \u0005[היה בא לו שלום מישיבה של מעלה כל יום]\u0006 \u0003ולאביי כל מעלי יומא דשבתא\u0004 \u0005[ערב שבת],\u0006 \u0003לרבא כל מעלי יומא דכיפורי\u0004 \u0005[ערב יום הכיפורים].\u0006 \u0003הוה קא חלשא דעתיה\u0004 \u0005[נחלשה דעתו,\u0006 נעלב\u0005]\u0006 \u0003אביי משום\u0004 זכייתו של \u0003אבא אומנא,\u0004 שאבא אומנא זוכה לכבוד כזה משמים, שהוא אינו זוכה לו. \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003לא מצית למיעבד כעובדיה\u0004 \u0005[אין אתה יכול לעשות כמעשיו]\u0006 ולכן אף אינך זוכה לכבוד לו הוא זוכה.","ושואלים: \u0003ומאי הוו עובדיה\u0004 \u0005[ומה היו מעשיו]\u0006 הגדולים של \u0003אבא אומנא\u0004 — \u0003דכי הוה עביד מילתא\u0004 \u0005[שכאשר היה עושה דבר,\u0006 הקזה\u0005]\u0006 \u0003הוה מחית גברי\u0004 \u0005[היה מכניס גברים]\u0006 \u0003לחוד ונשי\u0004 \u0005[ונשים]\u0006 \u0003לחוד\u0004 משום צניעות, \u0003ואית ליה לבושא דאית ביה קרנא דהוות בזיעא כי כוסילתא\u0004 \u0005[והיה לו לבוש שהיה בו חתך כמקום הכנסת קרן הקזה].\u0006 \u0003כי הוות אתיא ליה איתתא, הוה\u0004 \u0005[כאשר היתה באה אליו אשה, היה]\u0006 \u0003מלביש לה\u0004 בגד זה \u0003כי היכי דלא ניסתכל\u0004 \u0005[כדי שלא יסתכל]\u0006 \u0003בה, ואית ליה דוכתא דצניעא דשדי ביה פשיטי דשקיל\u0004 \u0005[ויש לו\u0006 במקום עבודתו \u0005מקום צנוע\u0006 שאין אנשים רואים \u0005שבו משליכים,\u0006 מניחים \u0005את הכסף שהוא נוטל]\u0006 בשכר עבודתו, \u0003דאית ליה\u0004 \u0005[\u0006מי \u0005שיש לו]\u0006 כסף לשלם — \u0003שדי ביה\u0004 \u0005[זורק בו],\u0006 ומי \u0003דלית ליה\u0004 \u0005[שאין לו]\u0006 \u0003לא מיכסיף\u0004 \u0005[אינו מתבייש],\u0006 שאין רואים אם שילם עבור הטיפול או לא.","\u0003כי הוה אתרמי ליה צורבא מרבנן\u0004 \u0005[כאשר היה מזדמן לו תלמיד חכם]\u0006 להקיז לו, \u0003אגרא מיניה\u0004 \u0005[שכר ממנו]\u0006 \u0003לא שקיל\u0004 \u0005[\u0006היה \u0005נוטל]\u0006 כלל, \u0003ובתר דקאי\u0004 \u0005[ולאחר שהיה קם]\u0006 מההקזה, \u0003יהיב ליה פשיטי\u0004 \u0005[\u0006היה \u0005נותן לו מטבעות]\u0006 \u0003ואמר ליה\u0004 \u0005[ו\u0006היה \u0005אומר לו]:\u0006 \u0003זיל בריא נפשך\u0004 \u0005[לך הברא את עצמך]\u0006 בכסף זה, שהרי צריך לאכול מאכלים מבריאים אחר ההקזה. \u0003יומא חד שדר\u0004 \u0005[יום אחד שלח]\u0006 \u0003אביי זוגא דרבנן למיבדקיה\u0004 \u0005[זוג חכמים לבדוק אותו]\u0006 עד כמה מגיעה צדקותו. \u0003אותבינהו ואכלינהו ואשקינהו ומך להו ביסתרקי בלילא\u0004 \u0005[הושיבם\u0006 אבא אומנא \u0005והאכילם והישקם ושטח להם שטיחים בלילה\u0006 לישון עליהם\u0005].\u0006"],["\u0003לצפרא כרכינהו ושקלינהו\u0004 \u0005[בבוקר כרכו\u0006 החכמים את המצעות הללו \u0005ונטלו אותם\u0006 איתם\u0005]\u0006 \u0003וקמו ונפקו להו לשוקא\u0004 \u0005[ועמדו ויצאו להם לשוק]\u0006 \u0003ואשכחינהו\u0004 \u0005[ומצא אותם]\u0006 אבא אומנא, \u0003אמרו ליה\u0004 \u0005[לו]\u0006 אותם החכמים: \u0003לשיימיה מר היכי שוו\u0004 \u0005[שיעריך אדוני כמה שווים]\u0006 מצעות אלה? \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003הכי והכי\u0004 \u0005[כך וכך]\u0006 הם שווים. \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003ודלמא שוו טפי\u0004 \u0005[ושמא\u0006 הם \u0005שווים יותר]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003בהכי שקלינהו\u0004 \u0005[בכך קניתי אותם].\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003דידך ניהו\u0004 \u0005[שלך הם]\u0006 \u0003ושקלינהו מינך\u0004 \u0005[ואנו נטלנו אותם ממך].\u0006","לאחר שסיפרו לו את הענין \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003במטותא מינך במאי חשדתינן\u0004 \u0005[בבקשה ממך,\u0006 אמור \u0005במה חשדת אותנו],\u0006 כלומר, איך הסברת לעצמך את העובדה שאנחנו באים ונוטלים ממך מצעות, ואתה לא אמרת דבר? \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אמינא\u0004 \u0005[אמרתי]\u0006 בלבי: ודאי \u0003פדיון שבויים איקלע להו לרבנן\u0004 \u0005[הזדמן להם לחכמים]\u0006 והיו צריכים לכסף לצורך זה \u0003ואכסיפו למימר\u0004 \u0005[והתביישו לומר]\u0006 \u0003לי\u0004 ולבקש ממני כסף ולכן נטלו מבלי לבקש. \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003השתא נשקלינהו מר\u0004 \u0005[עכשיו,\u0006 שנתברר הענין \u0005שיקח אותם אדוני]!\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003מההוא שעתא אסחתינהו מדעתאי\u0004 \u0005[מאותה שעה הסחתי אותם מדעתי]\u0006 כדי לתת אותם \u0003לצדקה,\u0004 שבלבי כבר נדבתים לצורך זה, ואינני יכול ליטלם שוב.","\u0003הוה קא חלשא דעתיה\u0004 \u0005[נחלשה דעתו,\u0006 נעלב\u0005]\u0006 \u0003רבא משום\u0004 הכבוד לו זכה \u0003אביי,\u0004 שהיה בא לו שלום משמים בכל ערב שבת והוא לא זכה לכך אלא מערב יום הכיפורים אחד למשנהו, \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003מסתייך דקא מגנית אכולא כרכא\u0004 \u0005[דייך שאתה מגן\u0006 בזכותך \u0005על כל העיר]\u0006 שאתה גר בה.","ועוד לענין צדקותם של אנשים פשוטים, מסופר: \u0003ר' ברוקא חוזאה\u0004 \u0005[\u0006מהמקום \u0005חוזאי]\u0006 \u0003הוה שכיח בשוקא\u0004 \u0005[היה מצוי בשוק]\u0006 של המקום \u0003בי לפט, הוה שכיח\u0004 \u0005[היה מצוי]\u0006 \u0003אליהו\u0004 הנביא \u0003גביה\u0004 \u0005[אצלו],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 פעם אחת לאליהו: \u0003איכא בהאי שוקא בר עלמא דאתי\u0004 \u0005[\u0006האם \u0005יש בשוק זה\u0006 על כל האנשים שבו מישהו שהוא \u0005בן עולם הבא]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא. אדהכי והכי\u0004 \u0005[בינתיים]\u0006 \u0003חזא לההוא גברא דהוה סיים מסאני אוכמי ולא רמי חוטא דתכלתא בגלימיה\u0004 \u0005[ראה אדם אחד שהיה נעול נעלים שחורות\u0006 שלא כמנהג ישראל \u0005ולא היו לו חוטי תכלת,\u0006 ציציות, \u0005בבגדו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אליהו לר' ברוקא: \u0003האי בר עלמא דאתי\u0004 \u0005[\u0006אדם \u0005זה בן עולם הבא]\u0006 \u0003הוא.\u0004","\u0003רהט בתריה\u0004 \u0005[רץ\u0006 ר' ברוקא \u0005אחריו],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי עובדך\u0004 \u0005[מה מעשיך]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זיל האידנא\u0004 \u0005[לך עכשיו],\u0006 שאין לי זמן \u0003ותא\u0004 \u0005[ובוא]\u0006 \u0003למחר\u0004 ואז נשוחח. \u0003למחר אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי עובדך\u0004 \u0005[מה מעשיך]\u0006 הטובים? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זנדוקנא אנא\u0004 \u0005[שומר בית הסוהר אני]\u0006 \u0003ואסרנא גברי\u0004 \u0005[ואני אוסר גברים]\u0006 \u0003לחוד ונשי\u0004 \u0005[ונשים]\u0006 \u0003לחוד ורמינא פורייאי בין הני להני כי היכי דלא ליתו\u0004 \u0005[ואני מכניס את מיטתי בין אלה לאלה כדי שלא יבואו]\u0006 \u0003לידי איסורא\u0004 \u0005[איסור],\u0006 \u0003כי חזינא\u0004 \u0005[כאשר רואה אני]\u0006 \u0003בת ישראל דיהבי\u0004 \u0005[שנותנים]\u0006 \u0003עלה עינייהו\u0004 \u0005[עיניהם בה]\u0006 \u0003מסרנא נפשאי ומצילנא לה\u0004 \u0005[מוסר אני את נפשי ומציל אותה].\u0006 \u0003יומא חד הוות\u0004 \u0005[יום אחד היתה]\u0006 \u0003נערה מאורסה גבן\u0004 \u0005[אצלנו]\u0006 \u0003דיהבו\u0004 \u0005[שנתנו]\u0006 \u0003בה גוים עינייהו\u0004 \u0005[עיניהם],\u0006 \u0003שקלי דורדייא דחמרא ושדאי לה בשיפולה, ואמרי: דיסתנא\u0004 \u0005[לקחתי שמרי יין\u0006 שהם אדומים \u0005ושמתי לה בשיפולי\u0006 בגדה \u0005ואמרתי: נידה]\u0006 \u0003היא,\u0004 כדי שיניחו לה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' ברוקא: \u0003מאי טעמא לית לך\u0004 \u0005[מה טעם,\u0006 משום מה \u0005אין לך]\u0006 \u0003חוטי\u0004 ציצית \u0003ורמית מסאני אוכמי\u0004 \u0005[ונועל אתה נעלים שחורות]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003עיילנא ונפיקנא ביני\u0004 \u0005[יוצא ונכנס אני בין]\u0006 \u0003גוים\u0004 כאשר אני לבוש כך, \u0003כי היכי דלא לידעו דיהודאה אנא\u0004 \u0005[כדי שלא ידעו שיהודי אני],\u0006 \u0003כי הוו גזרי גזירתא מודענא להו לרבנן ובעו רחמי ומבטלי לגזירתייהו\u0004 \u0005[\u0006ו\u0005כאשר הם גוזרים גזירה, מודיע אני לחכמים ו\u0006הם \u0005מבקשים רחמים,\u0006 מתפללים \u0005ומבטלים את גזירתם].\u0006 ושאל אותו: \u0003ומאי טעמא כי אמינא לך אנא מאי עובדך, ואמרת לי זיל האידנא ותא\u0004 \u0005[ומה טעם\u0006 הדבר ש\u0005כאשר אמרתי לך אני מה מעשיך, ואמרת לי לך עכשיו ובוא]\u0006 \u0003למחר? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בההיא שעתא גזרי גזירתא ואמינא\u0004 \u0005[באותה שעה גזרו גזירה, ואמרתי]\u0006 בלבי: \u0003ברישא איזיל ואשמע להו לרבנן, דלבעי רחמי עלה דמילתא\u0004 \u0005[בתחילה אלך ואודיע להם לחכמים, שיבקשו רחמים על הדבר].\u0006","\u0003אדהכי והכי אתו הנך תרי אתי\u0004 \u0005[בינתיים באו שנים אחרים]\u0006 לשוק. \u0003אמר ליה\u0004 \u0005[לו]\u0006 אליהו הנביא לר' ברוקא: \u0003הנך נמי בני עלמא דאתי נינהו\u0004 \u0005[אלה גם כן בני עולם הבא הם].\u0006 \u0003אזל לגבייהו\u0004 \u0005[הלך אליהם],\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003מאי עובדייכו\u0004 \u0005[מה מעשיכם]?\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003אינשי בדוחי אנן, מבדחינן עציבי\u0004 \u0005[אנשים שמחים אנו ומשמחים אנו את העצובים]\u0006 \u0003אי נמי, כי חזינן בי תרי דאית להו תיגרא בהדייהו טרחינן ועבדינן להו שלמא\u0004 \u0005[או גם כן, כאשר אנחנו רואים שנים שיש ביניהם קטטה אנו טורחים ועושים ביניהם שלום],\u0006 ודברים אלה הם בין הדברים ששנינו אודותם, שהעושה אותם אוכל פירותיהם בעולם הזה והקרן קיימת לו לעולם הבא.","שנינו במשנה: \u0003על אלו מתריעין בכל מקום וכו'. תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 \u0003על אלו מתריעין בכל מקום: על השדפון\u0004 (מחלת התבואה), \u0003ועל הירקון\u0004 שבתבואה, \u0003ועל ארבה וחסיל\u0004 (מין אחר של חגבים הבא בלהקות גדולות) שהגיעו למקום, \u0003ועל חיה רעה\u0004 המסוכנת לבני אדם שפשטה ביישוב, \u0003ר' עקיבא אומר: על השדפון ועל הירקון\u0004 מתריעים גם אם נראו \u0003בכל שהוא,\u0004 כלומר, במספר מצומצם, וכן \u0003ארבה וחסיל, אפילו לא נראה בארץ ישראל אלא כנף אחד\u0004 פרט אחד מאותו מין — \u0003מתריעין עליהן,\u0004 משום שהוא סימן שעומד לבוא מחנה גדול של ארבה.","שנינו במשנה שמתריעים על אלה \u0003ועל חיה\u0004 רעה המסוכנת לבני אדם שפשטה ביישוב. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003חיה רעה שאמרו — בזמן שהיא משולחת\u0004 שיש התפרצות של חיות שלא כדרכן (ראה ויקרא כו, כב) — \u0003מתריעין עליה,\u0004 אבל אם \u0003אינה משולחת — אין מתריעין עליה.\u0004 ומסבירים: \u0003אי זו היא משולחת ואיזו היא שאינה משולחת?\u0004 אם \u0003נראית\u0004 החיה \u0003בעיר —\u0004 הרי היא \u0003משולחת,\u0004 נראתה \u0003בשדה\u0004 — דרכה הוא ולכן \u0003אינה משולחת.\u0004 נראתה \u0003ביום — משולחת, בלילה — אינה משולחת.\u0004","\u0003ראתה שני בני אדם ורצתה\u0004 (ורצה) \u0003אחריהן —\u0004 הרי זו \u0003משולחת, נחבאת מפניהן — אינה משולחת. טרפה שני בני אדם ואכלה אחד מהן — משולחת,\u0004 שהדבר מראה שהחיות טורפות לא מפני הרעב. ואם \u0003אכלה\u0004 את \u0003שניהן — אינה משולחת,\u0004 שעשתה זאת רק מפני הרעב ודרך הטבע היא. \u0003עלתה\u0004 חיה \u0003לגג ונטלה תינוק מעריסה — משולחת.\u0004 עד כאן לשון הברייתא.","ומבררים: \u0003הא גופה קשיא\u0004 \u0005[היא עצמה קשה]\u0006 מתוכה, \u0003אמרת\u0004 תחילה שאם \u0003נראתה בעיר — משולחת,\u0004 משמע: \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 \u0003ביום ולא שנא\u0004 \u0005[ואינו שונה]\u0006 \u0003בלילה,\u0004 שכל שהיא נראית בעיר הרי זו משולחת, \u0003והדר אמרת\u0004 \u0005[וחזרת\u0006 ו\u0005אמרת]:\u0006 \u0003ביום — משולחת, בלילה — אינה משולחת!\u0004","ומתרצים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הכי קאמר\u0004 \u0005[כך אמר,\u0006 כך יש להבין\u0005]:\u0006 \u0003נראתה בעיר ביום — משולחת, בעיר בלילה — אינה משולחת. אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003בשדה, אפילו ביום — אינה משולחת, בשדה בלילה — אינה משולחת.\u0004","ועוד שואלים: שנינו שם \u0003ראתה שני בני אדם ורצתה אחריהן — משולחת, הא\u0004 \u0005[הרי]\u0006 אפשר להסיק מכאן: אם היתה \u0003עומדת\u0004 אף שאינה בורחת — \u0003אינה משולחת, והדר אמרת\u0004 \u0005[וחזרת\u0006 ו\u0005אמרת]\u0006 \u0003נחבאת מפניהן אינה משולחת,\u0004 ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 אם היתה \u0003עומדת\u0004 ולא ברחה — \u0003משולחת!\u0004","ומתרצים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003כאן,\u0004 שאם אין החיה בורחת אלא עומדת במקומה אינה נחשבת כמשולחת, הרי זה כשהיא עומדת \u0003בשדה הסמוכה לאגם\u0004 (ביצה, מקום סוף וקנה), שסבורה היא שאם יבואו לצודה, תברח לאגם, \u0003כאן,\u0004 שאם היא עומדת ואינה בורחת סימן שמשולחת היא — \u0003בשדה שאינה סמוכה לאגם,\u0004 שאין לה להיכן לברוח, ועמידתה במקום סימן הוא לכך שהיא משולחת.","שנינו שאם \u0003טרפה שני בני אדם כאחד ואכלה אחד מהן — משולחת,\u0004 אכלה \u0003שניהם — אינה משולחת.\u0004 ותוהים: \u0003והא אמרת\u0004 \u0005[והרי אמרת]\u0006 \u0003אפילו רצתה\u0004 (רדפה) אחריהם ולא טרפה אותם הרי היא משולחת! \u0003אמר רב פפא: כי תני\u0004 \u0005[כאשר שנויה]\u0006 \u0003ההיא\u0004 שדווקא כשטרפה את שניהם הריהי נחשבת למשולחת, הרי זה \u0003באגמא\u0004 \u0005[באגם\u0006 עצמו\u0005]\u0006 שאם החיה טורפת בני אדם במקומה אין זה סימן של שילוח, אלא דרכה הוא.","\u0003גופא\u0004 \u0005[לגופו\u0006 של ענין\u0005]\u0006 נאמר שם: \u0003עלתה לגג ונטלה תינוק מעריסה — משולחת.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שכן הוא! \u0003אמר רב פפא:\u0004 מדובר שם \u0003בכוכי דציידי\u0004 \u0005[בסוכות של ציידים]\u0006 הסמוכות למקום החיות, שאפשר היה לחשוב שכיון שחיות רעות מצויות שם, אפילו עלתה לגג אינה משולחת. ולכן הוצרך לומר שעל כל פנים משולחת היא.","שנינו במשנה: מתריעים \u0003על החרב. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003חרב שאמרו, אינו צריך לומר חרב שאינו של שלום,\u0004 כלומר, שבא צבא אויב להלחם בישראל, \u0003אלא אפילו חרב של שלום\u0004 שצבא זר עובר במקום ללא כוונות עוינות, אלא משתמש בו כמעבר למקום אחר — מתריעים על בואה. \u0003שאין לך חרב של שלום יותר מפרעה נכה\u0004 שעבר דרך ארץ ישראל כדי להלחם עם נבוכדנאצר, \u0003ואף על פי כן נכשל בה\u0004 ונהרג על ידה \u0003המלך יאשיהו, שנאמר\u0004 לאחר שיאשיהו יצא למלחמה ולא נתן לפרעה נכה ולצבאו לעבור בארץ:"],["\u0003\"וישלח אליו מלאכים לאמר מה לי ולך מלך יהודה לא עליך אתה היום כי אל בית מלחמתי ואלהים אמר לבהלני חדל לך מאלהים אשר עמי ואל ישחיתך\"\u0004 (דברי הימים ב' לה, כא), שמלך מצרים אמר במפורש שאיננו מתכוון כלל להלחם עם יאשיהו.","\u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]:\u0006 \u0003\"אלהים אשר עמי\"? אמר רב יהודה אמר רב: זו עבודה זרה.\u0004 רצה לומר שפרעה אמר שהוא מוליך עמו פסלי עבודה זרה, והם מסייעים לו. \u0003אמר\u0004 יאשיהו: \u0003הואיל וקא בטח\u0004 \u0005[והוא בוטח]\u0006 \u0003בעבודה זרה — יכילנא ליה\u0004 \u0005[יכול אני לו]\u0006 לנצחו.","ונאמר באותו ענין עוד: \u0003\"וירו הירים למלך יאשיהו ויאמר המלך לעבדיו העבירוני כי החליתי מאד\"\u0004 (דברי הימים ב' לה, כג), \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"כי החליתי מאד\"? אמר רב יהודה אמר רב: מלמד שעשו כל גופו ככברה\u0004 מרוב החיצים שירו בו.","\u0003אמר ר' שמואל בר נחמני אמר ר' יונתן: מפני מה נענש יאשיהו — מפני שהיה לו לימלך\u0004 (להתייעץ) \u0003בירמיהו\u0004 הנביא אם לצאת למלחמה \u0003ולא נמלך. מאי\u0004 \u0005[מה]\u0006 \u0003דרש\u0004 יאשיהו כשהלך למלחמה — שנאמר: \u0003\"וחרב לא תעבר בארצכם\"\u0004 (ויקרא כו, ו),","\u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"חרב\"\u0004 שנאמרה בכתוב? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהכוונה ל\u0003חרב שאינה של שלום, והכתיב\u0004 \u0005[והרי נאמר]\u0006 כבר שם: \u0003\"ונתתי שלום בארץ\"\u0004 (ויקרא כו, ו)! \u0003אלא\u0004 ודאי הכוונה ש\u0003אפילו\u0004 חרב \u0003של שלום\u0004 לא תעבור, ורצה למנוע דבר זה. \u0003ו\u0004אולם \u0003הוא אינו יודע שאין דורו דומה יפה,\u0004 כלומר, שאין דורו זכאי לברכות הללו, ולכן לא יהא לו סיוע משמים להצליח.","בענין זה מסופר: \u0003כי הוה ניחא נפשיה חזא\u0004 \u0005[כאשר עמד למות ראה]\u0006 \u0003ירמיהו שפוותיה דקא מרחשן\u0004 \u0005[\u0006את \u0005שפתיו שהן מרחשות],\u0006 שהוא אומר משהו בשקט, \u0003אמר: שמא חס וחלילה מילתא דלא מהגנא\u0004 \u0005[דבר שאינו מהוגן],\u0006 תלונה על דין שמים \u0003אמר אגב צעריה\u0004 \u0005[צערו].\u0006 \u0003גחין ושמעיה דקא\u0004 \u0005[התכופף ושמע אותו שהוא]\u0006 \u0003מצדיק עליה דינא אנפשיה\u0004 \u0005[את הדין על עצמו],\u0006 ש\u0003אמר\u0004 יאשיהו: \u0003\"צדיק הוא ה' כי פיהו מריתי\"\u0004 (איכה א, יח). \u0003פתח עליה\u0004 \u0005[עליו]\u0006 ירמיהו \u0003ההיא שעתא\u0004 \u0005[באותה שעה]\u0006 בהספד: \u0003\"רוח אפינו משיח ה'\u0004 נלכד בשחיתותם\u0003\"\u0004 (איכה ד, כ).","שנינו במשנה: \u0003מעשה וירדו זקנים מירושלים לעריהם\u0004 וגזרו תענית על שנראה כמלוא פי תנור שידפון. \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 לחכמים\u0005]:\u0006 האם הכוונה היא \u0003כמלא תנור תבואה\u0004 בשיעור שימלא תנור שלם, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כמלא תנור פת\u0004 שמדביקים רק בדפנות התנור, ונמצא השיעור קטן בהרבה.","ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003כמלא פי תנור,\u0004 משמע לא כשיעור הממלא את התנור, אלא כלחם שעל פיו. \u0003ועדיין תיבעי להו\u0004 \u0005[נשאלת להם]:\u0006 האם מדובר \u0003ככיסויא דתנורא\u0004 \u0005[ככיסויו של תנור],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כי דרא דריפתא דהדר ליה לפומא דתנורא\u0004 \u0005[כמו שורת הלחם\u0006 הסובבת את \u0005פי התנור]?\u0006 לשאלה זו לא נמצאה תשובה, ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","שנינו במשנה: \u0003ועוד גזרו תענית על שאכלו זאבים\u0004 שני תינוקות. \u0003אמר עולא משום ר' שמעון בן יהוצדק: מעשה ובלעו זאבים שני תינוקות והקיאום\u0004 כלומר פלטו אותם מתוכם אחר העיכול \u0003דרך בית הרעי\u0004 שלהם. \u0003ובא מעשה לפני חכמים\u0004 מה דין הגוויות לענין טומאה, \u0003וטיהרו את הבשר\u0004 שהבשר כבר נתעכל בגוף הזאבים, \u0003וטמאו את העצמות,\u0004 כיון שאינן מתעכלות, ונראה שמדובר באותו מעשה.","שנינו במשנה, \u0003על אלו מתריעין בשבת:\u0004 על עיר שהקיפוה גוים או נהר וכן על ספינה המיטרפת בים. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003עיר שהקיפוה גוים, או נהר\u0004 גואה ועומד לשטפם, \u0003ואחד ספינה המיטרפת\u0004 (עומדת לטבוע) \u0003בים, ואחד יחיד שנרדף מפני גוים או מפני לסטין\u0004 (שודדים) \u0003ומפני רוח רעה\u0004 הגורמת לו טירוף העשוי להביאו בסופו של דבר לכך שיוזק או ימות, \u0003על כולן יחיד רשאי לסגף את עצמו בתענית\u0004 כדי לבטל את רוע הגזירה.","\u0003ר' יוסי אומר: אין היחיד רשאי לסגף את עצמו בתענית, שמא\u0004 מחמת חולשה לא יוכל לעבוד ו\u0003יצטרך לבריות\u0004 שיפרנסוהו \u0003ואין הבריות מרחמות עליו. אמר רב יהודה אמר רב: מאי טעמא\u0004 \u0005[מה טעם]\u0006 דבריו של \u0003ר' יוסי\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויהי האדם לנפש חיה\"\u0004 (בראשית ב, ז) והוא דורשו: \u0003נשמה שנתתי בך החייה,\u0004 שחייב אדם לדאוג לחיי נשמתו בגוף.","שנינו במשנה, \u0003שמעון התימני\u0004 (מהעיר תמנה) \u0003אומר: אף על הדבר\u0004 מתריעים בשבת ולא הודו לו חכמים. \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: האם הכוונה היא ש\u0003לא הודו לו חכמים\u0004 שמתריעים על כך \u0003בשבת, אבל בחול הודו לו, או דלמא\u0004 \u0005[שמא]\u0006 \u0003לא הודו לו כלל\u0004 שעל צרה זו מתריעים?","ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003מתריעין על הדבר בשבת, ואין צריך לומר בחול. ר' חנן בן פיטום תלמידו של ר' עקיבא משום\u0004 (בשם) \u0003ר' עקיבא אומר: אין מתריעין על הדבר כל עיקר.\u0004 ודעה אחרונה זו היא דעת חכמים במשנתנו.","שנינו במשנה: \u0003על כל צרה שלא תבוא על הצבור\u0004 מתריעים, חוץ מרוב גשמים. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003על כל צרה שלא תבוא על הצבור מתריעין עליה, חוץ מרוב גשמים.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003אמר ר' יוחנן: לפי שאין מתפללים על רוב הטובה,\u0004 שכיון שגשמים ככלל טובה הם לעולם, אין ראוי להתריע על שבאה טובה מרובה מדי.","\u0003ואמר ר' יוחנן: מניין שאין מתפללין על רוב הטובה — שנאמר: \"הביאו את כל המעשר אל בית האוצר\u0004 ויהי טרף בביתי ובחנוני נא בזאת אמר ה' צבאות אם לא אפתח לכם את ארובות השמים והריקותי לכם ברכה עד בלי די\u0003\"\u0004 (מלאכי ג, י). ומסבירים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"עד בלי די\" — אמר רמי בר רב יוד: עד שיבלו שפתותיכם מלומר \"די\",\u0004 ומשמע שעל דבר של ברכה אין מתפללים שיפסק אף שהוא מרובה כל כך עד שהאנשים כבר אומרים \"די\".","\u0003אמר רמי בר רב יוד: ובגולה\u0004 (בבבל שהיא מקום נמוך), \u0003מתריעין עליה\u0004 על ריבוי גשמים, שכיון ששם עלול הדבר להביא לידי סכנה, ראוי להתריע עליו. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003שנה שגשמיה מרובין אנשי משמר\u0004 שבמקדש \u0003שולחים לאנשי מעמד\u0004 בכל מקומותיהם: \u0003תנו עיניכם\u0004 (שימו לבכם להתכוון בתפילה) \u0003באחיכם שבגולה\u0004 (שבבבל), \u0003שלא יהא בתיהם קבריהם,\u0004 שמתוך שהיא במקום נמוך, מציפים השטפונות את הבתים ועלולים דייריהם למות בטביעה.","\u0003שאלו את ר' אליעזר: עד היכן גשמים יורדין ויתפללו שלא ירדו? אמר להם\u0004 בלשון הפרזה: \u0003כדי שיעמוד אדם ב\u0004צוק הנקרא \u0003קרן אפל\u0004 שהוא מקום גבוה מאד \u0003וישכשך\u0004 (ינענע) \u0003רגליו במים,\u0004 שאם לא הגיעו המים עד לגובה כזה אין מתפללים על רוב הטובה. ושואלים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 שבה נאמר בלשון אחרת: \u0003\"\u0004ישכשך \u0003ידיו\"!\u0004 ומשיבים: אין זו סתירה, \u0003רגליו כידיו קאמינא\u0004 \u0005[אומרים אנו].\u0006 כלומר, שיכול לשכשך רגליו בשחיה הרי שיכול לשכשך גם את ידיו במים המגיעים ממש עד לקצה קרן אופל.","וכדי להסביר את שיעורם של הדברים, \u0003אמר רבה בר בר חנה: לדידי חזיא לי\u0004 \u0005[אני עצמי ראיתי]\u0006 את \u0003קרן אפל, דקם ההוא טייעא כי רכיב גמלא ונקיט רומחא בידיה מיתחזי איניבא\u0004 \u0005[שעמד ערבי אחד כאשר\u0006 הוא \u0005רוכב\u0006 על \u0005גמל ומחזיק רומח בידו ונראה\u0006 משם כ\u0005תולעת]\u0006 ללמדנו עד כמה גבוהה קרן אופל.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 נאמר: \u0003\"ונתתי גשמיכם בעתם\"\u0004 (ויקרא כו, ד), כוונתו \u0003לא שכורה,\u0004 כלומר, שלא רוותה הארץ יותר מדי מים \u0003ולא צמאה\u0004 פחות מדי, \u0003אלא בינונית. שכל זמן שהגשמים מרובין\u0004 מן המידה \u0003מטשטשין\u0004 (מוחקים, מועכים) \u0003את הארץ, ואינה מוציאה פירות. דבר אחר:\u0004"],["\u0003\"בעתם\" בלילי רביעיות\u0004 (אור ליום רביעי) \u0003ובלילי שבתות\u0004 שאין אנשים הולכים בהם ברחוב, אם מפני חשש המזיקים (ברביעיות. ראה פסחים קיב,ב) או בשל קדושת השבת, וגשמים היורדים בימים אלה אינם מפריעים לאיש.","\u0003שכן מצינו בימי שמעון בן שטח שירדו להם גשמים\u0004 תמיד \u0003בלילי רביעיות ובלילי שבתות\u0004 ובזמנם, \u0003עד שנעשו חטים\u0004 גדולות \u0003ככליות, ושעורים כגרעיני זיתים, ועדשים\u0004 גדולות \u0003כדינרי זהב, וצררו מהם דוגמא לדורות, להודיע כמה החטא גורם\u0004 שאין הדבר קורה בכל שנה, \u0003שנאמר: \"\u0004ה' אלהינו הנותן גשם יורה ומלקוש בעתו... \u0003עונותיכם הטו אלה וחטאתיכם מנעו הטוב מכם\"\u0004 (ירמיה ה, כד-כה).","\u0003וכן מצינו בימי הורדוס שהיו עוסקין בבנין בית המקדש, והיו יורדין גשמים בלילה, למחר נשבה הרוח ונתפזרו העבים וזרחה החמה, ויצאו העם למלאכתן, וידעו\u0004 העם \u0003שמלאכת שמים בידיהם,\u0004 שהגשמים יורדים רק בזמן שאינו מפריע למלאכה.","שנינו במשנה: \u0003מעשה ששלחו לחוני המעגל וכו'.\u0004 מעשה זה מסופר בהרחבה בברייתא, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003פעם אחת יצא רוב\u0004 חודש \u0003אדר ולא ירדו\u0004 עדיין \u0003גשמים, שלחו לחוני המעגל: התפלל וירדו גשמים! התפלל, ולא ירדו גשמים. עג עוגה\u0004 (מעגל) בעפר, \u0003ועמד בתוכה, כדרך שעשה חבקוק הנביא, שנאמר: \"על משמרתי אעמדה ואתיצבה על מצור\u0004 ואצפה לראות מה ידבר בי ומה אשיב על תוכחתי\u0003\"\u0004 (חבקוק ב, א).","\u0003אמר לפניו: רבונו של עולם! בניך שמו פניהם עלי, שאני כבן בית לפניך. נשבע אני בשמך הגדול שאיני זז מכאן עד שתרחם על בניך. התחילו גשמים מנטפין\u0004 טיפות קטנות. \u0003אמרו לו תלמידיו: רבי! ראינוך ולא נמות,\u0004 כלומר, ראינו אותך עושה גדולות, אבל אין הדבר מועיל לנו שלא נמות, \u0003כמדומין אנו שאין גשמים יורדים אלא להתיר שבועתך\u0004 שיירד גשם כל שהוא, אבל לא די הצורך.","\u0003אמר\u0004 חוני: \u0003לא כך שאלתי, אלא גשמי\u0004 ברכה, העשויים למלאות \u0003בורות שיחין\u0004 (בורות מאורכים) \u0003ומערות\u0004 (בורות מכוסים תיקרה). \u0003ירדו\u0004 גשמים \u0003בזעף, עד שכל טפה וטפה כמלא פי חבית. ושיערו חכמים שאין טפה פחותה\u0004 בשיעורה \u0003מלוג. אמרו לו תלמידיו: רבי, ראינוך ו\u0004עם כל זה עשה ש\u0003לא נמות,\u0004 שכן \u0003כמדומין אנו שאין גשמים יורדין אלא לאבד\u0004 בהם את \u0003העולם.\u0004","\u0003אמר לפניו: לא כך שאלתי, אלא גשמי רצון ברכה ונדבה. ירדו\u0004 גשמים \u0003כתיקנן,\u0004 אבל הוסיפו וירדו \u0003עד שעלו כל העם להר הבית\u0004 שהוא מקום גבוה, \u0003מפני הגשמים. אמרו לו: רבי, כשם שהתפללת שירדו — כך התפלל וילכו להם. אמר להם: כך מקובלני שאין מתפללין על רוב הטובה.\u0004","\u0003אף על פי כן, הביאו לי פר\u0004 ואקריבנו עולה לשם \u0003הודאה\u0004 ותוך כדי כך אתפלל. \u0003הביאו לו פר הודאה, סמך שתי ידיו עליו, ואמר לפניו: רבונו של עולם! עמך ישראל שהוצאת ממצרים אינן יכולין\u0004 לעמוד \u0003לא ברוב טובה ולא ברוב פורענות, כעסת עליהם — אינן יכולין לעמוד, השפעת עליהם טובה\u0004 מרובה — \u0003אינן יכולין לעמוד, יהי רצון מלפניך שיפסקו הגשמים, ויהא ריוח בעולם. מיד נשבה הרוח, ונתפזרו העבים, וזרחה החמה, ויצאו העם לשדה והביאו להם כמהין ופטריות\u0004 שצמחו עם הגשמים הללו.","\u0003שלח לו שמעון בן שטח: אלמלא\u0004 (אילו לא) \u0003חוני אתה\u0004 שאתה צדיק גמור, \u0003גוזרני\u0004 (גוזר הייתי) \u0003עליך נידוי\u0004 על שאתה מתפלל בלשון זה. \u0003שאילו\u0004 היו \u0003שנים\u0004 אלה \u0003כשני אליהו שמפתחות גשמים בידו של אליהו\u0004 ונשבע שלא ירדו גשמים, \u0003לא נמצא שם שמים מתחלל על ידך\u0004 שהפרת את דבריו של אליהו על ידי תפילתך וגם יתכן שתהיה שבועתך שבועת שווא, שלא תתקיים,","\u0003אבל מה אעשה לך, שאתה מתחטא\u0004 (מתפנק) \u0003לפני המקום, ועושה לך רצונך, כבן שמתחטא על אביו ועושה לו רצונו, ואומר לו: אבא, הוליכני לרחצני בחמין,\u0004 אחר כך אומר לו \u0003שטפני בצונן, תן לי אגוזים,\u0004 תן לי \u0003שקדים, אפרסקים ורמונים — ונותן לו. ועליך הכתוב אומר: \"ישמח אביך ואמך ותגל יולדתך\"\u0004 (משלי כג, כה).","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מה שלחו בני לשכת הגזית\u0004 (אנשי הסנהדרין הגדולה) \u0003לחוני המעגל\u0004 — עליך הכתוב אומר: \u0003\"ותגזר אמר ויקם לך ועל דרכיך נגה אור.\u0004 כי השפילו ותאמר גוה ושח עינים יושיע. ימלט אי נקי ונמלט בבור כפיך\u0003\"\u0004 (איוב כב, כח-ל)","\u0003\"ותגזר אמר\" — אתה גזרת מלמטה, והקדוש ברוך הוא מקיים מאמרך מלמעלה. \"ועל דרכיך נגה אור\" — דור שהיה אפל הארת בתפלתך.\u0004","\u0003\"כי השפילו ותאמר גוה\" — דור שהיה שפל הגבהתו בתפלתך, \"ושח עינים יושע\" — דור ששח\u0004 (שהיה כפוף) \u0003בעונו — הושעתו בתפלתך, \"ימלט אי נקי\" — דור שלא היה נקי מלטתו בתפלתך, \"ונמלט בבר כפיך\" — מלטתו במעשה ידיך הברורין\u0004 (הנקיים).","כיון שהזכרנו מעשה זה בחוני המעגל, מספרים עליו דבר אחר: \u0003אמר ר' יוחנן, כל ימיו של אותו צדיק\u0004 חוני, \u0003היה מצטער על\u0004 הבנתו של \u0003מקרא זה,\u0004 שנאמר: \u0003\"שיר המעלות בשוב ה' את שיבת ציון היינו כחלמים\"\u0004 (תהלים קכו, א), \u0003אמר: מי איכא דניים שבעין שנין בחלמא\u0004 \u0005[האם יש מי שישן שבעים שנים בחלום]\u0006 ואיך אפשר לדמות את גלות בבל שהיתה שבעים שנה, לחלום?","\u0003יומא חד הוה אזל באורחא, חזייה לההוא גברא דהוה נטע חרובא\u0004 \u0005[יום אחד הלך בדרך, ראה אדם אחד שנוטע\u0006 עץ \u0005חרוב],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003האי, עד כמה שנין טעין\u0004 \u0005[\u0006עץ \u0005זה, עד כמה שנים טוען\u0006 פירות\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003עד שבעין שנין\u0004 \u0005[שבעים שנה].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003פשיטא לך דחיית שבעין שנין\u0004 \u0005[\u0006האם \u0005פשוט לך שאתה חי שבעים שנה],\u0006 שאתה נוטע את העץ ודעתך ליהנות ממנו? \u0003אמר ליה האי גברא\u0004 \u0005[לו אותו אדם]:\u0006 \u0003עלמא בחרובא אשכחתיה, כי היכי דשתלי לי אבהתי, שתלי נמי לבראי\u0004 \u0005[עולם\u0006 מלא \u0005בחרובים מצאתי, כפי ששתלו לי אבותי, כך שותל אני גם כן לבני].\u0006","\u0003יתיב, קא כריך ריפתא, אתא ליה שינתא, נים\u0004 \u0005[ישב\u0006 חוני, \u0005אכל פיתו, באה לו שינה, וישן].\u0006 \u0003אהדרא ליה משוניתא, איכסי מעינא, ונים שבעין שנין\u0004 \u0005[הקיפה אותו שן סלע, נעלם מן העין, וישן שבעים שנה].\u0006 \u0003כי קם חזייה לההוא גברא דהוה קא מלקט מיניהו\u0004 \u0005[כאשר קם, ראה אדם אחד שמלקט מהם,\u0006 מן החרובים\u0005]\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003את הוא דשתלתיה\u0004 \u0005[אתה הוא ששתלת אותו]\u0006 את העץ הזה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בר בריה אנא\u0004 \u0005[בן בנו אני].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שמע מינה דניימי שבעין שנין\u0004 \u0005[נמצא מכאן שישנתי שבעים שנה].\u0006 \u0003חזא לחמריה דאתיילידא ליה רמכי רמכי\u0004 \u0005[וראה את חמורו שנולדו לה עדרים עדרים\u0006 של חמורים\u0005]\u0006 באותן שנים מרובות.","\u0003אזל לביתיה\u0004 \u0005[הלך לביתו]\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 לבני הבית: \u0003בריה\u0004 \u0005[בנו]\u0006 של \u0003חוני המעגל מי קיים\u0004 \u0005[האם\u0006 הוא \u0005חי]?\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003בריה ליתא, בר בריה איתא\u0004 \u0005[בנו איננו\u0006 עוד, \u0005בן בנו ישנו].\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אנא\u0004 \u0005[אני]\u0006 \u0003חוני המעגל. לא הימנוהו\u0004 \u0005[האמינו לו]\u0006 \u0003אזל\u0004 \u0005[הלך]\u0006 \u0003לבית המדרש, שמעינהו לרבנן דקאמרי\u0004 \u0005[שמע את החכמים שאומרים]:\u0006 \u0003נהירן שמעתתין כבשני\u0004 \u0005[מאירות\u0006 וברורות \u0005הלכותינו כבשנות]\u0006 \u0003חוני המעגל, דכי הוי עייל לבית מדרשא\u0004 \u0005[שכאשר היה נכנס לבית המדרש] —\u0006 \u0003כל קושיא דהוו להו לרבנן\u0004 \u0005[שהיתה להם לחכמים]\u0006 \u0003הוה מפרק להו\u0004 \u0005[היה פותר להם].\u0006 מששמע זאת \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אנא ניהו\u0004 \u0005[אני הוא]\u0006 \u0003ולא הימנוהו\u0004 \u0005[האמינו לו]\u0006 \u0003ולא עבדי ליה יקרא כדמבעי ליה\u0004 \u0005[עשו לו כבוד כראוי לו].\u0006 \u0003חלש דעתיה, בעי רחמי, ומית\u0004 \u0005[חלשה דעתו, ביקש רחמים ומת].\u0006 \u0003אמר רבא: היינו דאמרי אינשי\u0004 \u0005[זהו שאומרים אנשים\u0006 בפתגם מקובל\u0005]:\u0006 \u0003או חברותא\u0004 \u0005[חברה]\u0006 \u0003או מיתותא\u0004 \u0005[מיתה],\u0006 שאדם שאין לו כל חברה מוטב לו שימות.","ובקשר לסיפור זה מספרים גם על צאצאיו של חוני שהיו גדולים בצדקותם. מסופר: \u0003אבא חלקיה בר בריה\u0004 \u0005[בן בנו]\u0006 של \u0003חוני המעגל הוה\u0004 \u0005[היה],\u0006 \u0003וכי מצטריך עלמא למיטרא הוו משדרי רבנן לגביה, ובעי רחמי, ואתי מיטרא\u0004 \u0005[וכאשר היה צריך העולם לגשם היו שולחים חכמים אליו, והיה מבקש רחמים, ובא הגשם].\u0006 \u0003זימנא חדא איצטריך עלמא למיטרא\u0004 \u0005[פעם אחת הצטרך העולם לגשם],\u0006 \u0003שדור רבנן זוגא דרבנן לגביה למבעי רחמי דניתי מיטרא\u0004 \u0005[שלחו חכמים זוג חכמים אליו לבקש רחמים שיבא גשם],\u0006 \u0003אזול לביתיה ולא אשכחוהו\u0004 \u0005[הלכו לביתו ולא מצאוהו],\u0006 \u0003אזול בדברא ואשכחוהו דהוה קא רפיק\u0004 \u0005[הלכו בשדה ומצאוהו שהיה עודר],\u0006 \u0003יהבו ליה שלמא\u0004 \u0005[נתנו לו שלום]\u0006"],["\u0003ולא אסבר להו אפיה\u0004 \u0005[הסביר להם פנים],\u0006 בהשבת שלום. \u0003בפניא, כי הוה מנקט ציבי, דרא ציבי ומרא בחד כתפא, וגלימא בחד כתפא\u0004 \u0005[בערב, כאשר אסף עצים\u0006 להסקה, \u0005שם את העצים והמעדר על כתפו האחת, והגלימה על כתפו האחת].\u0006 \u0003כולה אורחא לא סיים מסאני\u0004 \u0005[כל הדרך לא נעל נעלים],\u0006 \u0003כי מטי למיא סיים מסאניה\u0004 \u0005[כאשר הגיע למים נעל נעלים],\u0006 \u0003כי מטא להיזמי והיגי דלינהו למניה\u0004 \u0005[כאשר הגיע ל\u0006מקום \u0005קוצים הרים את בגדיו].\u0006 \u0003כי מטא למתא, נפקא דביתהו לאפיה כי מיקשטא\u0004 \u0005[כאשר הגיע לעיר, יצאה אשתו לקראתו כשהיא מקושטת]\u0006 \u0003כי מטא לביתיה, עלת דביתהו ברישא, והדר עייל איהו, והדר עיילי רבנן\u0004 \u0005[כאשר הגיע לביתו, נכנסה אשתו בתחילה, ואחר כך נכנס הוא, ואחר כך נכנסו חכמים],\u0006 \u0003יתיב וכריך ריפתא\u0004 \u0005[ישב ובצע פת]\u0006 \u0003ולא אמר להו לרבנן\u0004 \u0005[להם לחכמים]:\u0006 \u0003תו כרוכו\u0004 \u0005[בואו ואכלו]\u0006 כפי שנהוג לומר מדרכי הנימוס. \u0003פלג ריפתא לינוקי\u0004 \u0005[חילק לחם לילדים],\u0006 \u0003לקשישא חדא ולזוטרא תרי\u0004 \u0005[לגדול\u0006 פרוסה \u0005אחת ולקטן שתיים],\u0006","\u0003אמר לה לדביתהו\u0004 \u0005[לאשתו]:\u0006 \u0003ידענא דרבנן משום מיטרא קא אתו\u0004 \u0005[יודע אני שהחכמים משום הגשם באו],\u0006 \u0003ניסק לאיגרא וניבעי רחמי\u0004 \u0005[נעלה לגג ונבקש רחמים],\u0006 \u0003אפשר דמרצי\u0004 \u0005[אולי יתרצה]\u0006 \u0003הקדוש ברוך הוא וייתי מיטרא ולא נחזיק טיבותא לנפשין\u0004 \u0005[ויביא מטר, ולא נחזיק טובה לנפשנו],\u0006 שלא ייראה שאנחנו שגרמנו לכך. \u0003סקו לאיגרא, קם איהו בהדא זויתא, ואיהי בחדא זויתא\u0004 \u0005[עלו לגג, עמד הוא בפינה זו והיא בפינה אחת,\u0006 אחרת\u0005],\u0006 \u0003קדים סלוק ענני מהך זויתא דדביתהו\u0004 \u0005[קדמו\u0006 ו\u0005עלו עננים מאותה\u0006 \u0005פינה ש\u0006עמדה בה \u0005אשתו].\u0006 \u0003כי נחית\u0004 \u0005[כאשר ירד]\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אמאי אתו רבנן\u0004 \u0005[מדוע באו חכמים]\u0006 אלי? \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003שדרי לן רבנן לגבי דמר למיבעי רחמי אמיטרא\u0004 \u0005[שלחו\u0006 אותנו \u0005חכמים אל אדוני לבקש רחמים על הגשם].\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003ברוך המקום שלא הצריך אתכם לאבא חלקיה\u0004 שהרי השמים כבר מעוננים ועומד לרדת הגשם.","\u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003ידעינן דמיטרא\u0004 \u0005[יודעים אנו שהגשם]\u0006 \u0003מחמת מר\u0004 \u0005[אדוני]\u0006 \u0003הוא דאתא\u0004 \u0005[שבא],\u0006 \u0003אלא לימא לן מר הני מילי דתמיהא לן\u0004 \u0005[שיאמר,\u0006 יסביר, \u0005לנו אדוני אותם הדברים ש\u0006היו \u0005תמוהים לנו]\u0006 שעשית במשך הזמן, \u0003מאי טעמא כי יהיבנא למר שלמא לא אסבר לן מר אפיה\u0004 \u0005[מה טעם כאשר נתנו לאדוני שלום לא הסביר לנו אדוני פניו]\u0006 ולא השיב לנו שלום? \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003שכיר יום הואי\u0004 \u0005[הייתי],\u0006 \u0003ואמינא\u0004 \u0005[ואמרתי]:\u0006 \u0003לא איפגר\u0004 \u0005[אתמהמה]\u0006 בשיחה ואבטל מעבודתי. ועוד שאלו: \u0003ומאי טעמא דרא מר ציבי אחד כתפיה וגלימא אחד כתפיה\u0004 \u0005[ומה טעם שם אדוני את העצים על כתפו האחת ו\u0006את \u0005הגלימה על כתפו האחת]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003טלית שאולה היתה\u0004 זאת, \u0003להכי — שאלי, ולהכי — לא שאלי\u0004 \u0005[לזו\u0006 ללבוש אותה \u0005שאלתי\u0006 אותה, \u0005ולזו\u0006 לשים עליה עצים \u0005לא שאלתיה].\u0006","ושאלוהו עוד: \u0003מאי טעמא כולה אורחא\u0004 \u0005[מה טעם כל הדרך]\u0006 \u0003לא סיים מר מסאניה\u0004 \u0005[נעל אדוני נעליו]\u0006 \u0003וכי מטי למיא סיים מסאניה\u0004 \u0005[וכאשר הגיע למים נעל נעלים]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003כולה אורחא חזינא, במיא לא קא חזינא\u0004 \u0005[כל הדרך רואה אני\u0006 ויכול להזהר מן המכשולים, \u0005במים אינני רואה]\u0006 ולכן נעלתי נעלים שלא אנזק שם. \u0003מאי טעמא כי מטא מר להיזמי והיגי דלינהו למניה\u0004 \u0005[מה טעם כאשר הגיע אדוני לקוצים הרים את בגדיו]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003זה\u0004 הבשר \u0003מעלה ארוכה\u0004 (מתרפא) אם נסרט בקוצים \u0003וזה\u0004 הבגד \u0003אינה מעלה ארוכה\u0004 אם ייקרע.","ושאלוהו עוד: \u0003מאי טעמא כי מטא מר למתא נפקא דביתהו דמר כי מיקשטא\u0004 \u0005[מה טעם כאשר הגיע אדוני לעיר יצאה אשתו של אדוני כשהיא מקושטת]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003כדי שלא אתן עיני באשה אחרת\u0004 בלכתי בעיר. \u0003מאי טעמא עיילא היא ברישא, והדר עייל מר אבתרה, והדר עיילינן אנן\u0004 \u0005[מה טעם נכנסה היא בתחילה, ואחר כך נכנס אדוני, ואחר כך נכנסנו אנחנו]?\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003משום דלא בדקיתו לי\u0004 \u0005[שאין אתם בדוקים לי\u0006 בעיני\u0005]\u0006 ולא רציתי שתתייחדו עם אשה.","ושאלוהו עוד: \u0003מאי טעמא כי כריך מר ריפתא לא אמר לן \"איתו כרוכו\"\u0004 \u0005[מה הטעם כאשר בצע אדוני פת לא אמר לנו \"בואו וביצעו\"]?\u0006 אמר להם: \u0003משום\u0004 ש\u0003לא נפישא ריפתא\u0004 \u0005[היתה הפת מרובה]\u0006 דייה גם לאורחים \u0003ואמינא\u0004 \u0005[ואמרתי]:\u0006 \u0003לא אחזיק בהו ברבנן טיבותא\u0004 \u0005[יחזיקו לי\u0006 החכמים \u0005טובה]\u0006 \u0003בחנם,\u0004 שאני מכבד אותם, ואין בליבי באמת לעשות זאת. עוד שאלוהו: \u0003מאי טעמא יהיב מר לינוקא קשישא חדא ריפתא ולזוטרא תרי\u0004 \u0005[מה טעם נתן אדוני לילד הגדול פרוסה אחת ולקטן שתיים]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003האי\u0004 \u0005[זה,\u0006 הגדול\u0005] —\u0006 \u0003קאי בביתא\u0004 \u0005[נמצא בבית]\u0006 ואם הוא רעב הוא אוכל, \u0003והאי\u0004 \u0005[וזה,\u0006 הקטן\u0005]\u0006 — \u0003יתיב בבי כנישתא\u0004 \u0005[יושב בבית הכנסת\u0006 ולומד\u0005]\u0006 ולכן הוא רעב יותר.","ושאלוהו עוד: \u0003ומאי טעמא קדים סלוק ענני מהך זויתא דהוות קיימא דביתהו דמר לעננא דידיה\u0004 \u0005[מה הטעם קדמו ועלו עננים מאותה זוית שהיתה עומדת אשתו של אדוני לענן שלו]?\u0006 אמר להם: \u0003משום דאיתתא שכיחא בביתא, ויהבא ריפתא לעניי, ומקרבא הנייתה\u0004 \u0005[שהאשה נמצאת בבית, ונותנת לחם לעניים, וקרובה הנאתה]\u0006 שהיא גורמת להם, ומידה כנגד מידה תפילתה נענית תחילה. \u0003ואנא יהיבנא זוזא ולא מקרבא הנייתיה\u0004 \u0005[ואני נותן\u0006 לעניים \u0005מעות ואין הנאה\u0006 זו \u0005קרובה],\u0006 שהרי העני אינו נהנה מיד, אלא עד שיקנה לחם במעות אלה. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 טעם אחר: לפי שהיא גדולה ממני בצדקותה, שכן \u0003הנהו ביריוני דהוו בשיבבותן\u0004 \u0005[אותם בריונים שהיו בשכנותנו],\u0006 \u0003אנא בעי רחמי דלימותו, והיא בעיא רחמי דליהדרו בתיובתא, ואהדרו\u0004 \u0005[אני ביקשתי רחמים שימותו, והיא ביקשה רחמים שיחזרו בתשובה, וחזרו].\u0006","ועוד מסופר: \u0003חנן הנחבא בר ברתיה\u0004 \u0005[בן בתו]\u0006 של \u0003חוני המעגל הוה\u0004 \u0005[היה],\u0006 \u0003כי מצטריך עלמא למיטרא\u0004 \u0005[כאשר היה העולם צריך לגשם],\u0006 \u0003הוו משדרי רבנן ינוקי דבי רב לגביה\u0004 \u0005[היו שולחים חכמים תינוקות של בית רבם אליו]\u0006 \u0003ונקטי ליה בשיפולי גלימיה\u0004 \u0005[ו\u0006היו \u0005תופסים אותו בשולי גלימתו],\u0006 \u0003ואמרו ליה\u0004 \u0005[לו]:\u0006 \u0003אבא, אבא, הב לן מיטרא\u0004 \u0005[תן לנו גשם]!\u0006 \u0003אמר לפני הקדוש ברוך הוא: רבונו של עולם! עשה בשביל אלו\u0004 התינוקות, \u0003שאין מכירין בין אבא דיהיב מיטרא\u0004 \u0005[שנותן גשם]\u0006 הקדוש ברוך הוא, \u0003לאבא\u0004 ש\u0003לא יהיב מיטרא\u0004 \u0005[נותן גשם].\u0006 \u0003ואמאי קרי ליה\u0004 \u0005[ומדוע קראו לו]\u0006 \u0003\"חנן הנחבא\" — מפני שהיה מחביא עצמו בבית הכסא,\u0004 כדי שלא יחלקו לו כבוד.","ועוד בענין צדיקים המתפללים על הגשמים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זריקא לרב ספרא: תא חזי מה בין תקיפי דארעא דישראל\u0004 \u0005[ארץ ישראל]\u0006 \u0003לחסידי בבל\u0004 וכמה גדולים אנשי ארץ ישראל. \u0003חסידי בבל רב הונא ורב חסדא, כי הוה מצטריך עלמא למיטרא אמרי\u0004 \u0005[כאשר היה העולם צריך לגשם, היו אומרים]:\u0006 \u0003ניכניף הדדי וניבעי רחמי\u0004 \u0005[נתאסף יחד ונבקש רחמים]\u0006 ו\u0003אפשר דמירצי\u0004 \u0005[שיתרצה]\u0006 \u0003הקדוש ברוך הוא דייתי מיטרא\u0004 \u0005[שיביא מטר]\u0006 ובכך הודיעו שהם הולכים לבקש על הגשם.","\u0003תקיפי דארעא דישראל\u0004 \u0005[ארץ ישראל]\u0006 \u0003כגון ר' יונה אבוה\u0004 \u0005[אביו]\u0006 של \u0003ר' מני, כי הוה מצטריך עלמא למיטרא\u0004 \u0005[כאשר היה העולם צריך לגשם],\u0006 \u0003הוה עייל לביתיה ואמר להו\u0004 \u0005[היה נכנס לביתו ואומר להם]:\u0006 \u0003הבו לי גואלקי, ואיזיל ואייתי לי בזוזא עיבורא\u0004 \u0005[תנו לי\u0006 את \u0005השק\u0006 שלי \u0005ואלך ואביא לי תבואה בזוז].\u0006 \u0003כי הוה נפיק לברא, אזיל וקאי בדוכתא עמיקתא\u0004 \u0005[כאשר היה יוצא לחוץ, היה הולך ועומד במקום עמוק],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ממעמקים קראתיך ה'\"\u0004 (תהלים קל, א), \u0003וקאי בדוכתא צניעא, ומכסי בשקא, ובעי רחמי, ואתי מיטרא\u0004 \u0005[והיה עומד במקום צנוע\u0006 נסתר, \u0005ומתכסה בשק ומבקש רחמים ובא הגשם].\u0006 \u0003כי הוה אתי לביתיה\u0004 \u0005[כאשר היה בא לביתו],\u0006 \u0003אמרי ליה\u0004 \u0005[היו אומרים לו]:\u0006 \u0003אייתי מר עיבורא\u0004 \u0005[האם הביא אדוני תבואה]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אמינא\u0004 \u0005[אמרתי\u0006 בלבי\u0005],\u0006 \u0003הואיל ואתא מיטרא\u0004 \u0005[ובא הגשם],\u0006 \u0003השתא רווח עלמא\u0004 \u0005[עכשיו רווח העולם]\u0006 ולא כדאי לקנותה עכשיו ביוקר. הרי שהיה מסתיר אפילו מבני ביתו שהוא הולך להתפלל על הגשם.","\u0003ותו\u0004 \u0005[ועוד]\u0006 מסופר על גדולתו, \u0003ר' מני בריה\u0004 \u0005[בנו]\u0006 \u0003הוו קא מצערי ליה דבי נשיאה\u0004 \u0005[היו מצערים אותו\u0006 בני \u0005בית הנשיא]\u0006 \u0003אישתטח על קברא דאבוה\u0004 \u0005[השתטח על קבר אביו],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אבא אבא! הני מצערו לי\u0004 \u0005[אלה מצערים אותי].\u0006 \u0003יומא חד הוו קא חלפי התם\u0004 \u0005[יום אחד עברו שם]\u0006 ליד הקבר, \u0003אינקוט כרעא דסוסוותייהו עד דקבילו עלייהו דלא קא מצערו ליה\u0004 \u0005[נתפסו רגלי סוסיהם עד שקיבלו עליהם שלא יצערו אותו].\u0006","\u0003ותו\u0004 \u0005[ועוד]\u0006 מסופר: \u0003ר' מני הוה שכיח קמיה\u0004 \u0005[היה מצוי לפני]\u0006 \u0003ר' יצחק בן אלישיב\u0004 שאף הוא היה בעל מופתים, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003עתירי דבי חמי קא מצערו לי\u0004 \u0005[העשירים של בית חמי מצערים אותי].\u0006 \u0003אמר\u0004 ר' יצחק: \u0003ליענו\u0004 \u0005[שייעשו עניים]\u0006 ולא יהיו תקיפים עוד, \u0003ואיענו\u0004 \u0005[ו\u0006אכן \u0005נעשו עניים].\u0006 לאחר זמן \u0003אמר\u0004 לרבו: \u0003קא דחקו לי\u0004 \u0005[הם דוחקים אותי],\u0006 משום שעכשיו הם נזקקים לעזרתי. \u0003אמר\u0004 ר' יצחק: \u0003ליעתרו\u0004 \u0005[שיתעשרו],\u0006 \u0003ואיעתרו\u0004 \u0005[ו\u0006אכן \u0005התעשרו].\u0006","\u0003אמר\u0004 ר' מני לרבו: \u0003לא מיקבלי\u0004 \u0005[מקובלים עלי]\u0006 \u0003עלי אינשי\u0004 \u0005[אנשי]\u0006 \u0003ביתי,\u0004 כלומר, אין אשתי מקובלת עלי, משום שאיננה יפה. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מה שמה?\u0004 אמר לו: \u0003חנה.\u0004 אמר: \u0003תתייפי חנה. ונתייפת\u0004 \u0005[ונתייפתה].\u0006 לאחר זמן \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' מני לרבי יצחק רבו: \u0003קא מגנדרא עלי\u0004 \u0005[היא מתגאה עלי]\u0006 משום שנעשתה יפה כל כך. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003תחזור חנה לשחרוריתה, ו\u0004אכן \u0003חזרה חנה לשחרוריתה.\u0004","ומסופר: \u0003הנהו תרי תלמידי דהוו קמיה\u0004 \u0005[אותם שני תלמידים שהיו יושבים לפני]\u0006 \u0003ר' יצחק בן אלישיב, אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003ניבעי מר רחמי עלן דניחכים טובא\u0004 \u0005[שיבקש אדוני רחמים עלינו שנחכים הרבה].\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003עמי היתה\u0004 פעם יכולת זאת שאתפלל ואיענה בתפילתי, \u0003ושלחתיה,\u0004 שקיבלתי על עצמי שלא להטריח בתפילה להטריח את בוראי בשינוי סדרי תבל (ר\"ג).","מסופר: \u0003ר' יוסי בר אבין הוה שכיח קמיה\u0004 \u0005[היה מצוי לפני]\u0006 \u0003ר' יוסי דמן יוקרת. שבקיה, ואתא לקמיה\u0004 \u0005[עזב אותו, ובא\u0006 ללמוד \u0005לפני]\u0006 \u0003רב אשי,\u0004 ורב אשי לא ידע מי הוא."],["\u0003יומא חד שמעיה\u0004 \u0005[יום אחד שמע אותו]\u0006 ר' יוסי בר אבין את רב אשי \u0003דקא גריס\u0004 \u0005[שהוא שונה],\u0006 \u0003אמר שמואל: השולה דג מן הים בשבת, כיון שיבש בו\u0004 בדג — שטח שגודלו \u0003כ\u0004מטבע של \u0003סלע — חייב\u0004 משום נטילת נשמה בשבת, שכן אין הדג יכול לחיות עוד, גם אם יחזירוהו למים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוסי בר אבין: \u0003ולימא מר\u0004 \u0005[ושיאמר אדוני]\u0006 ששיעור זה ליובש הוא דווקא \u0003בין סנפיריו\u0004 של הדג! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003ולא סבר לה מר דההיא\u0004 \u0005[האם אין אדוני סבור שאותה\u0006 הלכה\u0005]\u0006 \u0003ר' יוסי בן ר' אבין אמרה,\u0004 ומדוע לא אמרת בשמו? \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוסי לרב אשי: \u0003אנא ניהו\u0004 \u0005[אני הוא].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אשי: \u0003ולאו קמיה\u0004 \u0005[וכי לא לפני]\u0006 \u0003ר' יוסי דמן יוקרת הוה שכיח מר\u0004 \u0005[היה מצוי אדוני]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הין\u0004 \u0005[כן].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ומאי טעמא שבקיה מר ואתא הכא\u0004 \u0005[ומה טעם עזבו אדוני ובא לכאן]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003גברא\u0004 \u0005[אדם]\u0006 ש\u0003על בריה\u0004 \u0005[בנו]\u0006 \u0003ועל ברתיה\u0004 \u0005[בתו]\u0006 \u0003לא חס, עלי דידי היכי חייס\u0004 \u0005[עלי עצמי איך יחוס]?!\u0006 וחששתי מפני הקפדתו ועונשו ועזבתיו.","ומסבירים: מעשה \u0003בריה מאי היא\u0004 \u0005[בנו מה הוא]?\u0006 \u0003יומא חד הוו אגרי ליה אגירי בדברא, נגה להו ולא אייתי להו ריפתא\u0004 \u0005[יום אחד היו שכורים אצלו\u0006 פועלים \u0005שכירים בשדה, איחר\u0006 הזמן \u0005ולא הביא להם לחם],\u0006 \u0003אמרו ליה\u0004 \u0005[לו]\u0006 השכירים \u0003לבריה\u0004 \u0005[לבנו]\u0006 של ר' יוסי מן יוקרת: \u0003כפינן\u0004 \u0005[רעבים אנו]!\u0006 \u0003הוו יתבי תותי תאינתא\u0004 \u0005[היו יושבים תחת התאנה]\u0006 \u0003אמר: תאנה, תאנה! הוציאי פירותיך, ויאכלו פועלי אבא. אפיקו\u0004 \u0005[הוציאה]\u0006 התאנה פירות \u0003ואכלו.\u0004","\u0003אדהכי והכי אתא אבוה\u0004 \u0005[בין כך וכך בא אביו]\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003לא תינקטו בדעתייכו, דהאי דנגהנא, אמצוה טרחנא, ועד השתא הוא דסגאי\u0004 \u0005[אל תקפידו במחשבתכם\u0006 עלי, \u0005שזה שאחרתי,\u0006 משום ש\u0005במצוה טרחתי, ועד עכשיו הלכתי]\u0006 ולא יכולתי לבוא קודם לכן. \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003רחמנא לישבעך כי היכי דאשבען ברך\u0004 \u0005[הקדוש ברוך הוא ישביע אותך כפי שהשביענו בנך]\u0006 ואין אנו צריכים לאוכל. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003מהיכא\u0004 \u0005[מהיכן]\u0006 היה לו לתת? \u0003אמרו\u0004 לו: \u0003הכי והכי הוה\u0004 \u0005[כך וכך היה]\u0006 ה\u0003מעשה. אמר לו\u0004 לבנו: \u0003בני, אתה הטרחת את קונך להוציא תאנה פירותיה שלא בזמנה — יאסף\u0004 (ימות) גם בני \u0003שלא בזמנו,\u0004 וכך אכן אירע לו.","מעשה \u0003ברתיה מאי היא\u0004 \u0005[בתו מה הוא]?\u0006 \u0003הויא ליה ברתא\u0004 \u0005[היתה לו בת]\u0006 \u0003בעלת יופי, יומא חד חזיא לההוא גברא דהוה כריא בהוצא וקא חזי לה\u0004 \u0005[יום אחד ראה\u0006 ר' יוסי \u0005אדם אחד שהיה נוקב\u0006 נקב בגדר \u0005הקוצים\u0006 סביב ביתו \u0005ומביט בה].\u0006 \u0003אמר לו: מאי האי\u0004 \u0005[מה זה]?\u0006 \u0003אמר לו: רבי, אם ללוקחה\u0004 לאשה \u0003לא זכיתי — לראותה לא אזכה? אמר לה: בתי, קא מצערת להו לברייתא\u0004 \u0005[את מצערת את הבריות],\u0006 \u0003שובי לעפריך ואל יכשלו ביך\u0004 (בך) \u0003בני אדם.\u0004 אגב סיפורים אלה מספרים על מופתים אחרים שהיו בו.","\u0003הויא ליה ההוא חמרא\u0004 \u0005[היתה לו אתון אחת]\u0006 \u0003כדהוו אגרי לה כל יומא, לאורתא הוו משדרי לה אגרה אגבה, ואתיא לבי מרה\u0004 \u0005[כשהיו שוכרים אותה כל יום\u0006 לעבודה, \u0005בערב היו שולחים את שכרה על גבה והיתה באה לבית בעליה],\u0006 \u0003ואי טפו\u0004 \u0005[ואם היו מוסיפים]\u0006 \u0003לה או בצרי\u0004 \u0005[מורידים]\u0006 \u0003לה\u0004 מן השכר הראוי — \u0003לא אתיא\u0004 \u0005[היתה באה].\u0006 \u0003יומא חד אינשו זוגא דסנדלי עלה\u0004 \u0005[יום אחד שכחו זוג סנדלים עליה],\u0006 \u0003ולא אזלה\u0004 \u0005[הלכה]\u0006 \u0003עד דשקלונהו מינה, והדר אזלה\u0004 \u0005[שלקחו אותם ממנה, ואחר כך הלכה].\u0006","ועוד בענין ניסים שאירעו לצדיקים: \u0003אלעזר איש\u0004 הכפר \u0003בירתא כד הוו חזו ליה\u0004 \u0005[כאשר היו רואים אותו]\u0006 \u0003גבאי\u0004 ה\u0003צדקה הוו טשו מיניה\u0004 \u0005[היו מתחבאים ממנו]\u0006 ש\u0003כל מאי דהוה גביה\u0004 \u0005[מה שהיה איתו]\u0006 \u0003יהיב להו\u0004 \u0005[היה נותן להם],\u0006 ולא רצו שיתן כל רכושו. \u0003יומא חד הוה סליק לשוקא למיזבן נדוניא לברתיה\u0004 \u0005[יום אחד הלך לשוק לקנות נדוניה,\u0006 צרכי חתונה, \u0005לבתו]\u0006 \u0003חזיוהו\u0004 \u0005[ראוהו]\u0006 \u0003גבאי\u0004 ה\u0003צדקה, טשו מיניה\u0004 \u0005[ברחו ממנו].\u0006","\u0003אזל ורהט בתרייהו\u0004 \u0005[הלך ורץ אחריהם]\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אשבעתיכו במאי עסקיתו\u0004 \u0005[השבעתי אתכם,\u0006 שתאמרו לי \u0005במה,\u0006 באיזו מצוה \u0005אתם עוסקים]?\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003ביתום ויתומה\u0004 שאנו אוספים כסף לצורך נשואיהם. \u0003אמר להן: העבודה\u0004 (לשון שבועה בעבודת המקדש) \u0003שהן קודמין לבתי, שקל\u0004 \u0005[לקח]\u0006 את \u0003כל\u0004 מה \u0003דהוה בהדיה\u0004 \u0005[שהיה איתו]\u0006 \u0003ויהב להו\u0004 \u0005[ונתן להם].\u0006 \u0003פש ליה חד זוזא\u0004 \u0005[נשאר לו זוז אחד]\u0006 \u0003זבן ליה חיטי, ואסיק, שדייה באכלבא\u0004 \u0005[קנה לעצמו חיטים ועלה והשליכם באסם].\u0006","\u0003אתאי דביתהו\u0004 \u0005[באה אשתו]\u0006 \u0003אמרה לה לברתיה\u0004 \u0005[לבתו]:\u0006 \u0003מאי אייתי אבוך\u0004 \u0005[מה הביא אביך]?\u0006 \u0003אמרה לה: כל מה דאייתי, באכלבא שדיתיה\u0004 \u0005[כל מה שהיה לו, באסם זרק אותו].\u0006 \u0003אתיא למיפתח בבא דאכלבא, חזת אכלבא דמליא חיטי וקא נפקא בצינורא דדשא, ולא מיפתח בבא מחיטי\u0004 \u0005[באה לפתוח את דלת האסם, ראתה את האסם שהוא מלא חיטים והן יוצאות בסדק הדלת ואין הדלת נפתחת מ\u0006רוב ה\u0005חיטים],\u0006 שאירע לו נס והתמלא האסם כולו בחיטים. \u0003אזלא ברתיה לבי מדרשא\u0004 \u0005[הלכה בתו לבית המדרש],\u0006 \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003בא וראה מה עשה לך אוהבך\u0004 הקדוש ברוך הוא! \u0003אמר לה: העבודה\u0004 (לשון שבועה), \u0003הרי\u0004 החיטים הללו \u0003הן הקדש עליך\u0004 (לגביך) \u0003ואין לך בהן\u0004 חלק \u0003אלא כאחד מעניי ישראל,\u0004 שלא רצה ליהנות מן הנס.","ושוב חוזרים לספר בענין תעניות על הגשם. \u0003ר' יהודה נשיאה גזר תעניתא\u0004 \u0005[תענית],\u0006 \u0003בעי רחמי\u0004 \u0005[ביקש רחמים]\u0006 \u0003ולא אתא מיטרא\u0004 \u0005[בא גשם].\u0006 \u0003אמר\u0004 בצער: \u0003כמה איכא\u0004 \u0005[יש]\u0006 הבדל \u0003משמואל\u0004 הנביא \u0003הרמתי\u0004 שהתפלל וירד גשם אפילו בקיץ \u0003ליהודה בן גמליאל\u0004 (הוא ר' יהודה נשיאה)! \u0003אוי לו לדור שכן נתקע\u0004 במנהיגות שכזו, \u0003אוי לו למי שעלתה בימיו כך! חלש דעתיה ואתא מיטרא\u0004 \u0005[חלשה דעתו ובא הגשם].\u0006","אגב סיפור זה על הנשיא הגוזר תענית על הגשם, מספרים: \u0003דבי נשיאה גזר תעניתא\u0004 \u0005[תענית],\u0006 \u0003ולא אודעינהו\u0004 \u0005[הודיעו]\u0006 \u0003לר' יוחנן ולריש לקיש\u0004 מבעוד יום ורק \u0003לצפרא אודעינהו\u0004 \u0005[בבוקר הודיעו להם].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ריש לקיש לר' יוחנן:\u0004 כיצד ננהג? \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לא קבילנא עלן מאורתא\u0004 \u0005[קיבלנו עלינו\u0006 את התענית \u0005מן הערב]\u0006 ואין קבלת תענית אלא במנחה שלפני יום התענית! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנן בתרייהו גררינן\u0004 \u0005[אנחנו אחריהם\u0006 \u0005נגררים],\u0006 שהנשיא קובע עבור הכל, ואין אנו צריכים לקבוע תענית לעצמנו.","סיפור אחר בענין תענית על הגשם, סיפרו: \u0003דבי נשיאה\u0004 \u0005[בבית הנשיא]\u0006 \u0003גזר תעניתא\u0004 \u0005[גזרו תענית]\u0006 \u0003ולא אתא מיטרא\u0004 \u0005[ולא בא גשם].\u0006 \u0003תנא להו\u0004 \u0005[שנה להם]\u0006 \u0003אושעיא\u0004 שהיה מכונה \u0003זעירא דמן חברייא\u0004 \u0005[הקטן בחבורת\u0006 החכמים\u0005],\u0006 נאמר: \u0003\"והיה אם מעיני העדה נעשתה לשגגה\"\u0004 (במדבר טו, כד), פסוק זה מלמד, שקוראים למנהיגים \"עיני העדה\".","ובהתאם לכך, \u0003משל לכלה שהיא בבית אביה\u0004 ואין מכירים אותה, \u0003כל זמן שעיניה יפות — אין כל גופה צריכה בדיקה,\u0004 שודאי יפה ושלימה היא, אבל אם \u0003עיניה טרוטות\u0004 (פגומות ונוזלות) — \u0003כל גופה צריכה בדיקה.\u0004 וכך הוא בדור כולו גם כן, שאם ראשי הדור פגומים — סימן הם לכל העם כולו. ורמז לכך, שבשל רישעותם של בני בית הנשיא, אין בוחנים מן השמים כלל את מעשי העם, שמא זכאים הם לגשם.","\u0003אתו עבדיה ורמו ליה סודרא בצוריה וקא מצערו ליה\u0004 \u0005[באו עבדיו\u0006 של הנשיא, \u0005והשליכו,\u0006 הניחו \u0005לו סודר בצווארו וציערו אותו]\u0006 על שהעליב את בית הנשיא. \u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003בני מאתיה\u0004 \u0005[עירו]:\u0006 \u0003שבקיה\u0004 \u0005[הנח לו],\u0006 \u0003דהא נמי מצער לן\u0004 \u0005[שהוא גם כן מצער אותנו]\u0006 בדברי תוכחה קשים, ואף על פי כן \u0003כיון דחזינן דכל מיליה לשום\u0004 \u0005[שרואים אנו שכל דבריו לשם]\u0006 \u0003שמים לא אמרי ליה מידי\u0004 \u0005[אין אנו אומרים לו דבר],\u0006 \u0003ושבקינן ליה\u0004 \u0005[ומניחים אנו לו]\u0006 ומרשים לו לדבר, \u0003אתון נמי שבקוהו\u0004 \u0005[אתם גם כן הניחו לו].\u0006","מסופר: \u0003רבי גזר תעניתא\u0004 \u0005[תענית]\u0006 \u0003ולא אתא מיטרא\u0004 \u0005[בא גשם].\u0006 \u0003נחית קמיה\u0004 \u0005[ירד לפניו]\u0006 שליח הציבור \u0003אילפא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003ר' אילפי.\u0004 כאשר \u0003אמר\u0004 בתפילה \u0003\"משיב הרוח\",\u0004 מיד \u0003ונשא זיקא\u0004 \u0005[ונשב הרוח],\u0006 אמר \u0003\"מוריד הגשם\"\u0004 מיד \u0003ואתא מיטרא\u0004 \u0005[ובא הגשם].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבי: \u0003מאי עובדך\u0004 \u0005[מה\u0006 הם \u0005מעשיך]\u0006 הטובים, שבגללם אתה נענה כך בתפילתך? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דיירנא בקוסטא דחיקא דלית ביה חמרא לקידושא ואבדלתא\u0004 \u0005[אני גר בעיירה דחוקה\u0006 בכסף \u0005שאין בה יין לקידוש והבדלה]\u0006 \u0003טרחנא ואתינא חמרא לקידושא ואבדלתא, ומפיקנא להו ידי חובתייהו\u0004 \u0005[טורח אני ומביא אני\u0006 בכל פעם \u0005יין לקידוש ולהבדלה, ומוציא אני אותם ידי חובתם]\u0006 ובשכר השתדלותו במצוה זו — זכה.","מסופר: \u0003רב איקלע לההוא אתרא\u0004 \u0005[הזדמן למקום אחד],\u0006 \u0003גזר תעניתא\u0004 \u0005[תענית]\u0006 \u0003ולא אתא מיטרא\u0004 \u0005[בא גשם],\u0006 \u0003נחית קמיה שליחא דצבורא\u0004 \u0005[ירד לפניו שליח הציבור]\u0006 בתפילה, \u0003אמר \"משיב הרוח\" ונשב זיקא\u0004 \u0005[ונשבה רוח],\u0006 \u0003אמר \"מוריד הגשם\" ואתא מיטרא\u0004 \u0005[ובא הגשם],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב: \u0003מאי עובדך\u0004 \u0005[מה\u0006 הם \u0005מעשיך]\u0006 הטובים? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מיקרי דרדקי אנא, ומקרינא\u0004 \u0005[מלמד תינוקות אני, ומלמד אני מקרא]\u0006 \u0003לבני עניי\u0004 \u0005[עניים]\u0006 \u0003כבני עתירי\u0004 \u0005[עשירים]\u0006 \u0003וכל\u0004 מי ש\u0003לא אפשר ליה\u0004 \u0005[יכול לו\u0006 לשלם\u0005] —\u0006 \u0003לא שקלינא מיניה מידי\u0004 \u0005[אינני לוקח ממנו דבר].\u0006 \u0003ואית\u0004 \u0005[ויש]\u0006 \u0003לי פירא דכוורי\u0004 \u0005[בריכה של דגים]\u0006 \u0003וכל מאן דפשע\u0004 \u0005[מי שמתרשל\u0006 בלימודו\u0005],\u0006 \u0003משחדינא ליה מינייהו, ומסדרינן ליה, ומפייסינן ליה\u0004 \u0005[משחד אני אותו בהם, ומרגיע אני אותו, ומפייס אני אותו]\u0006 \u0003עד דאתי וקרי\u0004 \u0005[ש\u0006הוא \u0005בא וקורא].\u0006","מסופר: \u0003רב נחמן גזר תעניתא\u0004 \u0005[תענית]\u0006 על הגשם, \u0003בעא רחמי\u0004 \u0005[ביקש רחמים]\u0006 \u0003ולא אתא מיטרא\u0004 \u0005[בא הגשם],\u0006 \u0003אמר\u0004 בצערו: \u0003שקלוה\u0004 \u0005[קחוהו]\u0006 את \u0003נחמן, חבוטו\u0004 \u0005[השליכו אותו]\u0006 \u0003מן גודא לארעא\u0004 \u0005[הכותל לארץ],\u0006 שהרי רואים שאין התענית שגזר מועילה. \u0003חלש דעתיה ואתא מיטרא\u0004 \u0005[חלשה דעתו ו\u0006אז \u0005בא הגשם].\u0006","מסופר: \u0003רבה גזר תעניתא\u0004 \u0005[תענית],\u0006 \u0003בעי רחמי\u0004 \u0005[ביקש רחמים]\u0006 \u0003ולא אתא מיטרא\u0004 \u0005[בא גשם].\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב יהודה כי הוה גזר תעניתא\u0004 \u0005[כאשר היה גוזר תענית]\u0006 \u0003אתא מיטרא\u0004 \u0005[היה בא גשם].\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003מאי אעביד\u0004 \u0005[מה אעשה]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום תנויי\u0004 \u0005[לימוד]\u0006 התורה — \u0003אנן עדיפינן מינייהו\u0004 \u0005[אנחנו עדיפים מהם],\u0006 מבני הדור הקודם, \u0003דבשני\u0004 \u0005[שבשנותיו]\u0006 של \u0003רב יהודה כל תנויי\u0004 \u0005[לימודם]\u0006"],["\u0003ב\u0004סדר \u0003נזיקין\u0004 בלבד \u0003הוה\u0004 \u0005[היה],\u0006 ולא ידעו הרבה בשאר סדרי המשנה, \u0003ואנן קא מתנינן בשיתא סדרין\u0004 \u0005[ואנחנו מלמדים בשישה סדרים]\u0006 כולם, \u0003וכי הוה מטי\u0004 \u0005[וכאשר היה מגיע]\u0006 \u0003רב יהודה\u0004 בלימודו \u0003ב\u0004מסכת \u0003עוקצין\u0004 להלכה של \u0003\"האשה שכובשת ירק בקדירה\" ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 בהלכה של \u0003\"זיתים שכבשן בטרפיהן\u0004 (בעלים שלהם) \u0003\",\u0004 שאותו ירק, או אותם עלים \u0003טהורין\u0004 מלהביא טומאה לאוכל עצמו\u0003, אמר: הוייות\u0004 \u0005[מחלוקות]\u0006 של \u0003רב ושמואל קא חזינא הכא\u0004 \u0005[אני רואה כאן],\u0006 שהיה מתקשה בהבנת הדברים, והיה אומר שהם קשים בעיניו כמו המחלוקות החמורות של רב ושמואל,","\u0003ואנן קא מתנינן בעוקצין תליסר מתיבתא\u0004 \u0005[ואנחנו מלמדים ב\u0006מסכת \u0005עוקצין שלוש עשרה ישיבות]\u0006 \u0003ואילו רב יהודה כי הוה שליף חד מסאנא\u0004 \u0005[כאשר היה חולץ נעל אחת]\u0006 בלבד לאות צער משום התענית, טרם שחלץ נעל שניה \u0003אתי מיטרא\u0004 \u0005[היה בא גשם],\u0006 \u0003ואנן קא צווחינן כולי יומא וליכא דאשגח בן\u0004 \u0005[ואנחנו צווחים כל היום ואין שמשגיח בנו],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום עובדא\u0004 \u0005[מעשים\u0006 לא טובים\u0005]\u0006 — \u0003אי איכא דחזא מידי\u0004 \u0005[אם יש\u0006 מי \u0005שראה דבר]\u0006 שאינו ראוי — \u0003לימא\u0004 \u0005[שיאמר],\u0006 ואם כן אין הדבר תלוי בחסרונו של רבה, \u0003אבל מה יעשו גדולי הדור שאין דורן דומה יפה\u0004 ובעוון הדור אין הגשמים יורדים.","ובענין כוח תפילתו של רב יהודה מסופר: \u0003רב יהודה חזא הנהו בי תרי דהוו קא פרצי בריפתא\u0004 \u0005[ראה שני\u0006 אנשים \u0005שהיו מזלזלים בלחם],\u0006 שהיו זורקים לחם מאחד לשני, \u0003אמר: שמע מינה איכא שבעא בעלמא\u0004 \u0005[מכאן\u0006 נראה ש\u0005יש שובע בעולם]\u0006 שאנשים נוהגים כך בלחם, \u0003יהיב עיניה\u0004 \u0005[נתן עיניו]\u0006 והקפיד על כך — \u0003הוה כפנא\u0004 \u0005[\u0006ו\u0005נהיה רעב].\u0006 \u0003אמרו ליה רבנן\u0004 \u0005[לו חכמים]\u0006 \u0003לרב כהנא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחוניא שמעיה\u0004 \u0005[שמשו]\u0006 של רב יהודה: \u0003מר דשכיח קמיה, ניעשייה דליפוק בפתחא דסמוך לשוקא\u0004 \u0005[אדוני שמצוי לפניו,\u0006 לפני רב יהודה, \u0005יכפה עליו שיצא בפתח סמוך לשוק]\u0006 שיראה בעיניו את הרעב בעולם. \u0003עשייה ונפק לשוקא, חזא כנופיא\u0004 \u0005[כפה אותו ויצא לשוק, ראה קבוצה\u0006 של אנשים\u0005],\u0006","\u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003מאי האי\u0004 \u0005[מה זה]\u0006 שאתם מתקבצים יחד? \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003אכוספא דתמרי קיימי דקא מזדבן\u0004 \u0005[על כלי של תמרים אנחנו עומדים, שמוכרים אותם\u0006 עכשיו\u0005].\u0006 \u0003אמר:\u0004 אם קבוצה גדולה של אנשים עומדים סביב כלי אחד של תמרים לקנותו לאכילה, \u0003שמע מינה כפנא בעלמא\u0004 \u0005[מכאן שרעב בעולם],\u0006 \u0003אמר ליה לשמעיה\u0004 \u0005[לו לשמשו]:\u0006 \u0003שלוף לי מסאניי\u0004 \u0005[חלוץ לי\u0006 את \u0005נעליי]\u0006 לאות צער, שרצוני להתענות על כך. \u0003שלף ליה חד מסאנא ואתא מיטרא\u0004 \u0005[חלץ לו נעל אחת ובא גשם],\u0006 \u0003כי מטא למישלף אחרינא\u0004 \u0005[כאשר בא לחלוץ את השניה]\u0006 \u0003אתא\u0004 \u0005[בא]\u0006 \u0003אליהו ואמר ליה\u0004 \u0005[לו]:\u0006 \u0003אמר הקדוש ברוך הוא\u0004 עכשיו: \u0003אי שלפת אחרינא\u0004 \u0005[אם חולץ אתה\u0006 נעל \u0005אחרת] —\u0006 \u0003מחריבנא לעלמא\u0004 \u0005[מחריב אני את העולם],\u0006 שלא יהא לך כל צער בו.","\u0003אמר רב מרי ברה דבת\u0004 \u0005[בנה של בת]\u0006 \u0003שמואל: אנא הוה קאימנא אגודא\u0004 \u0005[אני הייתי עומד\u0006 באותה שעה \u0005על שפת]\u0006 \u0003נהר פפא\u0004 הסמוך, \u0003חזאי למלאכי דאידמו למלחי דקא מייתי חלא ומלונהו לארבי והוה קמחא דסמידא\u0004 \u0005[ראיתי מלאכים שהיו נראים כמו מלחים שהביאו חול ומילאו את האוניות ונעשה ממנו קמח סולת].\u0006 \u0003אתו כולי עלמא למיזבן\u0004 \u0005[באו הכל לקנות]\u0006 מאותו קמח, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003מהא לא תיזבנון\u0004 \u0005[מזה אל תקנו]\u0006 שמ \u0003מעשה נסים הוא, למחר אתיין ארבי דחיטי\u0004 \u0005[יבואו אוניות חיטים]\u0006 מן המקום \u0003פרזינא\u0004 ומשם תקנו.","ועוד מסופר: \u0003רבא איקלע\u0004 \u0005[נזדמן]\u0006 \u0003ל\u0004עיר \u0003הגרוניא, גזר תעניתא\u0004 \u0005[תענית]\u0006 \u0003ולא אתא מיטרא\u0004 \u0005[בא גשם].\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003ביתו כולי עלמא בתעניתייכו\u0004 \u0005[ילונו כל העם בתעניתם]\u0006 ולא יאכלו בערב זה. \u0003למחר\u0004 \u0005[למחרת\u0006 בבוקר\u0005]\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003מי איכא דחזא חילמא\u0004 \u0005[האם יש מי שראה חלום] —\u0006 \u0003לימא\u0004 \u0005[שיאמר,\u0006 יספר חלומו\u0005].\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003ר' אלעזר מהגרוניא: לדידי אקריון בחלמי\u0004 \u0005[הקריאו לי בחלומי]\u0006 משפט זה: \u0003שלם טב לרב טב מריבון טב, דמטוביה מטיב לעמיה\u0004 \u0005[שלום טוב לרב טוב מאדון טוב שמטובו מיטיב לעמו].\u0006 \u0003אמר\u0004 רבא: \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003עת רצון היא מבעי רחמי\u0004 \u0005[לבקש רחמים].\u0006 \u0003בעי רחמי ואתי מיטרא\u0004 \u0005[ביקש רחמים וירד גשם].\u0006","ועוד מסופר בענין תפילה על הגשם, ותחילה מספרים את הרקע לענין, \u0003ההוא גברא דאיחייב נגדא בבי דינא\u0004 \u0005[אדם אחד שנתחייב מלקות בבית הדין]\u0006 של \u0003רבא משום\u0004 ש\u0003בעל גויה, נגדיה\u0004 \u0005[הלקהו],\u0006 ציוה \u0003רבא\u0004 להלקותו \u0003ומית\u0004 \u0005[ומת]\u0006 האיש מהמכות. \u0003אשתמע מילתא בי שבור מלכא, בעא לצעורי\u0004 \u0005[נשמע הדבר בביתו של המלך\u0006 הפרסי \u0005שבור, ורצה לצער]\u0006 את \u0003רבא\u0004 על שדן דיני נפשות בלא רשות המלך. \u0003אמרה ליה\u0004 \u0005[לו]\u0006 \u0003איפרא הורמיז אימיה\u0004 \u0005[אמו]\u0006 של \u0003שבור מלכא\u0004 \u0005[המלך]\u0006 \u0003לברה\u0004 \u0005[לבנה]:\u0006 ש\u0003לא ליהוי\u0004 \u0005[יהיה]\u0006 \u0003לך עסק דברים\u0004 של קטטה \u0003בהדי יהודאי\u0004 \u0005[עם היהודים],\u0006 \u0003דכל מאן דבעיין ממרייהו יהיב להו\u0004 \u0005[שכל מה שהם מבקשים מאדוניהם,\u0006 הקדוש ברוך הוא, \u0005נותן להם].\u0006","\u0003אמר לה: מאי היא\u0004 \u0005[מה הוא]\u0006 הדבר? אמרה לו: \u0003בעין רחמי ואתי מיטרא\u0004 \u0005[מבקשים רחמים ובא הגשם].\u0006 \u0003אמר לה:\u0004 זו איננה הוכחה שה' שומע לקולם, כי הדבר \u0003ההוא\u0004 קורה \u0003משום דזימנא דמיטרא\u0004 \u0005[שזמן הגשם]\u0006 \u0003הוא\u0004 ובמקרה מזדמן שיורדים גשמים אחר תפילתם \u0003אלא\u0004 אם רצונם להוכיח זאת, \u0003לבעו רחמי האידנא\u0004 \u0005[שיבקשו רחמים עכשיו],\u0006 \u0003בתקופת תמוז, וליתי מיטרא\u0004 \u0005[ושיבוא גשם]\u0006 ואז נראה אם אכן תפילתם היא הקובעת. \u0003שלחה ליה\u0004 \u0005[לו]\u0006 איפרא הורמיז \u0003לרבא: כוין דעתך ובעי רחמי דליתי מיטרא\u0004 \u0005[כוון דעתך ובקש רחמים שירד גשם].\u0006 \u0003בעי רחמי ולא אתי מיטרא\u0004 \u0005[ביקש רחמים ולא בא הגשם].\u0006","\u0003אמר לפניו: רבונו של עולם!\u0004 כבר נאמר: \u0003\"אלהים באזנינו שמענו אבותינו ספרו לנו פעל פעלת בימיהם בימי קדם\"\u0004 (תהלים מד, ב), \u0003ואנו בעינינו לא ראינו!\u0004 וכיון שאמר זאת \u0003אתא מיטרא עד דשפוך מרזבי דצפורי לדיגלת\u0004 \u0005[ירד גשם\u0006 רב \u0005עד ששפכו מרזבי\u0006 מחוזא מים \u0005ל\u0006נהר \u0005חידקל],\u0006 \u0003אתא אבוה איתחזי ליה בחלמיה\u0004 \u0005[בא אביו\u0006 של רבא, \u0005נראה לו בחלום]\u0006 \u0003ואמר ליה\u0004 \u0005[לו]:\u0006 \u0003מי איכא דמיטרח קמי שמיא כולי האי\u0004 \u0005[האם יש מי שמטריח לפני השמים כל כך]\u0006 לבקש גשם שלא בזמנו? \u0003אמר לו\u0004 אביו בחלום: \u0003שני דוכתיך\u0004 \u0005[שנה את מקומך]\u0006 שלא תנזק. \u0003שני דוכתיה\u0004 \u0005[שינה את מקומו]\u0006 שישן בו בלילה, \u0003למחר\u0004 בבוקר \u0003אשכחיה דמרשם פורייה בסכיני\u0004 \u0005[מצא שבמיטתו סימני סכינים]\u0006 שננעצו במיטה, ועל ידי שינוי מקומו ניצל רבא.","מסופר: \u0003רב פפא גזר תעניתא\u0004 \u0005[תענית]\u0006 \u0003ולא אתא מיטרא\u0004 \u0005[ירד גשם],\u0006 \u0003חלש ליביה, שרף פינכא דדייסא, ובעי רחמי\u0004 \u0005[נחלש ליבו\u0006 מרעב \u0005גמע צלחת דיסה, ביקש רחמים]\u0006 \u0003ולא אתא מיטרא\u0004 \u0005[בא גשם].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן בר אושפזתי\u0004 בצחוק: \u0003אי שריף מר פינכא אחריתי דדייסא אתי מיטרא\u0004 \u0005[אם יגמע,\u0006 יאכל \u0005אדוני צלחת אחרת של דיסה ירד גשם],\u0006 שהרי הכל מתענים ורב פפא אוכל. \u0003איכסיף, וחלש דעתיה, ואתא מיטרא\u0004 \u0005[התבייש, וחלשה דעתו, ובא הגשם].\u0006","ועוד לענין תפילה על הגשם. מסופר: \u0003ר' חנינא בן דוסא הוה קא אזיל באורחא אתא מיטרא\u0004 \u0005[היה הולך בדרך\u0006 ו\u0005בא גשם],\u0006 \u0003אמר לפניו: רבונו של עולם, כל העולם כולו בנחת,\u0004 שהכל צריכים לגשמים \u0003וחנינא בצער\u0004 מפני הגשם! \u0003פסק מיטרא\u0004 \u0005[הגשם]\u0006 לרדת. \u0003כי מטא לביתיה\u0004 \u0005[כאשר הגיע לביתו]\u0006 \u0003אמר לפניו: רבונו של עולם, כל העולם כולו בצער\u0004 על עצירת הגשמים \u0003וחנינא בנחת? אתא מיטרא\u0004 \u0005[בא הגשם].\u0006","על סיפור זה \u0003אמר רב יוסף:\u0004 כמה גדול כוחו של ר' חנינא, כי \u0003מאי אהניא ליה צלותא\u0004 \u0005[מה הועילו לו תפילות]\u0006 של ה\u0003כהן\u0004 ה\u0003גדול לגבי ר' חנינא בן דוסא. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003היה\u0004 הכהן הגדול בצאתו ביום הכיפורים מקודש הקודשים \u0003מתפלל תפלה קצרה בבית החיצון\u0004 (בהיכל). ושאלו: \u0003מאי מצלי\u0004 \u0005[מה היה מתפלל]?\u0006 \u0003רבין בר אדא ורבא בר אדא דאמרי תרוייהו משמיה\u0004 \u0005[שאמרו שניהם משמו]\u0006 של \u0003רב יהודה,\u0004 שכך היה אומר: \u0003יהי רצון מלפניך ה' אלהינו שתהא השנה הזו גשומה ושחונה\u0004 (וחמה). על לשון זו תוהים: וכי שנה \u0003שחונה מעלייתא\u0004 \u0005[מעולה]\u0006 \u0003היא? אדרבא, גריעותא\u0004 \u0005[להיפך, גרועה]\u0006 \u0003היא!\u0004","\u0003אלא\u0004 כך היה מתפלל: \u0003אם\u0004 השנה הבאה שנה \u0003שחונה\u0004 היא — נבקש כי \u0003תהא\u0004 גם \u0003גשומה וטלולה\u0004 (מרובה בגשם ובטל). ועוד היה הכהן הגדול אומר בתפילתו: \u0003ואל יכנס לפניך תפילת עוברי דרכים,\u0004 שאף שהם מתפללים שלא ירדו גשמים ויצערו אותם בדרכם, חשוב יותר שירד גשם לטובת הציבור כולו. \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא מסיים משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב יהודה\u0004 בנוסח תפילת הכהן הגדול, שהיה אומר: \u0003לא יעדי עביד שולטן\u0004 \u0005[יסור שלטון]\u0006 \u0003מ\u0004של \u0003בית יהודה, ואל יהו עמך ישראל צריכין להתפרנס\u0004 בצדקה \u0003זה מזה, ולא\u0004 יהיו צריכים לסיוע בפרנסה \u0003לעם אחר.\u0004 ואף שהיה הכהן הגדול מתפלל בהיכל שלא תישמע בקשת עוברי דרכים, בכל זאת נשמעה בקשתו (הראשונה) של רבי חנינא בן דוסא.","כיון שהוזכר ר' חנינא בן דוסא מספרים כמה דברים על צדקותו ועל מופתים שעשה. \u0003אמר רב יהודה אמר רב: בכל יום ויום בת קול יוצאת ואומרת: כל העולם כולו ניזון בשביל\u0004 (בזכות) \u0003חנינא\u0004 בן דוסא \u0003בני, ו\u0004אילו \u0003חנינא בני\u0004 עצמו \u0003דיו בקב חרובים\u0004 שזה מאכל עניים זול ביותר, ומסתפק בו \u0003מערב שבת לערב שבת.\u0004 ומסופר: \u0003הוה רגילא דביתהו למיחמא תנורא כל מעלי דשבתא ושדייא אקטרתא\u0004 \u0005[היתה רגילה אשתו לחמם את התנור כל ערב שבת ולהעלות עשן\u0006 גדול\u0005]\u0006"],["\u0003משום כיסופא\u0004 \u0005[בושה],\u0006 שלא רצתה שידעו השכנות שאין לחם בביתה. \u0003הוה לה הך שיבבתא בישתא\u0004 \u0005[היתה לה שכנה רעה אחת]\u0006 \u0003אמרה\u0004 השכנה בלבה: \u0003מכדי ידענא דלית להו ולא מידי, מאי כולי האי\u0004 \u0005[הרי יודעת אני שאין להם דבר, מה\u0006 אם כן \u0005כל זה]\u0006 שהיא מסיקה את התנור? \u0003אזלא וטרפא אבבא\u0004 \u0005[הלכה ודפקה בדלת]\u0006 להיכנס ולראות מה בתנור, \u0003איכספא ועיילא לאינדרונא\u0004 \u0005[התביישה\u0006 אשת ר' חנינא \u0005ונכנסה לחדר הפנימי],\u0006","\u0003איתעביד לה נסא דחזיא לתנורא\u0004 \u0005[נעשה לה נס שראתה\u0006 השכנה \u0005שהתנור]\u0006 \u0003מלא לחמא\u0004 \u0005[לחם]\u0006 \u0003ואגנא\u0004 \u0005[והאגן]\u0006 \u0003מלא לישא\u0004 \u0005[בצק],\u0006 \u0003אמרה לה\u0004 השכנה: \u0003פלניתא פלניתא\u0004 \u0005[פלונית פלונית]\u0006 \u0003אייתי מסא, דקא חריך לחמיך\u0004 \u0005[הביאי מרדה, שנחרך\u0006 \u0005לחמך\u0006 בתנור\u0005].\u0006 \u0003אמרה לה\u0004 אשת ר' חנינא: \u0003אף אנא\u0004 \u0005[אני]\u0006 \u0003להכי עיילי\u0004 \u0005[לשם כך נכנסתי]\u0006 לחדר הפנימי. \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003אף היא\u0004 באמת \u0003להביא מרדה נכנסה, מפני ש\u0004היתה \u0003מלומדת\u0004 (רגילה) \u0003בנסים\u0004 וידעה שיקרה לה נס ולא תבוא לידי בושה.","ועוד מסופר: \u0003אמרה ליה דביתהו\u0004 \u0005[לו אשתו]\u0006 לר' חנינא: \u0003עד אימת\u0004 \u0005[מתי]\u0006 \u0003ניזיל ונצטער כולי האי\u0004 \u0005[נלך ונצטער כל כך\u0006 בעוני\u0005]?\u0006 \u0003אמר לה: מאי נעביד\u0004 \u0005[מה נעשה]?\u0006 אמרה לו: \u0003בעי רחמי דניתבו לך מידי\u0004 \u0005[בקש רחמים שיתנו לך דבר מה\u0006 משמים\u0005].\u0006 \u0003בעא רחמי\u0004 \u0005[ביקש רחמים],\u0006 \u0003יצתה כמין פיסת יד ויהבו ליה חד כרעא דפתורא דדהבא\u0004 \u0005[ונתנו לו רגל אחת של שולחן זהב].\u0006 \u0003חזאי בחלמא, עתידי צדיקי דאכלי אפתורא דדהבא דאית ליה תלת כרעי\u0004 \u0005[ראתה בחלום שעתידים צדיקים שאוכלים על שולחן זהב שיש לו שלוש רגלים]\u0006 \u0003ואת אוכלת אפתורא דתרי כרעי\u0004 \u0005[על שולחן של שתי רגלים].\u0006","בספרה את חלומה לבעלה, \u0003אמר לה: ניחא\u0004 \u0005[\u0006האם \u0005נוח]\u0006 \u0003לך דמיכל אכלי כולי עלמא אפתורא דמשלם ואנן אפתורא דמיחסר\u0004 \u0005[שיאכלו הכל על שולחן שלם ואנחנו על שולחן חסר],\u0006 שאותה רגל אחת ניטלה מאותו שולחן זהב. \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003ומאי נעביד\u0004 \u0005[ומה נעשה]?\u0006 \u0003בעי רחמי דנשקלינהו מינך\u0004 \u0005[בקש רחמים שיטלו אותה,\u0006 את הרגל \u0005ממך].\u0006 \u0003בעי רחמי ושקלוהו\u0004 \u0005[ביקש רחמים ונטלו אותה].\u0006 ומעירים: \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 בברייתא: \u0003גדול היה\u0004 ה\u0003נס\u0004 ה\u0003אחרון יותר מן\u0004 הנס \u0003הראשון. דגמירי, דמיהב יהבי מישקל לא שקלי\u0004 \u0005[שלמדנו\u0006 במסורת, \u0005ש\u0006משמים \u0005נותנים\u0006 אבל \u0005אין נוטלים].\u0006","ועוד מסופר: \u0003חד בי שמשי חזייה לברתיה דהוות עציבא\u0004 \u0005[ערב שבת אחד ראה את בתו שהיא עצובה],\u0006 \u0003אמר לה: בתי למאי עציבת\u0004 \u0005[מדוע את עצובה]?\u0006 \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003כלי של חומץ נתחלף לי בכלי של שמן והדלקתי ממנו אור\u0004 (אש) \u0003לשבת,\u0004 שהוסיפה בנר השמן מן החומץ, ועוד מעט יכבה הנר בשל כך. \u0003אמר לה: בתי מאי אכפת לך? מי שאמר לשמן וידלוק — הוא יאמר לחומץ וידלוק. תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003היה\u0004 אותו נר \u0003דולק והולך\u0004 בשבת \u0003כל היום כולו, עד שהביאו ממנו אור להבדלה.\u0004","ועוד מסופר: \u0003ר' חנינא בן דוסא הוו ליה הנך עיזי\u0004 \u0005[היו לו אותם עיזים],\u0006 \u0003אמרו ליה\u0004 \u0005[לו]\u0006 השכנים: \u0003קא מפסדן\u0004 \u0005[\u0006העזים \u0005מזיקות לנו],\u0006 שאוכלות בשדותינו. \u0003אמר: אי קא מפסדן\u0004 \u0005[אם הן\u0006 אכן \u0005מזיקות] —\u0006 \u0003ניכלינהו דובי\u0004 \u0005[שיאכלו אותן דובים],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא — כל חדא וחדא\u0004 \u0005[אחת ואחת]\u0006 מהן \u0003תיתי לאורתא דובא בקרנייהו\u0004 \u0005[תביא בערב דוב בקרניה].\u0006 \u0003לאורתא אייתי\u0004 \u0005[בערב הביאה]\u0006 \u0003כל חדא וחדא\u0004 \u0005[אחת ואחת]\u0006 \u0003דובא בקרנייהו\u0004 \u0005[דוב בקרניה].\u0006","ועוד סיפרו: \u0003הוה ליה ההיא שיבבתא דקא בניא ביתא\u0004 \u0005[היתה לו שכנה שבנתה בית]\u0006 \u0003ולא מטו כשורי\u0004 \u0005[הגיעו,\u0006 הספיקו, \u0005הקורות]\u0006 שעשו עבור התיקרה באורכם מקיר לקיר. \u0003אתיא לקמיה\u0004 \u0005[באה לפניו]\u0006 \u0003ואמרה ליה\u0004 \u0005[לו]:\u0006 \u0003בניתי ביתי ולא קמטו כשוראי\u0004 \u0005[ואין מגיעות קורותי],\u0006 שאין אורכן מספיק. \u0003אמר לה: מה שמך? אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003איכו\u0004 שמי. \u0003אמר: איכו נימטו כשוריך\u0004 \u0005[אם כן יגיעו\u0006 יאריכו \u0005קורותיך].\u0006","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003הגיעו\u0004 התארכו הקורות \u0003עד שיצאו אמה לכאן ואמה לכאן\u0004 מכל צד. \u0003ויש אומרין: סניפין עשאום,\u0004 שנתחברו להן בנס לקורות הקיימים, עוד קורות מכל צד. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 החכם \u0003פלימו אומר: אני ראיתי אותו הבית, והוו קורותיו יוצאות אמה לכאן ואמה לכאן, ואמרו לי: בית זה שקירה\u0004 (שעשה את התיקרה) \u0003ר' חנינא בן דוסא בתפלתו.\u0004","אגב כך שואלים: \u0003ור' חנינא בן דוסא מהיכן הוו ליה\u0004 \u0005[היו לו]\u0006 \u0003עזים? והא\u0004 \u0005[והרי]\u0006 \u0003עני הוי\u0004 \u0005[היה],\u0006 כפי שסופר?! \u0003ועוד:\u0004 הלא \u0003אמרו חכמים: אין מגדלין בהמה דקה בארץ ישראל,\u0004 מפני שמשחיתות את השדות ורכוש הזרים, וכיצד איפוא גידל הוא עיזים? \u0003אמר רב פנחס:\u0004 כך אירע הדבר, \u0003מעשה ועבר אדם אחד על פתח ביתו\u0004 של ר' חנינא \u0003והניח שם תרנגולין\u0004 ושכח לקחתן, \u0003ומצאתן אשתו של ר' חנינא בן דוסא,\u0004 וטיפלו הם באבידה זו,","\u0003ואמר לה: אל תאכלי מביציהן,\u0004 שהן מציאה ואין לנו זכות בהן. \u0003והרבו\u0004 התרנגולות \u0003ביצים ו\u0004אחר כך בקעו מן הביצים \u0003תרנגולין והיו מצערין אותם\u0004 התרנגולות הללו ברעש ובליכלוך, \u0003ומכרן וקנה בדמיהן עזים. פעם אחת עבר אותו אדם שאבדו ממנו התרנגולין ואמר לחבירו: בכאן הנחתי התרנגולין שלי. שמע\u0004 זאת \u0003ר' חנינא, אמר לו: יש לך בהן\u0004 באותן התרנגולות \u0003סימן? אמר לו: הן\u0004 (כן). \u0003נתן לו סימן ונטל\u0004 אותו האיש \u0003את העיזין, והן הן עיזי דאייתו דובי בקרנייהו\u0004 \u0005[העיזים שהביאו דובים בקרניהן].\u0006","אגב סיפורים אלה מספרים עוד על צדיקים שהיו עניים ביותר. מסופר: \u0003ר' אלעזר בן פדת דחיקא ליה מילתא טובא\u0004 \u0005[\u0006היה \u0005דחוק לו הדבר,\u0006 פרנסתו \u0005הרבה].\u0006 \u0003עבד מלתא ולא הוה ליה מידי למטעם\u0004 \u0005[עשה דבר,\u0006 הקיז דם, \u0005ולא היה לו דבר לטעום]\u0006 אחר כך, \u0003שקל ברא דתומא ושדייה בפומיה, חלש לביה ונים\u0004 \u0005[לקח בן שום,\u0006 שן אחת של שום \u0005והניח בפיו\u0006 ו\u0005נחלש ליבו\u0006 שהתעלף, \u0005וישן].\u0006 \u0003אזול רבנן לשיולי ביה\u0004 \u0005[הלכו חכמים לשאול בו\u0006 לשלומו\u0005],\u0006 \u0003חזיוהו דקא בכי וחייך, ונפק צוציתא דנורא מאפותיה\u0004 \u0005[ראו אותו שהוא בוכה וצוחק, ויוצאת קרן אור ממצחו].\u0006","\u0003כי אתער\u0004 \u0005[כאשר התעורר]\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003מאי טעמא קבכית וחייכת\u0004 \u0005[מה טעם בכית וצחקת]?\u0006 \u0003אמר להו\u0004 \u0005[להם],\u0006 כך היה המעשה: \u0003דהוה יתיב עמי\u0004 \u0005[שהיה יושב איתי]\u0006 \u0003הקדוש ברוך הוא, ואמרי ליה\u0004 \u0005[ואמרתי לו],\u0006 \u0003עד מתי אצטער בהאי עלמא\u0004 \u0005[בעולם זה]\u0006 בדחק? \u0003ואמר לי: אלעזר בני, ניחא לך דאפכיה לעלמא מרישא\u0004 \u0005[\u0006האם \u0005נוח לך שאהפוך את העולם מראשיתו],\u0006 \u0003אפשר דמתילדת בשעתא דמזוני\u0004 \u0005[ש\u0006אז \u0005תיוולד בשעה,\u0006 במזל \u0005של מזונות]\u0006 ולא תהיה עני.","\u0003אמרי לקמיה: כולי האי\u0004 \u0005[אמרתי לפניו: כל כך]\u0006 ישתנה העולם \u0003ו\u0004עדיין רק \u0003אפשר\u0004 ולא ודאי? ועוד \u0003אמרי ליה\u0004 \u0005[אמרתי לו]:\u0006 \u0003דחיי טפי או דחיינא\u0004 \u0005[\u0006האם השנים \u0005שחייתי\u0006 הן \u0005יותר, או אלה שאחיה]?\u0006 \u0003אמר לי: דחיית\u0004 \u0005[\u0006אלה \u0005שחיית]\u0006 הן רבות יותר. \u0003אמרי לקמיה\u0004 \u0005[אמרתי לפניו]:\u0006 \u0003אם כן, לא בעינא\u0004 \u0005[אין אני רוצה]\u0006 להפוך את סדר העולם רק עבור אותן שנים שיש לי עוד להצטער.","\u0003אמר לי: בהאי אגרא דאמרת \"לא בעינא\" יהיבנא לך לעלמא דאתי תליסרי נהרוותא דמשחא אפרסמון דכיין כפרת ודיגלת, דמענגת בהו\u0004 \u0005[בשכר זה שאמרת \"אין אני רוצה\" נותן אני לך לעולם הבא שלושה עשר נהרות שמן אפרסמון טהור\u0006 גדולים \u0005כפרת וכחידקל, שתתענג בהם].\u0006 \u0003אמרי לקמיה\u0004 \u0005[אמרתי לפניו]:\u0006 \u0003האי ותו לא\u0004 \u0005[\u0006רק \u0005זה ולא עוד]?\u0006 \u0003אמר לי: ולחברך מאי יהיבנא\u0004 \u0005[ולחבריך מה אתן],\u0006 אם תקבל אתה יותר? \u0003אמרי ליה\u0004 \u0005[אמרתי לו]:\u0006 \u0003ואנא מגברא דלית ליה בעינא\u0004 \u0005[ו\u0006כי \u0005אני מאדם שאין לו אני מבקש]?\u0006 הלא אתה יכול לעשות הכל! \u0003מחיין באסקוטלא אפותאי\u0004 \u0005[היכה אותי באצבע על מצחי]\u0006 כדרך שעושים לשעשוע, \u0003ואמר לי\u0004 בחיבה: \u0003אלעזר ברי\u0004 \u0005[בני],\u0006 \u0003גירי בך גירי\u0004 \u0005[חיצי\u0006 אני יורה בך, \u0005חיצי]\u0006 וממגע אצבע זה יצא הזוהר ממצחו.","ושוב לענין תעניות על הגשם. מסופר: \u0003ר' חמא בר חנינא גזר תעניתא\u0004 \u0005[תענית]\u0006 \u0003ולא אתא מיטרא\u0004 \u0005[בא גשם].\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' יהושע בן לוי גזר תעניתא\u0004 \u0005[תענית]\u0006 \u0003ואתי מיטרא\u0004 \u0005[ובא הגשם]!\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003הא אנא, הא בר ליואי\u0004 \u0005[הרי אני, הרי בן לוי]\u0006 ואין אנו בדרגה אחת, שנראה שהוא גדול ממני. \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003דניתי וניכוין דעתין, אפשר דתברי צבורא לבייהו דאתי מיטרא\u0004 \u0005[שנבוא ונכוון את דעתינו, שמא ישבור הציבור ליבם, ויבא גשם].\u0006 \u0003בעון רחמי ולא אתי מיטרא\u0004 \u0005[בקשו רחמים ולא בא גשם].\u0006","\u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003ניחא לכו\u0004 \u0005[נוח לכם]\u0006 \u0003שיבא מטר בשבילנו\u0004 ובזכותנו? \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003הן\u0004 \u0005[כן].\u0006 \u0003אמר: רקיע רקיע כסי פניך\u0004 בעננים! \u0003לא איכסי\u0004 \u0005[התכסה]\u0006 הרקיע. \u0003אמר\u0004 בגערה: \u0003כמה עזין פני רקיע,\u0004 שמתחצף ואינו נשמע, \u0003איכסי ואתא מיטרא\u0004 \u0005[התכסה\u0006 הרקיע בעננים \u0005ובא גשם].\u0006","קצת בדומה לכך מסופר: \u0003לוי גזר תעניתא\u0004 \u0005[תענית]\u0006 \u0003ולא אתא מיטרא\u0004 \u0005[בא גשם].\u0006 \u0003אמר לפניו: רבונו של עולם! עלית וישבת במרום ואין אתה מרחם על בניך. אתא מיטרא\u0004 \u0005[בא גשם],\u0006 אבל כעונש על דברים אלה שאמר בלשון חריפה \u0003ואיטלע\u0004 \u0005[נעשה צולע].\u0006 ומשום כך \u0003אמר ר' אלעזר: לעולם אל יטיח\u0004 (יזרוק, יטיל) \u0003אדם דברים כלפי מעלה\u0004 בלשון קשה, \u0003שהרי אדם גדול הטיח דברים כלפי מעלה ואיטלע\u0004 \u0005[ונעשה צולע]\u0006 \u0003ומנו\u0004 \u0005[ומי הוא] —\u0006 \u0003לוי.\u0004","ושואלים: \u0003והא גרמא ליה\u0004 \u0005[ו\u0006כי \u0005זו\u0006 שהטיח דברים \u0005גרמה לו]\u0006 שנעשה צולע? \u0003והא\u0004 \u0005[והרי]\u0006 המעשה היה ש\u0003לוי אחוי\u0004 \u0005[הראה]\u0006 \u0003קידה\u0004 שעושה כהן גדול \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רבי,\u0004 ומתוך המאמץ נקע את רגלו \u0003ואיטלע\u0004 \u0005[ונעשה צולע]!\u0006 ומשיבים: \u0003הא והא גרמא ליה\u0004 \u0005[זו וזו גרמה לו],\u0006 שכיון שלא נהג כיאות בדבריו, אירע לו שנפגע בשעת המאמץ.","מסופר: \u0003ר' חייא בר לולייני שמעינהו להנך ענני דקאמרי\u0004 \u0005[שמע את אותם העננים שאומרים]\u0006 זה לזה: \u0003ניתו וניתבי מיא\u0004 \u0005[\u0006הבה \u0005נלך ונביא מים]\u0006 \u0003בעמון ומואב\u0004 בעבר הירדן. \u0003אמר לפניו: רבונו של עולם! כשנתת תורה לעמך ישראל חזרת על כל אומות העולם\u0004 שמא יקבלוה, \u0003ולא קיבלוה, ועכשיו אתה נותן להם מטר? שדו הכא\u0004 \u0005[השליכו כאן]\u0006 את המים. \u0003שדיוה אדוכתיהו\u0004 \u0005[השליכו\u0006 העננים את הגשם \u0005במקומם].\u0006","וכיון שהוזכר ר' חייא בר לולייני, מביאים דבר תורה שאמר. \u0003דרש ר' חייא בר לולייני: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"צדיק כתמר יפרח כארז בלבנון ישגה\"\u0004 (תהלים צב, יג), \u0003אם נאמר תמר — למה נאמר ארז, ואם נאמר ארז — למה נאמר תמר?\u0004 ומה נוסף על ידי הדימוי הכפול? והסביר: \u0003אילו נאמר תמר ולא נאמר ארז, הייתי אומר: מה תמר\u0004"],["\u0003אין גזעו מחליף,\u0004 שאם קוצצים אותו שוב אינו צומח, \u0003אף צדיק חס וחלילה אין גזעו מחליף,\u0004 שאם מת אינו קם בתחיית המתים — \u0003לכך נאמר ארז,\u0004 שאף שנקצץ, חוזר וצומח משורשיו, וכן היא גם תקומת הצדיק. ו\u0003אילו נאמר ארז ולא נאמר תמר, הייתי אומר: מה ארז אין עושה פירות\u0004 מאכל \u0003אף צדיק חס וחלילה אין עושה פירות,\u0004 שאין לו שכר לעתיד — \u0003לכך נאמר תמר ונאמר ארז.\u0004","ותוהים: \u0003וארז,\u0004 האם \u0003גזעו מחליף? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הלוקח\u0004 (הקונה) \u0003אילן מחבירו לקוץ,\u0004 שקנה אילן על מנת לקצוץ את הקורה, ולא קנה את האילן כולו — \u0003מגביהו\u0004 את מקום החיתוך \u0003מן הקרקע טפח וקוצץ,\u0004 שמטפח זה יצמיח האילן מחדש, ואם קנה \u0003בסדן השקמה,\u0004 עץ שיקמה גדול — לצורך זה מגביה \u0003שני טפחים,\u0004 אם \u0003בבתולת השקמה,\u0004 שהיא שקמה שעדיין לא נקצצה — מגביה \u0003שלשה טפחים. בקנים ובגפנים,\u0004 שקנה את הקנים והזמורות — חותך \u0003מן הפקק\u0004 (פרק החיבור התחתון) \u0003ולמעלה,\u0004 אבל \u0003בדקלים ובארזים,\u0004 כאשר קונה את הקורות — \u0003חופר\u0004 גם \u0003למטה ומשריש\u0004 (ומוציא את השרשים) \u0003לפי שאין גזעו מחליף.\u0004 משמע שארזים אין גזעם מחליף!","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנחנו עוסקים]\u0006 \u0003בשאר מיני ארזים\u0004 ואלה גזעם מחליף, \u0003כד\u0004 ברי \u0003רבה בר הונא,\u0004 שיש מינים רבים של עצים הקרויים ארזים. ש\u0003אמר רבה בר הונא: עשרה מיני ארזים הם, שנאמר: \"אתן במדבר ארז שטה והדס\u0004 ועץ שמן אשים בערבה ברוש תדהר ותאשור יחדיו\u0003\"\u0004 (ישעיהו מא, יט), ששבעה עצים המנויים בפסוק זה כולם קרויים ארזים, והוסיפו עוד עליהם שלושה מינים אחרים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מעשה בר' אליעזר שגזר שלש עשרה תעניות על הצבור,\u0004 שהן מחזור שלם של תעניות על הגשם \u0003ולא ירדו גשמים, ב\u0004סוף התענית ה\u0003אחרונה התחילו הצבור לצאת\u0004 מבית הכנסת. \u0003אמר להם: תקנתם קברים לעצמכם?!\u0004 שהרי אם לא ירדו גשמים ימותו הכל ברעב. \u0003געו\u0004 (הרימו קול) \u0003כל העם בבכיה, וירדו גשמים.\u0004","\u0003שוב מעשה בר' אליעזר שירד לפני התיבה\u0004 בתענית, \u0003ואמר עשרים וארבע ברכות — ולא נענה. ירד ר' עקיבא אחריו ואמר\u0004 בלשון זו: \u0003\"אבינו מלכנו אין לנו מלך אלא אתה. אבינו מלכנו, למענך רחם עלינו\", וירדו גשמים. הוו מרנני רבנן\u0004 \u0005[היו מרננים חכמים]\u0006 כיצד התלמיד, רבי עקיבא, נענה ואילו רבו רבי אליעזר אינו נענה, \u0003יצתה בת קול ואמרה: לא מפני שזה\u0004 רבי עקיבא \u0003גדול מזה\u0004 מר' אליעזר, \u0003אלא שזה\u0004 רבי עקיבא \u0003מעביר על מידותיו\u0004 (שהוא ותרן וסלחן) ולכן הקדוש ברוך הוא מוותר למענו על גזר־הדין הקשה, מידה כנגד מידה, \u0003וזה\u0004 רבי אליעזר \u0003אינו מעביר על מדותיו,\u0004 ולכן נוהגים עמו גם כן על פי שורת הדין.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003עד מתי\u0004 (כמה) \u0003יהו הגשמים יורדין והצבור פוסקין מתעניתם\u0004 על הגשם? אם ירדו \u0003כמלא ברך המחרישה,\u0004 כלומר, כעומק להב המחרישה עד למקום שהוא מתעקם (ה\"ברך\"), אלו \u0003דברי ר' מאיר, וחכמים אומרים\u0004 מידה אחרת: אם היתה זו אדמה \u0003חרבה\u0004 — שתירטב האדמה בעומק \u0003טפח, בבינונית — טפחיים, ב\u0004קרקע \u0003עבודה\u0004 (מעובדת וחרושה) — \u0003שלשה טפחים.\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בן אלעזר אומר: אין לך טפח\u0004 של מי גשם שבא \u0003מלמעלה, שאין תהום יוצא לקראתו שלשה טפחים.\u0004 ומקשים: \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 אחרת שיוצא \u0003טפחיים\u0004 בלבד! ומתרצים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003כאן — ב\u0004קרקע \u0003עבודה\u0004 שבה הגשם מחלחל יותר ואין הדבר מהווה סימן לריבוי הגשם, יוצא כנגד טפח שלושה טפחים, ו\u0003כאן בשאינה עבודה\u0004 שאין הגשם מחלחל בה בקלות ואם ירד טפח מלמעלה הרי זה ודאי מפני שירד גשם רב, ובאים טפחיים בלבד מלמטה.","\u0003אמר ר' אלעזר: כשמנסכין את המים בחג\u0004 הסוכות, \u0003תהום\u0004 אחד \u0003אומר לחבירו: אבע\u0004 \u0005[נבע]\u0006 את \u0003מימיך, קול שני ריעים אני שומע,\u0004 קול ניסוך היין וניסוך המים היורדים על המזבח ולכן ראוי שתביא גם אתה מים. \u0003שנאמר: \"תהום אל תהום קורא לקול צנוריך\"\u0004 (תהלים מב, ח), למשמע קול הנסכים הזורמים בצינורות המזבח קוראים התהומות זה אל זה.","\u0003אמר רבה: לדידי חזי לי האי\u0004 \u0005[אני עצמי ראיתי\u0006 את המלאך \u0005הזה]\u0006 ששמו \u0003רידיא\u0004 הממונה על המים, \u0003דמי לעיגלא תלתא ופירסא שפוותיה וקיימא בין תהומא תתאה לתהומא עילאה\u0004 \u0005[\u0006ו\u0005דומה לעגל ששפתיו\u0006 \u0005פתוחות והוא עומד בין תהום תחתון ותהום עליון],\u0006 \u0003לתהומא עילאה\u0004 \u0005[לתהום העליון]\u0006 \u0003אמר ליה\u0004 \u0005[אומר הוא לו]:\u0006 \u0003חשור\u0004 \u0005[הטל]\u0006 את \u0003מימך,\u0004 הגשם, \u0003לתהומא תתאה\u0004 \u0005[לתהום התחתון]\u0006 \u0003אמר ליה\u0004 \u0005[אומר הוא לו]:\u0006 \u0003אבע\u0004 \u0005[נבע]\u0006 את \u0003מימיך, שנאמר: \"הנצנים נראו בארץ\u0004 עת הזמיר הגיע וקול התור נשמע בארצנו\u0003\"\u0004 (שיר השירים ב, יב). \"הניצנים\" רומזים לנסכים הבאים אחת לשנה, כשם שאין האילן מנץ אלא פעם אחת בשנה, ו\"עת הזמיר הגיע\", רמז הוא לבוא עת הזמירות שהוא החג, ו\"תור\" פירושו בארמית שור, והוא המלאך הנראה כעגל ואותו מלאך נראה להם בשעת ניסוך נסכי החג.","שנינו במשנה: \u0003היו מתענין וירדו גשמים קודם הנץ החמה\u0004 — לא ישלימו תעניתם. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003היו מתענין וירדו להם גשמים, קודם הנץ החמה — לא ישלימו\u0004 את התענית, שכל עוד לא הנצה החמה לא חלה עליהם חובת התענית, ומאחר וירדו גשמים שוב אינה חלה. ירדו גשמים \u0003לאחר הנץ החמה — ישלימו,\u0004 אלו \u0003דברי ר' מאיר. ר' יהודה אומר:\u0004 אם ירדו הגשמים \u0003קודם חצות\u0004 היום — \u0003לא ישלימו,\u0004 שזמן סעודה הוא מחצות היום ואילך ולכך אין מניעת אכילה נחשבת כתענית אלא מאותה שעה ואילך, וכאילו לא חלה חובת התענית לפני כן, ומכיון שירדו גשמים טרם חלות התענית — לכך לא ישלימו. ירדו \u0003לאחר חצות — ישלימו.\u0004","\u0003ר' יוסי אומר: קודם תשע שעות\u0004 ביום (שלוש שעות אחר הצהרים) — \u0003לא ישלימו, לאחר תשע שעות — ישלימו, שכן מצינו באחאב מלך ישראל שהתענה מתשע שעות ולמעלה, שנאמר: \"\u0004ויהי כשמוע אחאב את הדברים האלה ויקרע בגדיו וישם שק על בשרו ויצום וישכב בשק ויהלך אט. ויהי דבר ה' אל אליהו התשבי לאמור. \u0003הראית כי נכנע אחאב מלפני\"\u0004 (מלכים א' כא, כז-כט), ולפי המסורת היה זה בשעה התשיעית של היום.","מסופר: \u0003ר' יהודה נשיאה\u0004 \u0005[הנשיא]\u0006 \u0003גזר תעניתא\u0004 \u0005[תענית]\u0006 \u0003וירדו להם גשמים לאחר הנץ החמה, סבר לאשלומינהו\u0004 \u0005[חשב להשלים\u0006 את התענית\u0005],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אמי: קודם חצות ואחר חצות שנינו,\u0004 שהלכה כדברי ר' יהודה. ומסופר עוד: \u0003שמואל הקטן גזר תעניתא\u0004 \u0005[תענית]\u0006 \u0003וירדו להם גשמים קודם הנץ החמה. כסבורין העם לומר: שבחו של צבור הוא,\u0004 שנראה מכאן שהציבור זכאי, שהרי הגשם יורד אף לפני שהתפללו.","\u0003אמר להם: אמשול לכם משל, למה הדבר דומה — לעבד שמבקש פרס\u0004 (מזון, פרנסה) \u0003מרבו, אמר להם\u0004 האדון למשרתיו: \u0003תנו לו\u0004 מה שמבקש \u0003ואל אשמע קולו,\u0004 שאינני רוצה לשמוע אותו. ואף כאן מראה הדבר שאין הקדוש ברוך הוא רוצה לשמוע את תפילתנו.","\u0003שוב שמואל הקטן גזר תעניתא\u0004 \u0005[תענית]\u0006 \u0003וירדו להם גשמים לאחר שקיעת החמה\u0004 בסוף היום, \u0003כסבורים העם לומר\u0004 על פי דבריו של שמואל הקטן ש\u0003שבחו של צבור הוא,\u0004 ששמע ה' את תפילתם כל היום כולו, \u0003אמר להם שמואל: לא שבח של צבור הוא, אלא אמשול לכם משל, למה הדבר דומה — לעבד שמבקש פרס מרבו, ואמר להם\u0004 הרב למשרתיו: \u0003המתינו לו עד שיתמקמק\u0004 (שירקב) \u0003ויצטער, ואחר כך תנו לו,\u0004 ואם כן אף זה — רק גנאי של הציבור הוא.","ושואלים: אם כן \u0003ל\u0004דעת \u0003שמואל הקטן שבחו של צבור היכי דמי\u0004 \u0005[כיצד הוא]?\u0006 ומשיבים: כאשר \u0003אמר\u0004 שליח הציבור \u0003\"משיב הרוח\" ונשב זיקא\u0004 \u0005[ו\u0006מיד \u0005נושבת הרוח],\u0006 \u0003אמר \"מוריד הגשם\" ואתא מיטרא\u0004 \u0005[ו\u0006מיד \u0005יורד הגשם],\u0006 זהו שבחו של ציבור.","שנינו במשנה: \u0003מעשה\u0004 ש\u0003גזרו\u0004 החכמים \u0003תענית בלוד\u0004 וירדו גשמים, ועשו משתה וסעודה ואחר כך אמרו הלל. ושואלים: \u0003ונימא\u0004 \u0005[ושיאמרו]\u0006 \u0003הלל מעיקרא\u0004 \u0005[מתחילה,\u0006 מיד\u0005],\u0006 ולמה חזרו קודם לבתיהם ואמרו הלל רק לאחר שאכלו? \u0003אביי ורבא דאמרי תרווייהו\u0004 \u0005[שאמרו שניהם]\u0006 תשובה לדבר: \u0003לפי שאין אומרים הלל\u0004"]]};
